,"PerspectiveCamera를 사용하여 상호작용하는 카메라 제어 생성","Three.js Scene 객체를 사용하여 몰입형 장면 구축"],"es":["Renderizado de modelos 3D con WebGLRenderer","Creación de controles de cámara interactivos con PerspectiveCamera","Construcción de escenas inmersivas con objetos de escena Three.js"],"fr":["Renderisation de modèles 3D avec WebGLRenderer","Création de contrôles de caméra interactifs avec PerspectiveCamera","Construction de scènes immersives avec des objets de scène Three.js"],"de":["Rendering von 3D-Modellen mit WebGLRenderer","Erstellung interaktiver Kamera-Steuerungen mit PerspectiveCamera","Aufbau immersiver Szenen mit Three.js-Szeneobjekten"],"pt":["Renderização de modelos 3D com WebGLRenderer","Criação de controles de câmera interativos com PerspectiveCamera","Construção de cenas imersivas com objetos Scene do Three.js"],"ru":["Рендеринг 3D-моделей с помощью WebGLRenderer","Создание интерактивных камерных контролей с помощью PerspectiveCamera","Построение иммерсивных сцен с помощью объектов Scene в Three.js"],"ar":["تجسيد نماذج 3D باستخدام WebGLRenderer","إنشاء أدوات تحكم بالكاميرا التفاعلية مع PerspectiveCamera","بناء مشاهد غامرة باستخدام كائنات Scene من Three.js"]},"limitations":{"en":["Requires WebGL-compatible browser","Native JavaScript only","Limited to Three.js ecosystem"],"zh":["需要WebGL兼容的浏览器","仅支持本地JavaScript","仅限Three.js生态系统"],"ja":["WebGL対応ブラウザが必要","ネイティブJavaScriptのみのサポート","Three.jsエコシステムのみの対応"],"ko":["WebGL 호환 브라우저 필요","네이티브 자바스크립트만 지원","Three.js 생태계만 해당"],"es":["Requiere un navegador compatible con WebGL","Solo JavaScript nativo","Limitado al ecosistema Three.js"],"fr":["Nécessite un navigateur compatible avec WebGL","JavaScript natif uniquement","Limité à l''écosystème Three.js"],"de":["Benötigt einen WebGL-kompatiblen Browser","Nur natives JavaScript","Begrenzt auf das Three.js-Ökosystem"],"pt":["Exige navegador compatível com WebGL","JavaScript nativo apenas","Limitado ao ecossistema Three.js"],"ru":["Требует браузера, совместимого с WebGL","Только родной JavaScript","Ограничен экосистемой Three.js"],"ar":["يتطلب متصفح متوافق مع WebGL","جافاسكربت أصلي فقط","محدود بنظام Three.js"]},"version":3},"contentHash":"eb66d52f53f489067d602b9b62df507adb391d8220bdd1a8aae6b73e6cee578a","qualityScore":28}');
