INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('upstash/search-js/upstash/search TypeScript SDK', 'upstash/search TypeScript SDK', 'upstash', 'search-js', 'community', 'upstash/search TypeScript SDK upstash search-js community Upstash 搜索 TypeScript SDK 是一个基于 Upstash REST API 的 HTTP/REST AI 搜索客户端。它提供了简单的搜索和更新功能 Upstash 検索 TypeScript SDK は、Upstash REST API を基盤とする HTTP/REST AI 検索クライアントです。シンプルな検索および更新機能を提供します Upstash 검색 TypeScript SDK는 Upstash REST API를 기반으로 하는 HTTP/REST AI 검색 클라이언트입니다. 단순한 검색 및 업데이트 기능을 제공합니다 El SDK de búsqueda Upstash para TypeScript es una solución de búsqueda AI basada en HTTP/REST que permite a los desarrolladores integrar capacidades de búsqueda avanzadas en sus aplicaciones Le SDK de recherche Upstash pour TypeScript est une solution de recherche AI basée sur HTTP/REST qui permet aux développeurs d''intégrer des capacités de recherche avancées dans leurs applications Das Upstash-Such-SDK für TypeScript ist eine künstliche Intelligenz-Suchlösung basierend auf HTTP/REST, die es Entwicklern ermöglicht, erweiterte Suchfunktionen in ihre Anwendungen zu integrieren A Upstash Search TypeScript SDK é uma biblioteca de busca em AI que permite a integração de funcionalidades de busca avançadas em seus projetos de desenvolvimento de software Upstash Search TypeScript SDK — это библиотека поиска в AI, которая позволяет интегрировать функции продвинутого поиска в ваших проектах разработки программного обеспечения مكتبة Upstash Search TypeScript SDK هي مكتبة بحث الذكاء الاصطناعي التي تمكنك من دمج功能 البحث المتقدم في مشاريع تطوير البرمجيات الخاصة بك An HTTP/REST based AI Search client built on top of Upstash REST API. Upstash 搜索 TypeScript SDK AI 搜索 HTTP/REST API 搜索客户端 Upstash REST API 软件开发工具包 An HTTP/REST based AI Search client built on top of Upstash REST API.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('udecode/better-convex/review', 'community', 'udecode', 'better-convex', 'udecode/better-convex', 'review', 363, 25, 28, '2026-02-25T20:25:59Z', '2026-02-26T08:28:22.937Z', 'b776c143841159778df09c47c9ac44c9daa5ce67669a1e0bcc81a7fae4c4f064', '{"id":"udecode/better-convex/review","name":"review","description":{"zh":"Better Auth + tRPC + Drizzle + TanStack Query的代码审查工具，用于提高代码质量","ja":"Better Auth + tRPC + Drizzle + TanStack Queryのコードレビューツール、コード品質の向上に役立ち","ko":"Better Auth + tRPC + Drizzle + TanStack Query의 코드 리뷰 도구, 코드 품질 향상에 도움","es":"Mejora la autenticación y la gestión de datos con Better Auth, tRPC, Drizzle y TanStack Query. Estos Agentes de IA ofrecen una forma eficiente de gestionar tus datos.","fr":"Améliorez l''authentification et la gestion de données avec Better Auth, tRPC, Drizzle et TanStack Query. Ces outils d''examen IA offrent une manière efficace de gérer vos données.","de":"Verbessern Sie die Authentifizierung und Datenverwaltung mit Better Auth, tRPC, Drizzle und TanStack Query. Diese KI-Tools bieten eine effiziente Möglichkeit, Ihre Daten zu verwalten.","pt":"Melhore a autenticação com tRPC, Drizzle e TanStack Query em Ferramentas de IA. Aprenda a integrar essas tecnologias para melhorar a segurança e a eficiência.","ru":"Улучшите аутентификацию с помощью tRPC, Drizzle и TanStack Query в ИИ Агентах. Узнайте, как интегрировать эти технологии для повышения безопасности и эффективности.","ar":"حسّن عملية المصادقة مع تطبيق Better Auth + tRPC + Drizzle + TanStack Query في أدوات الذكاء الاصطناعي. تعلم كيفية دمج هذه التقنيات لتحسين الأمان والكفاءة.","en":"Better Auth + tRPC + Drizzle + TanStack Query"},"seo":{"title":{"zh":"AI智能代理 - 代码审查工具 Better Auth + tRPC + Drizzle + TanStack Q...","ja":"AIエージェント - コードレビューツール Better Auth + tRPC + Drizzle + TanS...","ko":"AI 에이전트 - 코드 리뷰 도구 Better Auth + tRPC + D