INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('unju-ai/ecc/frontend-slides', 'frontend-slides', 'unju-ai', 'ecc', 'community', 'frontend-slides unju-ai ecc community frontend-slides是一个AI智能代理的前端解决方案，用于构建强大的Web应用 frontend-slidesはAIエージェントのフロントエンドソリューションであり、強力なWebアプリを構築するために使用されます frontend-slides는 AI 에이전트의 프론트엔드 솔루션으로 강력한 Web 애플리케이션을 구축하는 데 사용됩니다 frontend-slides es una herramienta de AI para desarrolladores, basada en un fork de everything-claude-code, diseñada para unju-vm frontend-slides est un outil d''AI pour les développeurs, basé sur un fork de everything-claude-code, conçu pour unju-vm frontend-slides ist ein KI-Tool für Entwickler, basierend auf einem Fork von everything-claude-code, entwickelt für unju-vm O frontend-slides é uma ferramenta de IA para desenvolvedores, criada a partir do fork de everything-claude-code, projetada para trabalhar com o unju-vm. frontend-slides - это инструмент ИИ для разработчиков, созданный на основе форка everything-claude-code, предназначенный для работы с unju-vm. frontend-slides هي أداة ذكاء اصطناعي للمطورين، تم إنشاؤها من فورك everything-claude-code، مصممة للعمل مع unju-vm. Unju fork of everything-claude-code — curated agent harness for unju-vm AI智能代理 前端解决方案 Unju VM Web应用场景 如何使用frontend-slides frontend-slides教程 AI智能代理工具 前端开发框架 Unju VM安装 Unju fork of everything-claude-code — curated agent harness for unju-vm');
