INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aafff623/yihui-vibe-coding-exer/my-react-rules', 'my-react-rules', 'Aafff623', 'yihui-vibe-coding-exer', 'community', 'my-react-rules Aafff623 yihui-vibe-coding-exer community my-react-rules是一个AI代理工具，旨在帮助开发者跟随Yihui完成个人React编程练习。它提供个性化的代码指导、实时反馈和最佳实践建议，使React学习过程更加高效和结构化。 my-react-rulesは、開発者がYihuiと連携して個人のReactプログラミング練習を完了するためのAIエージェントです。パーソナライズされたコードガイダンス、リアルタイムフィードバック、ベストプラクティスを提供します。 my-react-rules는 개발자가 Yihui와 협력하여 개인 React 프로그래밍 실습을 완료하도록 지원하는 AI 에이전트입니다. 개인화된 코드 지도, 실시간 피드백 및 모범 사례를 제공합니다. my-react-rules es una herramienta de IA que ayuda a los desarrolladores a completar sus prácticas de programación personalizadas en React. Proporciona seguimiento y orientación para mejorar las habilidades de codificación con ejercicios prácticos. my-react-rules est un outil d''IA qui aide les développeurs à compléter leurs pratiques de programmation personnalisées en React. Il assure un suivi et des conseils pour améliorer les compétences en codage avec des exercices pratiques. my-react-rules ist ein KI-Tool, das Entwicklern hilft, ihre persönlichen Programmierübungen in React abzuschließen. Es bietet Follow-up und Anleitung, um Coding-Fähigkeiten mit praktischen Übungen zu verbessern. O my-react-rules é um agente de IA projetado para desenvolvedores que desejam praticar programação React. Ele oferece exercícios personalizados e acompanhamento com Yihui para melhorar suas habilidades de codificação. my-react-rules — это ИИ агент, созданный для разработчиков, желающих практиковаться в программировании на React. Он предоставляет персонализированные упражнения и сопровождение от Yihui для улучшения навыков кодирования. my-react-rules هو عميل ذكاء اصطناعي مصمم للمطورين الراغبين في ممارسة برمجة React. يقدم تمارين مخصصة ومتابعة مع Yihui لتحسين مهارات البرمجة لديك. Follow up with up Yihui to complete your personal AI programming practice my-react-rules使用指南 React AI代理工具 Yihui编程练习 AI辅助React开发 my-react-rules安装 React学习工具 代码审查AI工具 my-react-rules替代方案 React vs Vue AI工具 Follow up with up Yihui to complete your personal AI programming practice');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zuiaizengdada/uniapp_vue3_vite_pinia_template/vue-debug-guides', 'community', 'zuiaizengdada', 'uniapp_vue3_vite_pinia_template', 'zuiaizengdada/uniapp_vue3_vite_pinia_template', 'vue-debug-guides', 9, 0, 26, '2026-02-02T04:25:14Z', '2026-03-06T06:48:44.842Z', 'cd4695540dac2fbc16352cbb12f975246b6ac5870e8b82943cbd8bb54edc51ed', '{"id":"zuiaizengdada/uniapp_vue3_vite_pinia_template/vue-debug-guides","name":"vue-debug-guides","description":{"en":"vue-debug-guides provides a comprehensive debugging solution for Vue 3 applications, helping developers identify and resolve runtime issues, warnings, and async failures. Ideal for developers working with uniapp, vite, pinia, and tailwindcss.","zh":"此项目提供 Vue 3 调试和错误处理的指南，包括 Reactivity 和 Watchers 的调试","ja":"このプロジェクトでは、Vue 3 のデバッグとエラーハンドリングのガイドを提供します","ko":"이 프로젝트에서는 Vue 3 디버깅 및 에러 핸들링에 대한 가이드를 제공합니다","es":"Esta guía de depuración de Vue 3 proporciona consejos y trucos para solucionar errores y warnings en tiempo de ejecución, incluyendo reactividad y watchers","fr":"Ce guide de débogage Vue 3 fournit des conseils et des astuces pour résoudre les erreurs et les warnings en temps de execution, incluant la réactivité et les watchers","de":"Dieser Vue 3-Debugging-Leitfaden bietet Tipps und Tricks, um Laufzeitfehler und Warnungen zu beheben, einschließlich Reaktivität und Watchern","pt":"O guia de depuração Vue 3 fornece dicas e técnicas para solucionar problemas em aplicações Vue 3, incluindo reatividade e watchers.","ru":"Руководство по отладке Vue 3 предоставляет советы и техники для решения проблем в приложениях Vue 3, включая реактивность и watchers.","ar":"يدل دليل التصحيح الفني لفيو 3 على نصائح و تقنيات لحل المشاكل في تطبيقات فيو 3، بما في ذلك التفاعل و المشاهدة."},"seo":{"title":{"en":"vue-debug-guides: Debugging Setup Guide for AI Agents","zh":"Vue 3 调试指南：错误处理和性能