INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('o1xhack/telegram-watch/telegram-watch-dev', 'telegram-watch-dev', 'o1xhack', 'telegram-watch', 'community', 'telegram-watch-dev o1xhack telegram-watch community cli monitoring privacy python reporting selfhosted sqlite telegram telegram-client telethon watcher The telegram-watch-dev skill is a fully local Telegram watcher that monitors specific users and captures messages into SQLite. It benefits developers who need to track Telegram activity. Telegram_WATCH_DEV是一个监控Telegram用户和群组的工具，使用Telethon和SQLite TelegramWatchDevは、TelethonとSQLiteを使用してTelegramユーザーとグループを監視するツールです Telegram_WATCH_DEV는 Telethon과 SQLite를 사용하여 Telegram 사용자와 그룹을 모니터링하는 도구입니다 Telegram-watch-dev es una herramienta de monitoreo de Telegram que utiliza Telethon y SQLite para capturar mensajes y medios de usuarios y canales específicos. Telegram-watch-dev est un outil de surveillance Telegram qui utilise Telethon et SQLite pour capturer des messages et des médias d''utilisateurs et de canaux spécifiques. Telegram-watch-dev ist ein Überwachungstool für Telegram, das Telethon und SQLite verwendet, um Nachrichten und Medien von bestimmten Nutzern und Kanälen zu erfassen. O telegram-watch-dev é uma ferramenta de monitoramento de Telegram que usa Telethon para capturar mensagens e mídia de usuários e canais específicos e gerar relatórios em HTML telegram-watch-dev — это инструмент для мониторинга Telegram, который использует Telethon для захвата сообщений и медиа конкретных пользователей и каналов и генерации отчетов в HTML telegram-watch-dev هو أداة مراقبة تليجرام تستخدم Telethon لالتقاط الرسائل والوسائط من المستخدمين والقنوات المحددة وتوليد تقارير بالصيغة HTML how to use telegram-watch-dev telegram-watch-dev setup guide telegram-watch-dev alternative telegram-watch-dev vs telethon telegram-watch-dev install what is telegram-watch-dev telegram-watch-dev tutorial telegram-watch-dev documentation telegram client for monitoring Telegram监控 Telethon SQLite Python CLI 监控工具 Telegram用户监控 Telegram群组监控 AIエージェント Monitors specific users in target groups/channels using Telethon Captures messages and media into SQLite database Generates periodic HTML reports and pushes them to a control chat Follows a mandatory requirements workflow with approved requests Utilizes a self-hosted solution for privacy and security telegram-watch-dev is a Telethon-powered watcher that monitors Telegram groups and channels, capturing messages and media into SQLite.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bh213/hx-multianim/precommit', 'community', 'bh213', 'hx-multianim', 'bh213/hx-multianim', 'precommit', 6, 0, 26, '2026-03-03T22:59:02Z', '2026-03-06T06:53:22.083Z', 'ed004f4d5614083932863864c4e378245b7653347fe366d55bd5215ca19e9eed', '{"id":"bh213/hx-multianim/precommit","name":"precommit","description":{"en":"precommit is a pixel perfect animation/UI library for Heaps, designed to streamline development. It benefits developers working with Heaps by providing a robust pre-commit workflow.","zh":"Precommit 是一个用于 Heaps 的动画/UI 库，提供 pixel perfect 动画效果。通过 Precommit 进行代码检查和优化，可以提升开发效率","ja":"Precommit は Heaps 用のアニメーション/UI ライブラリで、ピクセルパーフェクトなアニメーション効果を提供します。Precommit を使用してコードをチェックおよび最適化することで、開発効率を向上させることができます","ko":"Precommit는 Heaps를 위한 애니메이션/UI 라이브러리로서 픽셀퍼펙트한 애니메이션 효과를 제공합니다. Precommit를 사용하여 코드를 검사 및 최적화하면 개발 효율성을 향상시킬 수 있습니다","es":"precommit es una biblioteca de animaciones/UI perfectas para Heaps. Permite a los desarrolladores crear experiencias de usuario fluidas y personalizadas.","fr":"precommit est une bibliothèque d''animations/UI parfaites pour Heaps. Elle permet aux développeurs de créer des expériences utilisateur fluides et personnalisées.","de":"precommit ist eine Bibliothek für perfekte Animationen/UI für Heaps. Sie ermöglicht es Entwicklern, flüssige und personalisierte Benutzeroberflächen zu erstellen.","pt":"O Precommit é uma biblioteca de animação/UI para Heaps que permite a criação de animações perfeitas. Configure-o facilmente com nosso guia.","ru":"Precommit - это библиотека анимации/UI для Heaps, которая позволяет создавать пиксельную анимацию. Настройте его легко с нашим руководством - ИИ Агенты.","ar":"Precommit هو مكتبة للرسوم المتحركة/WI ل Heaps التي تمكن من إنشاء رسوم متحركة مثالية. أعدّه بسهولة مع دليلنا - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"precommit: Setup Guide for Heaps Animation/UI Library | A...","zh":"Precommit 设置指南：Heaps 动画/UI 库最佳实践","ja":"Precommit セットアップガイド：Heaps アニメーション/UI ライブラリのベストプラクティス","ko":"Precommit 설정 가이드: Heaps 애니메이션/UI 라이브러리 최적화","es":"Guía de configuración de precommit para animaciones perfe...","fr":"Configurer precommit pour des animations parfaites","de":"Einrichtungsleitfaden für precommit mit perfekten Animati...","pt":"Guia de Configuração do Precommit para Animações Perfeitas","ru":"Настройка Precommit для Пиксельной Анимации - ИИ Агенты","ar":"إعداد Precommit للرسوم المتحركة المثالية - أدوات الذكاء ا..."},"description":{"en":"Discover how to leverage precommit for pixel-perfect animations and UI in Heaps. Learn the pre-commit workflow and optimize your development process now!","zh":"了解如何使用 Precommit 进行 Heaps 动画/UI 库的代码检查和优化，提升开发效率","ja":"Precommit を使用して Heaps アニメーション/UI ライブラリのコードをチェックおよび最適化し、開発効率を向上させる方法を学びます","ko":"Precommit를 사용하여 Heaps 애니메이션/UI 라이브러리의 코드를 검사 및 최적화하여 개발 효율성을 향상시키는 방법을 알아보세요","es":"Aprende a configurar precommit para crear animaciones perfectas con Heaps. Sigue nuestros pasos para una implementación exitosa.","fr":"Découvrez comment configurer precommit pour des animations parfaites avec Heaps. Suivez nos étapes pour une mise en œuvre réussie.","de":"Erfahren Sie, wie Sie precommit für perfekte Animationen mit Heaps einrichten. Befolgen Sie unsere Schritte für eine erfolgreiche Implementierung.","pt":"Aprenda a configurar o Precommit para criar animações perfeitas com a biblioteca Heaps. Siga nosso guia passo a passo.","ru":"Узнайте, как настроить Precommit для создания пиксельной анимации с помощью библиотеки Heaps. Следуйте нашему пошаговому руководству - ИИ Агенты.","ar":"تعلم كيفية إعداد Precommit لإنشاء رسوم متحركة مثالية باستخدام مكتبة Heaps. اتبع دليلنا خطوة بخطوة - أدوات الذكاء الاصطناعي"},"definition":{"en":"precommit is a technical workflow tool that performs checks and updates, such as reviewing changes with git log and git diff, and maintaining a CHANGELOG.md file.","zh":"Precommit 是一个用于 Heaps 的动画/UI 库，提供代码检查和优化功能","ja":"Precommit は Heaps 用のアニメーション/UI ライブラリで、コードチェックおよび最適化機能を提供します","ko":"Precommit는 Heaps를 위한 애니메이션/UI 라이브러리로서 코드 검사 및 최적화 기능을 제공합니다","es":"precommit es una herramienta de desarrollo que ayuda a los desarrolladores a crear animaciones perfectas con Heaps.","fr":"precommit est un outil de développement qui aide les développeurs à créer des animations parfaites avec Heaps.","de":"precommit ist ein Entwicklungstool, das Entwicklern hilft, perfekte Animationen mit Heaps zu erstellen.","pt":"O Precommit é uma ferramenta de pré-commit que executa verificações antes de confirmar alterações no código.","ru":"Precommit - это инструмент предкоммита, который выполняет проверки перед фиксацией изменений в коде - ИИ Агенты.","ar":"Precommit هو أداة ما قبل الإلتزام التي تنفذ عمليات التحقق قبل إلتزام التغييرات في الكود - أدوات الذكاء الاصطناعي"},"features":{"en":["Performs pre-commit checks using git log --oneline and git diff --stat","Reviews changes with git diff HEAD for detailed analysis","Updates CHANGELOG.md to document new features, fixes, and breaking changes","Analyzes changes to understand additions, modifications, and fixes","Supports concise reporting of findings"],"zh":["代码检查和优化","Git 日志和 diff 分析","CHANGELOG.md 更新","Pre-commit 工作流","Heaps 动画/UI 库集成"],"ja":["コードチェックおよび最適化","Git ログおよび diff 分析","CHANGELOG.md 更新","Pre-commit ワークフロー","Heaps アニメーション/UI ライブラリ統合"],"ko":["코드 검사 및 최적화","Git 로그 및 diff 분석","CHANGELOG.md 업데이트","Pre-commit 워크플로우","Heaps 애니메이션/UI 라이브러리 통합"],"es":["_compatibilidad con Heaps","animaciones perfectas","personalización de la interfaz de usuario","verificación de cambios con git log","actualización de CHANGELOG.md"],"fr":["compatibilité avec Heaps","animations parfaites","personnalisation de l''interface utilisateur","vérification des modifications avec git log","mise à jour de CHANGELOG.md"],"de":["Kompatibilität mit Heaps","perfekte Animationen","Anpassung der Benutzeroberfläche","Überprüfung von Änderungen mit git log","Aktualisierung von CHANGELOG.md"],"pt":["Verificação de alterações no código com git log e git diff","Atualização do arquivo CHANGELOG.md","Análise de alterações para entender o que foi adicionado ou alterado","Suporte à biblioteca Heaps para animações perfeitas","Execução de verificações pré-commit para garantir a qualidade do código"],"ru":["Проверка изменений в коде с помощью git log и git diff - ИИ Агенты","Обновление файла CHANGELOG.md","Анализ изменений для понимания того, что было добавлено или изменено","Поддержка библиотеки Heaps для пиксельной анимации","Выполнение предкоммит-чеков для обеспечения качества кода"],"ar":["التحقق من التغييرات في الكود باستخدام git log و git diff - أدوات الذكاء الاصطناعي","تحديث ملف CHANGELOG.md","تحليل التغييرات لفهم ما تم إضافته أو تعديله","دعم مكتبة Heaps لإنشاء رسوم متحركة مثالية","تنفيذ عمليات التحقق قبل الإلتزام لضمان جودة الكود"]},"keywords":{"en":["how to use precommit","precommit setup guide","precommit for Heaps","what is precommit","precommit vs other animation libraries","precommit install","precommit alternative","precommit workflow","precommit for pixel perfect animation"],"zh":["Precommit","Heaps","动画/UI 库","代码检查","优化","Git","CHANGELOG.md","AIエージェント","代码开发工具"],"ja":["Precommit","Heaps","アニメーション/UI ライブラリ","コードチェック","最適化","Git","CHANGELOG.md","AIエージェント","コード開発ツール"],"ko":["Precommit","Heaps","애니메이션/UI 라이브러리","코드 검사","최적화","Git","CHANGELOG.md","AI 에이전트","코드 개발 도구"],"es":["precommit","Heaps","animaciones perfectas","herramientas de desarrollo","git log","CHANGELOG.md","desarrollo de software","interfaz de usuario personalizada"],"fr":["precommit","Heaps","animations parfaites","outils de développement","git log","CHANGELOG.md","développement de logiciels","interface utilisateur personnalisée"],"de":["precommit","Heaps","perfekte Animationen","Entwicklungstools","git log","CHANGELOG.md","Softwareentwicklung","benutzeroberfläche anpassen"],"pt":["precommit","animação perfeita","biblioteca Heaps","git log","git diff","CHANGELOG.md","pré-commit","qualidade do código","desenvolvimento de software"],"ru":["precommit","пиксельная анимация","библиотека Heaps","git log","git diff","CHANGELOG.md","предкоммит","качество кода","разработка программного обеспечения","ИИ Агенты"],"ar":["precommit","رسوم متحركة مثالية","مكتبة Heaps","git log","git diff","CHANGELOG.md","ما قبل الإلتزام","جودة الكود","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"bh213","repo":"hx-multianim","repoPath":"bh213/hx-multianim","stars":6,"forks":0,"updatedAt":"2026-03-03T22:59:02Z","topics":[],"category":"community","skillMd":{"name":"precommit","description":"Run pre-commit documentation and code hygiene checks before committing. Reviews changes since last commit, updates changelog/docs/todos, checks for missing items, and suggests a commit message.","bodyPreview":"# Pre-Commit Checks\n\nPerform the following pre-commit workflow. Report findings concisely.\n\n## 1. Review Changes\n\n- Run `git log --oneline -5` to see recent commits\n- Run `git diff --stat HEAD` to see changed files\n- Run `git diff HEAD` to see the full diff\n- Analyze all changes to understand what was added/changed/fixed\n\n## 2. Update CHANGELOG.md\n\n- Read `CHANGELOG.md` and check if any changes in the diff are NOT yet documented\n- Add entries for new features, fixes, and breaking changes under t","body":"# Pre-Commit Checks\n\nPerform the following pre-commit workflow. Report findings concisely.\n\n## 1. Review Changes\n\n- Run `git log --oneline -5` to see recent commits\n- Run `git diff --stat HEAD` to see changed files\n- Run `git diff HEAD` to see the full diff\n- Analyze all changes to understand what was added/changed/fixed\n\n## 2. Update CHANGELOG.md\n\n- Read `CHANGELOG.md` and check if any changes in the diff are NOT yet documented\n- Add entries for new features, fixes, and breaking changes under the current dev version section\n- Follow the existing format (bullet points with bold feature name and description)\n\n## 3. Update Documentation\n\n- Check if changes affect `.manim` syntax or builder/codegen API\n- If so, update `docs/manim-reference.md` (quick-lookup reference)\n- If substantial, also update `docs/manim.md` (detailed documentation)\n- Update `CLAUDE.md` if architectural patterns or key instructions changed\n\n## 4. Clean Up TODO Files\n\n- Read `todo/TODO.md` and other `todo/*.md` files\n- Remove items that have been completed (check against CHANGELOG and recent commits)\n- Do NOT remove items that are still pending or in-progress\n\n## 5. Check for Missing Items\n\nVerify:\n- No sensitive files (.env, credentials) in the diff\n- All reference images updated if visual tests changed\n- No inconsistencies between code changes and documentation\n- MEMORY.md is up to date with any new patterns or pitfalls discovered. \n- Check if anything can be removed from MEMORY.md because it is no longer relevant. Ask user if unsure.\n\n## 6. Suggest Commit Message\n\n- Follow the project''s commit message style (see recent commits)\n- Format: `area: short description` on first line\n- Add bullet points for significant changes in the body\n- Keep the first line under 72 characters\n- Do not include TODO file changes.\n\n## 7. Report Summary\n\nPresent a summary table:\n- Files changed (count)\n- Changelog entries added\n- Docs updated\n- TODOs cleaned\n- Any issues found\n- Suggested commit message\n\nDo NOT create the commit at all. Present the summary and user will commit.\n"},"lastSynced":"2026-03-06T06:53:22.083Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined pre-commit workflows and pixel-perfect animation/UI libraries like Heaps.","zh":"适用于需要简化的预提交工作流和像 Heaps 这样的像素级动画/UI 库的开发代理。","ja":"Heaps のようなストリームライン化されたプレコミットワークフローとピクセルパーフェクトなアニメーション/UI ライブラリを必要とする開発エージェントに最適です。","ko":"Heaps 같은 스트림 라인화된 프리 커밋 워크 플로우와 픽셀 완벽한 애니메이션/UI 라이브러리를 필요로 하는 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo que requieren flujos de trabajo de pre-compromiso simplificados y bibliotecas de animación/UI de píxeles perfectos como Heaps.","fr":"Idéal pour les agents de développement nécessitant des flux de travail de pré-validation simplifiés et des bibliothèques d''animation/UI de pixels parfaits comme Heaps.","de":"Ideal für Entwicklungsmittel, die optimierte Vorcommit-Arbeitsabläufe und pixelgenaue Animations-/UI-Bibliotheken wie Heaps erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem fluxos de trabalho de pré-compromisso simplificados e bibliotecas de animação/UI perfeitas em pixels, como Heaps.","ru":"Идеально для агентов разработки, требующих оптимизированных предварительных коммитов и библиотек анимации/интерфейса пользователя с идеальным качеством пикселей, таких как Heaps.","ar":"مثالي لعميل التطوير الذي يحتاج إلى تدفقات عمل مدمجة قبل الالتزام ووكالات الرسوم المتحركة/الواجهة المستخدمة بدقة البكسل المثالية مثل Heaps."},"recommendation":{"en":"Empowers agents to automate pre-commit checks using Git commands like `git log` and `git diff`, ensuring robust pre-commit workflows and accurate CHANGELOG.md updates, leveraging Heaps for pixel-perfect animations.","zh":"赋予代理人使用 Git 命令（如 `git log` 和 `git diff`）自动执行预提交检查的能力，确保强大的预提交工作流和准确的 CHANGELOG.md 更新，利用 Heaps 实现像素级完美的动画。","ja":"Git コマンド（例：`git log`、`git diff`）を使用してプレコミットチェックを自動化するエージェントを可能にし、強力なプレコミットワークフローと正確な CHANGELOG.md 更新を保証し、Heaps を使用してピクセルパーフェクトなアニメーションを実現します。","ko":"Git 명령어(`git log`, `git diff` 등)을 사용하여 프리 커밋 체크를 자동화할 수 있는 에이전트를 제공하여 강력한 프리 커밋 워크 플로우와 정확한 CHANGELOG.md 업데이트를 보장하며, Heaps를 사용하여 픽셀 완벽한 애니메이션을 구현합니다.","es":"Habilita a los agentes a automatizar las verificaciones de pre-compromiso utilizando comandos de Git como `git log` y `git diff`, garantizando flujos de trabajo de pre-compromiso robustos y actualizaciones precisas de CHANGELOG.md, aprovechando Heaps para animaciones de píxeles perfectos.","fr":"Permet aux agents d''automatiser les vérifications de pré-validation en utilisant des commandes Git comme `git log` et `git diff`, garantissant des flux de travail de pré-validation robustes et des mises à jour précises de CHANGELOG.md, en exploitant Heaps pour des animations de pixels parfaits.","de":"Ermöglicht es Agenten, Vorcommit-Prüfungen mit Git-Befehlen wie `git log` und `git diff` zu automatisieren, um robuste Vorcommit-Arbeitsabläufe und genaue Aktualisierungen von CHANGELOG.md sicherzustellen und Heaps für pixelgenaue Animationen zu nutzen.","pt":"Permite que os agentes automatizem as verificações de pré-compromisso usando comandos Git, como `git log` e `git diff`, garantindo fluxos de trabalho de pré-compromisso robustos e atualizações precisas do CHANGELOG.md, aproveitando Heaps para animações perfeitas em pixels.","ru":"Наделяет агентов возможностью автоматизировать предварительные коммиты с помощью команд Git, таких как `git log` и `git diff`, обеспечивая надежные предварительные коммиты и точные обновления CHANGELOG.md, используя Heaps для анимаций с идеальным качеством пикселей.","ar":"يمنح الوكيل القدرة على توفير عمليات اختبار مسبقة للإلتزام باستخدام أوامر Git مثل `git log` و `git diff` ، مما يضمن تدفقات عمل قوية قبل الالتزام وتحديثات دقيقة لCHANGELOG.md ، مستفيداً من Heaps للحصول على رسوم متحركة بدقة البكسل المثالية."},"useCases":{"en":["Automating pre-commit checks with Git","Updating CHANGELOG.md for new features and fixes","Analyzing code changes with `git diff --stat HEAD`"],"zh":["使用 Git 自动执行预提交检查","更新 CHANGELOG.md 以记录新功能和修复","使用 `git diff --stat HEAD` 分析代码更改"],"ja":["Git を使用してプレコミットチェックを自動化する","CHANGELOG.md を更新して新機能と修正を記録する","`git diff --stat HEAD` を使用してコード変更を分析する"],"ko":["Git를 사용하여 프리 커밋 체크를 자동화하는 것","CHANGELOG.md를 업데이트하여 새로운 기능과 수정 사항을 기록하는 것","`git diff --stat HEAD`를 사용하여 코드 변경 사항을 분석하는 것"],"es":["Automatizar las verificaciones de pre-compromiso con Git","Actualizar CHANGELOG.md para nuevas características y correcciones","Analizar cambios de código con `git diff --stat HEAD`"],"fr":["Automatiser les vérifications de pré-validation avec Git","Mettre à jour CHANGELOG.md pour les nouvelles fonctionnalités et correctifs","Analyser les modifications de code avec `git diff --stat HEAD`"],"de":["Automatisierung von Vorcommit-Prüfungen mit Git","Aktualisieren von CHANGELOG.md für neue Funktionen und Korrekturen","Analyse von Codeänderungen mit `git diff --stat HEAD`"],"pt":["Automatizar verificações de pré-compromisso com Git","Atualizar CHANGELOG.md para novos recursos e correções","Analise de alterações de código com `git diff --stat HEAD`"],"ru":["Автоматизация предварительных коммитов с помощью Git","Обновление CHANGELOG.md для новых функций и исправлений","Анализ изменений кода с помощью `git diff --stat HEAD`"],"ar":["توفير عمليات اختبار مسبقة للإلتزام مع Git","تحديث CHANGELOG.md للسمات الجديدة والتصحيحات","تحليل التغييرات في الشفرة باستخدام `git diff --stat HEAD`"]},"limitations":{"en":["Requires Git installation","Designed specifically for Heaps","Needs access to CHANGELOG.md file"],"zh":["需要 Git 安装","专门为 Heaps 设计","需要访问 CHANGELOG.md 文件"],"ja":["Git のインストールが必要","Heaps 専用に設計されている","CHANGELOG.md ファイルへのアクセスが必要"],"ko":["Git 설치가 필요함","Heaps専용으로 설계됨","CHANGELOG.md 파일에 접근할 수 있어야 함"],"es":["Requiere instalación de Git","Diseñado específicamente para Heaps","Necesita acceso al archivo CHANGELOG.md"],"fr":["Nécessite l''installation de Git","Conçu spécifiquement pour Heaps","Nécessite l''accès au fichier CHANGELOG.md"],"de":["Benötigt Git-Installation","Speziell für Heaps konzipiert","Benötigt Zugriff auf die Datei CHANGELOG.md"],"pt":["Exige instalação do Git","Projetado especificamente para Heaps","Necessita acesso ao arquivo CHANGELOG.md"],"ru":["Требует установки Git","Разработан специально для Heaps","Требует доступа к файлу CHANGELOG.md"],"ar":["يتطلب تركيب Git","صُمِّم خصيصاً من أجل Heaps","يحتاج إلى الوصول إلى ملف CHANGELOG.md"]},"version":4},"contentHash":"ed004f4d5614083932863864c4e378245b7653347fe366d55bd5215ca19e9eed","qualityScore":26}');
