INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tvararu/tuicraft/tuicraft', 'tuicraft', 'tvararu', 'tuicraft', 'community', 'tuicraft tvararu tuicraft community tuicraft is a CLI client for World of Warcraft 3.3.5a, allowing players to chat from their terminal. It benefits WoW players seeking convenience and efficiency. tuicraft是一个CLI客户端，允许您从终端聊天 WoW 3.3.5a。它使用一个后台守护进程维持游戏连接和缓冲事件 tuicraftは、ターミナルからWoW 3.3.5aでチャットできるCLIクライアントです。バックグラウンドのデーモンがゲーム接続とイベントバッファを維持します tuicraft는 터미널에서 WoW 3.3.5a에서 채팅할 수 있는 CLI 클라이언트입니다. 백그라운드 데몬이 게임 연결과 이벤트 버퍼링을 유지합니다 tuicraft es un cliente CLI para World of Warcraft 3.3.5a que permite enviar mensajes y verificar el estado de la conexión. Incluye un daemon en segundo plano que mantiene la conexión y almacena eventos. tuicraft est un client CLI pour World of Warcraft 3.3.5a qui permet d''envoyer des messages et de vérifier l''état de la connexion. Il comprend un démon en arrière-plan qui maintient la connexion et stocke les événements. tuicraft ist ein CLI-Client für WoW 3.3.5a, der das Senden von Nachrichten und die Überprüfung des Verbindungszustands ermöglicht. Er umfasst einen Hintergrund-Daemon, der die Verbindung aufrechterhält und Ereignisse puffert. O tuicraft é um cliente CLI para WoW 3.3.5a que permite enviar mensagens e verificar status de conexão. Ele usa um daemon em segundo plano para manter a conexão e bufferizar eventos ИИ Агент tuicraft - это клиент для WoW 3.3.5a, который позволяет отправлять сообщения и проверять статус соединения. Он использует фоновый демон для поддержания соединения и буферизации событий tuicraft هو عميل واجهة سطر الأوامر للعبة WoW 3.3.5a الذي يسمح بإرسال الرسائل وفتح حالة الاتصال. يستخدم ديمونًا في الخلفية للحفاظ على الاتصال وتخزين الأحداث how to use tuicraft tuicraft setup guide tuicraft vs wow chat tuicraft install what is tuicraft wow 3.3.5a terminal chat tuicraft alternative tuicraft documentation tuicraft WoW 3.3.5a CLI客户端 终端聊天 游戏连接 事件缓冲 AIエージェント 游戏开发 Starts automatically on first use and stays running for 30 minutes of inactivity Supports sending messages via ''tuicraft send'' command Allows yelling messages with ''-y'' flag, e.g., ''tuicraft send -y "message"'' Enables private messages with ''-p'' flag, e.g., ''tuicraft send -p "message"'' Provides status check via ''tuicraft status'' command, returning CONNECTED or an error tuicraft is a background daemon that maintains the game connection and buffers events, enabling terminal-based chat in WoW 3.3.5a.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('claushaas/palette-kit/exporters-builder', 'community', 'claushaas', 'palette-kit', 'claushaas/palette-kit', 'exporters-builder', 3, 0, 26, '2026-02-14T02:06:38Z', '2026-03-06T07:00:31.512Z', '44c4e44cbb38c3f9024612dfb8e1609028c9f941ce051eb81dd5c24b0a31f9b5', '{"id":"claushaas/palette-kit/exporters-builder","name":"exporters-builder","description":{"en":"The exporters-builder skill enables developers to implement export functions with CSS variables and JSON output formatting. It benefits developers working with v0.3 spec.","zh":"Exporters Builder是一种用于实现导出功能和输出格式化的技能，支持CSS变量和JSON输出","ja":"Exporters Builderは、CSS変数とJSON出力をサポートする導出機能と出力フォーマットを実装するスキルです","ko":"Exporters Builder는 CSS 변수와 JSON 출력을 지원하는 출력 형식 지정 및 데이터 내보내기 기능을 구현하는 스킬입니다","es":"Exporters-builder es una habilidad para implementar funciones de exportación de CSS variables y JSON con opciones de salida personalizadas","fr":"Exporters-builder est une compétence pour mettre en place des fonctions d''exportation de variables CSS et JSON avec des options de sortie personnalisées","de":"Exporters-builder ist eine Fähigkeit zur Implementierung von Exportfunktionen für CSS-Variablen und JSON mit benutzerdefinierten Ausgabemöglichkeiten","pt":"O Exporters Builder é uma ferramenta para implementar funções de exportação com CSS variables e JSON, incluindo formatação de saída e testes.","ru":"Exporters Builder - это инструмент для реализации функций экспорта с помощью CSS переменных и JSON, включая форматирование вывода и тестирование для ИИ Агентов.","ar":"Exporters Builder هو أداة لتنفيذ وظائف التصدير باستخدام متغيرات CSS و JSON، بما في ذلك تنسيق الإخراج والاختبارات لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"exporters-builder: Setup Guide for AI Agents | AI Agent S...","zh":"AIエージェント导航：Exporters Builder 设置指南","ja":"AIエージェント：Exporters Builder ベストプラクティス","ko":"AI 도구: Exporters Builder 구축 가이드","es":"Guía de configuración de exporters-builder para funciones...","fr":"Guide de mise en place de exporters-builder pour les fonc...","de":"Einrichtungsleitfaden für exporters-builder zur Implement...","pt":"Guia de Configuração do Exporters Builder para Desenvolve...","ru":"Руководство по настройке Exporters Builder для разработчи...","ar":"دليل إعداد Exporters Builder لمنشئي أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient export functions with exporters-builder. Learn how to implement CSS variables and JSON output formatting per v0.3 spec and take your develop...","zh":"实现导出功能和输出格式化，了解Exporters Builder的工作流和守护规则","ja":"Exporters Builderを使用して導出機能と出力フォーマットを実装する方法を学ぶ","ko":"Exporters Builder로 구축하여 출력 형식 지정 및 데이터 내보내기 기능 구현","es":"Aprende a implementar exporters-builder para funciones de exportación de CSS variables y JSON con opciones de salida personalizadas","fr":"Découvrez comment mettre en place exporters-builder pour les fonctions d''exportation de variables CSS et JSON avec des options de sortie personnalisées","de":"Erfahren Sie, wie Sie exporters-builder für die Implementierung von Exportfunktionen für CSS-Variablen und JSON mit benutzerdefinierten Ausgabemöglichkeiten ...","pt":"Aprenda a implementar funções de exportação com CSS variables e JSON utilizando o Exporters Builder, incluindo formatação de saída e testes","ru":"Узнайте, как реализовать функции экспорта с помощью CSS переменных и JSON, используя Exporters Builder, включая форматирование вывода и тестирование для ИИ А...","ar":"تعرف على كيفية تنفيذ وظائف التصدير باستخدام متغيرات CSS و JSON باستخدام Exporters Builder، بما في ذلك تنسيق الإخراج والاختبارات لأدوات الذكاء الاصطناعي"},"definition":{"en":"exporters-builder is a skill that facilitates the implementation of export functions, including CSS variables and JSON output formatting, according to the v0.3 specification.","zh":"Exporters Builder是一种AI工具，用于构建导出功能和输出格式化","ja":"Exporters Builderは、導出機能と出力フォーマットを構築するためのAIエージェントです","ko":"Exporters Builder는 출력 형식 지정 및 데이터 내보내기 기능을 구축하는 AI 도구입니다","es":"Exporters-builder es una habilidad de AI que permite implementar funciones de exportación de datos","fr":"Exporters-builder est une compétence d''IA qui permet de mettre en place des fonctions d''exportation de données","de":"Exporters-builder ist eine KI-Fähigkeit, die die Implementierung von Exportfunktionen für Daten ermöglicht","pt":"O que é Exporters Builder? É uma ferramenta para desenvolvedores que implementa funções de exportação com CSS variables e JSON.","ru":"Что такое Exporters Builder? Это инструмент для разработчиков ИИ Агентов, реализующий функции экспорта с помощью CSS переменных и JSON.","ar":"ما هو Exporters Builder؟ إنه أداة لمنشئي أدوات الذكاء الاصطناعي التي تنفذ وظائف التصدير باستخدام متغيرات CSS و JSON."},"features":{"en":["Implements exporters in src/export with OutputOptions for precision and formats","Includes optional meta data only when requested","Supports minimal snapshot-like tests for CSS vars and JSON output","Preserves the public API surface","Reads src/planning/spec-v0.3.md and relevant phase in src/planning/roadmap-v0.3.md"],"zh":["支持CSS变量和JSON输出","实现输出格式化","可选的meta数据包含","最小的快照测试","遵守v0.3规范"],"ja":["CSS変数とJSON出力をサポート","出力フォーマットを実装","オプションのmetaデータを含む","最小のスナップショットテスト","v0.3仕様に準拠"],"ko":["CSS 변수와 JSON 출력 지원","출력 형식 지정 구현","옵션 메타 데이터 포함","최소한의 스냅샷 테스트","v0.3 사양 준수"],"es":["Implementación de funciones de exportación de CSS variables","Soporte para JSON con opciones de salida personalizadas","Inclusión de metadatos opcionales","Pruebas de instantáneas para CSS vars y JSON","Compatibilidad con la especificación v0.3"],"fr":["Mise en place de fonctions d''exportation de variables CSS","Prise en charge de JSON avec des options de sortie personnalisées","Inclusion de métadonnées facultatives","Tests de captures instantanées pour les variables CSS et JSON","Compatibilité avec la spécification v0.3"],"de":["Implementierung von Exportfunktionen für CSS-Variablen","Unterstützung für JSON mit benutzerdefinierten Ausgabemöglichkeiten","Einclusion von optionalen Metadaten","Schnappschuss-Tests für CSS-Variablen und JSON","Kompatibilität mit der Spezifikation v0.3"],"pt":["Implementação de funções de exportação com CSS variables","Suporte a JSON para exportação de dados","Formatação de saída personalizável","Testes de unidade para garantir a qualidade do código","Preservação da API pública"],"ru":["Реализация функций экспорта с помощью CSS переменных","Поддержка JSON для экспорта данных","Настраиваемое форматирование вывода","Модульные тесты для обеспечения качества кода","Сохранение публичного API"],"ar":["تنفيذ وظائف التصدير باستخدام متغيرات CSS","دعم JSON للتصدير البيانات","تنسيق الإخراج المخصص","اختبارات الوحدة لضمان جودة الشفرة","الحفاظ على واجهة برمجة التطبيقات العامة"]},"keywords":{"en":["how to use exporters-builder","exporters-builder setup guide","exporters-builder alternative","exporters-builder vs other export tools","what is exporters-builder","exporters-builder install","exporters-builder implementation","exporters-builder and CSS variables","exporters-builder and JSON output formatting"],"zh":["AI工具","导出功能","输出格式化","CSS变量","JSON输出","Exporters Builder","v0.3规范","输出选项"],"ja":["AIエージェント","導出機能","出力フォーマット","CSS変数","JSON出力","Exporters Builder","v0.3仕様","出力オプション"],"ko":["AI 도구","출력 형식 지정","데이터 내보내기","CSS 변수","JSON 출력","Exporters Builder","v0.3 사양","출력 옵션"],"es":["exporters-builder","funciones de exportación","CSS variables","JSON","opciones de salida","metadatos","pruebas de instantáneas","especificación v0.3","herramientas de AI"],"fr":["exporters-builder","fonctions d''exportation","variables CSS","JSON","options de sortie","métadonnées","tests de captures instantanées","spécification v0.3","outils d''IA"],"de":["exporters-builder","Exportfunktionen","CSS-Variablen","JSON","Ausgabemöglichkeiten","Metadaten","Schnappschuss-Tests","Spezifikation v0.3","KI-Tools"],"pt":["Exporters Builder","funções de exportação","CSS variables","JSON","formatação de saída","testes de unidade","desenvolvedores","ferramentas de desenvolvimento","API pública"],"ru":["Exporters Builder","функции экспорта","CSS переменные","JSON","форматирование вывода","модульные тесты","разработчики ИИ Агентов","инструменты разработки","публичное API"],"ar":["Exporters Builder","وظائف التصدير","متغيرات CSS","JSON","تنسيق الإخراج","اختبارات الوحدة","منشئو أدوات الذكاء الاصطناعي","أدوات التطوير","واجهة برمجة التطبيقات العامة"]}},"owner":"claushaas","repo":"palette-kit","repoPath":"claushaas/palette-kit","stars":3,"forks":0,"updatedAt":"2026-02-14T02:06:38Z","topics":[],"category":"community","skillMd":{"name":"exporters-builder","description":"Build CSS/JSON exporters per src/planning/spec-v0.3.md and src/planning/roadmap-v0.3.md, including output options and gamut handling.","bodyPreview":"# Exporters Builder\n\nUse this skill when implementing export functions (CSS variables and JSON) and output formatting per v0.3 spec.\n\n## Workflow\n\n1. Read `src/planning/spec-v0.3.md` and the relevant phase in `src/planning/roadmap-v0.3.md`.\n2. Implement exporters in `src/export` with `OutputOptions` (precision, formats).\n3. Ensure optional `meta` data is included only when requested.\n4. Add minimal snapshot-like tests for CSS vars and JSON output.\n\n## Guardrails\n\n- Preserve the public API surfac","body":"# Exporters Builder\n\nUse this skill when implementing export functions (CSS variables and JSON) and output formatting per v0.3 spec.\n\n## Workflow\n\n1. Read `src/planning/spec-v0.3.md` and the relevant phase in `src/planning/roadmap-v0.3.md`.\n2. Implement exporters in `src/export` with `OutputOptions` (precision, formats).\n3. Ensure optional `meta` data is included only when requested.\n4. Add minimal snapshot-like tests for CSS vars and JSON output.\n\n## Guardrails\n\n- Preserve the public API surface for v0.3 (`exportThemeCss`, `exportThemeJson`).\n- Keep output stable and deterministic (ordering, precision).\n"},"lastSynced":"2026-03-06T07:00:31.512Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents working with data export and formatting, particularly those utilizing CSS variables and JSON output.","zh":"非常适合与数据导出和格式化合作的AI代理，特别是那些利用CSS变量和JSON输出的代理。","ja":"データのエクスポートとフォーマットに従事するAIエージェント、特にCSS変数とJSON出力を利用するものに最適です。","ko":"데이터导出과 형식화와 협력하는 AI 에이전트에 적합하며, 특히 CSS 변수와 JSON 출력을 사용하는 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA que trabajan con exportación de datos y formato, particularmente aquellos que utilizan variables CSS y salida JSON.","fr":"Parfait pour les agents IA travaillant avec l''exportation de données et la mise en forme, en particulier ceux qui utilisent des variables CSS et une sortie JSON.","de":"Perfekt für KI-Agents, die mit Datenexport und Formatierung arbeiten, insbesondere solche, die CSS-Variablen und JSON-Ausgaben verwenden.","pt":"Perfeito para agentes de IA que trabalham com exportação de dados e formatação, particularmente aqueles que utilizam variáveis CSS e saída JSON.","ru":"Идеально подходит для агентов ИИ, работающих с экспортом данных и форматированием, особенно тех, которые используют переменные CSS и вывод JSON.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يعملون مع تصدير البيانات وتحويلها إلى تنسيق معين، ولا سيما أولئك الذين يستخدمون متغيرات CSS و JSON"},"recommendation":{"en":"Empowers agents to implement export functions with precision and flexibility, utilizing OutputOptions for customizable formats and including optional meta data as needed, all while preserving the public API surface and adhering to the v0.3 spec.","zh":"赋予代理实现导出函数的精确性和灵活性，利用OutputOptions进行可定制的格式，并在需要时包含可选的元数据，同时保留公共API接口并遵循v0.3规范。","ja":"エージェントに、OutputOptionsを使用してカスタマイズ可能な形式でエクスポート関数を実装する能力を与え、必要に応じてオプションのメタデータを含めながら、公開APIサーフェスを保持し、v0.3仕様に従います。","ko":"에이전트가 OutputOptions를 사용하여 맞춤형 형식으로 내보내기 함수를 구현할 수 있는 능력을 부여하며, 필요한 경우 선택적 메타데이터를 포함시키고, 공개 API 표면을 유지하며, v0.3 사양을 준수합니다.","es":"Permite a los agentes implementar funciones de exportación con precisión y flexibilidad, utilizando OutputOptions para formatos personalizables e incluyendo metadatos opcionales según sea necesario, todo mientras se mantiene la superficie de la API pública y se ajusta a la especificación v0.3.","fr":"Permet aux agents de mettre en œuvre des fonctions d''exportation avec précision et flexibilité, en utilisant OutputOptions pour des formats personnalisables et en incluant des métadonnées facultatives selon les besoins, tout en préservant la surface d''API publique et en respectant la spécification v0.3.","de":"Ermöglicht es Agenten, Exportfunktionen mit Präzision und Flexibilität zu implementieren, indem sie OutputOptions für anpassbare Formate verwenden und optional Metadaten einbeziehen, wie erforderlich, während die öffentliche API-Oberfläche erhalten und der Spezifikation v0.3 entsprochen wird.","pt":"Habilita os agentes a implementar funções de exportação com precisão e flexibilidade, utilizando OutputOptions para formatos personalizados e incluindo metadados opcionais conforme necessário, preservando a superfície da API pública e aderindo ao spec v0.3.","ru":"Наделяет агентов возможностью реализовывать функции экспорта с точностью и гибкостью, используя OutputOptions для настраиваемых форматов и включая необязательные метаданные по мере необходимости, сохраняя при этом публичный API-интерфейс и соблюдая спецификацию v0.3.","ar":"تمكن الوكلاء من تنفيذ وظائف التصدير بدقة ومرونة، باستخدام OutputOptions لتنسيقات مخصصة وإدراج بيانات وصفية tùy thuộc على الحاجة، مع الحفاظ على سطح API العام والموافقة على مواصفات v0.3"},"useCases":{"en":["Implementing export functions with CSS variables and JSON output formatting","Customizing output formats using OutputOptions","Ensuring optional meta data inclusion in export outputs"],"zh":["使用CSS变量和JSON输出格式化实现导出函数","使用OutputOptions自定义输出格式","确保导出输出中包含可选的元数据"],"ja":["CSS変数とJSON出力形式を使用してエクスポート関数を実装する","OutputOptionsを使用して出力形式をカスタマイズする","エクスポート出力にオプションのメタデータを含めることを保証する"],"ko":["CSS 변수와 JSON 출력 형식으로 내보내기 함수를 구현하는 것","OutputOptions를 사용하여 출력 형식을 사용자 정의하는 것","내보내기 출력에 선택적 메타데이터가 포함되도록 보장하는 것"],"es":["Implementar funciones de exportación con variables CSS y formato de salida JSON","Personalizar formatos de salida mediante OutputOptions","Asegurar la inclusión de metadatos opcionales en las salidas de exportación"],"fr":["Mettre en œuvre des fonctions d''exportation avec des variables CSS et un format de sortie JSON","Personnaliser les formats de sortie à l''aide de OutputOptions","Assurer l''inclusion de métadonnées facultatives dans les sorties d''exportation"],"de":["Implementierung von Exportfunktionen mit CSS-Variablen und JSON-Ausgabenformatierung","Anpassen von Ausgabeformaten mit OutputOptions","Sicherstellung der Einbeziehung optionaler Metadaten in Exportausgaben"],"pt":["Implementação de funções de exportação com variáveis CSS e formatação de saída JSON","Personalização de formatos de saída usando OutputOptions","Garantia de inclusão de metadados opcionais nos resultados de exportação"],"ru":["Реализация функций экспорта с переменными CSS и форматированием вывода JSON","Настройка форматов вывода с помощью OutputOptions","Обеспечение включения необязательных метаданных в результаты экспорта"],"ar":["تنفيذ وظائف التصدير باستخدام متغيرات CSS وتنسيق JSON للخرج","تخصيص تنسيقات الإخراج باستخدام OutputOptions","ضمان إدراج بيانات وصفية اختيارية في مخرجات التصدير"]},"limitations":{"en":["Requires adherence to v0.3 spec","Preservation of public API surface is mandatory"],"zh":["需要遵循v0.3规范","公共API接口的保留是强制性的"],"ja":["v0.3仕様に従う必要がある","公開APIサーフェスの保持は必須である"],"ko":["v0.3 사양을 준수해야 함","공개 API 표面的 보존은 필수적임"],"es":["Requiere adherencia a la especificación v0.3","La preservación de la superficie de la API pública es obligatoria"],"fr":["Nécessite de respecter la spécification v0.3","La préservation de la surface d''API publique est obligatoire"],"de":["Erfordert die Einhaltung der Spezifikation v0.3","Die Erhaltung der öffentlichen API-Oberfläche ist verpflichtend"],"pt":["Exige adesão ao spec v0.3","Preservação da superfície da API pública é mandatória"],"ru":["Требует соблюдения спецификации v0.3","Сохранение публичного API-интерфейса является обязательным"],"ar":["يتطلب الامتثال لمواصفات v0.3","الحفاظ على سطح API العام هو إلزامي"]},"version":4},"contentHash":"44c4e44cbb38c3f9024612dfb8e1609028c9f941ce051eb81dd5c24b0a31f9b5","qualityScore":26}');
