INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('claushaas/palette-kit/exporters-builder', 'exporters-builder', 'claushaas', 'palette-kit', 'community', 'exporters-builder claushaas palette-kit community The exporters-builder skill enables developers to implement export functions with CSS variables and JSON output formatting. It benefits developers working with v0.3 spec. Exporters Builder是一种用于实现导出功能和输出格式化的技能，支持CSS变量和JSON输出 Exporters Builderは、CSS変数とJSON出力をサポートする導出機能と出力フォーマットを実装するスキルです Exporters Builder는 CSS 변수와 JSON 출력을 지원하는 출력 형식 지정 및 데이터 내보내기 기능을 구현하는 스킬입니다 Exporters-builder es una habilidad para implementar funciones de exportación de CSS variables y JSON con opciones de salida personalizadas Exporters-builder est une compétence pour mettre en place des fonctions d''exportation de variables CSS et JSON avec des options de sortie personnalisées Exporters-builder ist eine Fähigkeit zur Implementierung von Exportfunktionen für CSS-Variablen und JSON mit benutzerdefinierten Ausgabemöglichkeiten O Exporters Builder é uma ferramenta para implementar funções de exportação com CSS variables e JSON, incluindo formatação de saída e testes. Exporters Builder - это инструмент для реализации функций экспорта с помощью CSS переменных и JSON, включая форматирование вывода и тестирование для ИИ Агентов. Exporters Builder هو أداة لتنفيذ وظائف التصدير باستخدام متغيرات CSS و JSON، بما في ذلك تنسيق الإخراج والاختبارات لأدوات الذكاء الاصطناعي. how to use exporters-builder exporters-builder setup guide exporters-builder alternative exporters-builder vs other export tools what is exporters-builder exporters-builder install exporters-builder implementation exporters-builder and CSS variables exporters-builder and JSON output formatting AI工具 导出功能 输出格式化 CSS变量 JSON输出 Exporters Builder v0.3规范 输出选项 Implements exporters in src/export with OutputOptions for precision and formats Includes optional meta data only when requested Supports minimal snapshot-like tests for CSS vars and JSON output Preserves the public API surface Reads src/planning/spec-v0.3.md and relevant phase in src/planning/roadmap-v0.3.md exporters-builder is a skill that facilitates the implementation of export functions, including CSS variables and JSON output formatting, according to the v0.3 specification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qte77/Agents-eval/committing-staged-with-message', 'community', 'qte77', 'Agents-eval', 'qte77/Agents-eval', 'committing-staged-with-message', 2, 1, 26, '2026-02-22T21:51:31Z', '2026-03-06T07:04:11.980Z', '7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7', '{"id":"qte77/Agents-eval/committing-staged-with-message","name":"committing-staged-with-message","description":{"en":"committing-staged-with-message is a Multi-Agent System evaluation framework that generates and evaluates scientific paper reviews. It benefits developers by automating Git workflows","zh":"Committing-Staged-With-Message 是一个使用 PydanticAI 的多代理系统评估框架，通过传统指标、LLM-as-a-Judge 和图形复杂性分析等三层评估方法生成和评估科学论文审查","ja":"Committing-Staged-With-Message は、PydanticAI を使用したマルチエージェントシステム評価フレームワークで、伝統的な指標、LLM-as-a-Judge、グラフベースの複雑さ分析などの 3 つの評価方法で科学論文のレビューを生成および評価します","ko":"Committing-Staged-With-Message는 PydanticAI를 사용하는 多代理システム 평가 프레임워크로서 전통적인 지표, LLM-as-a-Judge 및 그래프 기반 복잡도 분석 등의 3단계 평가 방법으로 과학 논문 리뷰를 생성 및 평가합니다","es":"Committing-staged-with-message es un marco de evaluación de sistemas multiagente que utiliza PydanticAI para evaluar cambios de código","fr":"Committing-staged-with-message est un cadre d''évaluation de systèmes multi-agents qui utilise PydanticAI pour évaluer les modifications de code","de":"Committing-staged-with-message ist ein Bewertungsrahmen für Multi-Agenten-Systeme, der PydanticAI zur Bewertung von Code-Änderungen verwendet","pt":"O committing-staged-with-message é uma ferramenta que utiliza PydanticAI para avaliar artigos científicos","ru":"committing-staged-with-message - это инструмент, использующий PydanticAI для оценки научных статей","ar":"committing-staged-with-message هو أداة تستخدم PydanticAI لتقييم الأبحاث العلمية"},"seo":{"title":{"en":"committing-staged-with-message: Setup Guide for AI Agents","zh":"Committing-Staged-With-Message 设置指南 - AI工具","ja":"Committing-Staged-With-Message のベストプラクティス - AIエージェント","ko":"Committing-Staged-With-Message 구축 가이드 - AI 에이전트","es":"Guía de configuración de committing-staged-with-message p...","fr":"Guide de mise en place de committing-staged-with-message ...","de":"Einrichtungsleitfaden für committing-staged-with-message ...","pt":"Committing Staged com Mensagem: Guia de Configuração com ...","ru":"ИИ Агенты: Настройка_committing-staged-with-message с пом...","ar":"إعداد Committing Staged مع الرسائل باستخدام PydanticAI"},"description":{"en":"Discover how committing-staged-with-message streamlines Git workflows using PydanticAI and Bash. Learn to analyze staged changes and generate messages","zh":"使用 Committing-Staged-With-Message AI工具，通过 PydanticAI 和三层评估方法生成和评估科学论文审查","ja":"Committing-Staged-With-Message AIエージェントを使用して、PydanticAI と 3 つの評価方法で科学論文のレビューを生成および評価します","ko":"Committing-Staged-With-Message AI 에이전트를 사용하여 PydanticAI 및 3단계 평가 방법으로 과학 논문 리뷰를 생성 및 평가합니다","es":"Aprende a configurar committing-staged-with-message para evaluar cambios de código con PydanticAI y Git","fr":"Découvrez comment configurer committing-staged-with-message pour évaluer les modifications de code avec PydanticAI et Git","de":"Erfahren Sie, wie Sie committing-staged-with-message für die Bewertung von Code-Änderungen mit PydanticAI und Git einrichten","pt":"Aprenda a configurar o committing-staged-with-message com PydanticAI e melhore a avaliação de artigos científicos","ru":"Настройте committing-staged-with-message с помощью PydanticAI и улучшите оценку научных статей с помощью ИИ Агентов","ar":"تعلم كيفية إعداد committing-staged-with-message باستخدام PydanticAI وتحسين تقييم الأبحاث العلمية"},"definition":{"en":"committing-staged-with-message is a Git workflow automation tool using PydanticAI and Bash to analyze staged changes and generate commit messages","zh":"Committing-Staged-With-Message 是一个使用 PydanticAI 生成和评估科学论文审查的多代理系统评估框架","ja":"Committing-Staged-With-Message は、PydanticAI を使用して科学論文のレビューを生成および評価するマルチエージェントシステム評価フレームワークです","ko":"Committing-Staged-With-Message는 PydanticAI를 사용하여 과학 논문 리뷰를 생성 및 평가하는 多代理システム 평가 프레임워크입니다","es":"Committing-staged-with-message es una herramienta de evaluación de cambios de código que utiliza Git y PydanticAI","fr":"Committing-staged-with-message est un outil d''évaluation de modifications de code qui utilise Git et PydanticAI","de":"Committing-staged-with-message ist ein Werkzeug zur Bewertung von Code-Änderungen, das Git und PydanticAI verwendet","pt":"O committing-staged-with-message é uma ferramenta de avaliação de artigos científicos","ru":"committing-staged-with-message - это инструмент оценки научных статей","ar":"committing-staged-with-message هو أداة لتقييم الأبحاث العلمية"},"features":{"en":["Analyzes staged changes using `git diff --staged --name-only` and `git diff --staged --stat`","Reviews detailed staged changes with `git diff --staged`","Implements size guard to skip full diff for large changes","Utilizes PydanticAI for evaluation framework","Runs Bash commands for context gathering","Generates commit messages based on staged changes"],"zh":["使用 PydanticAI 生成和评估科学论文审查","三层评估方法：传统指标、LLM-as-a-Judge 和图形复杂性分析","支持 Git diff 和 Git log 命令","自动生成 commit 消息","支持 Size guard 功能"],"ja":["PydanticAI を使用して科学論文のレビューを生成および評価","3 つの評価方法：伝統的な指標、LLM-as-a-Judge、グラフベースの複雑さ分析","Git diff と Git log コマンドをサポート","自動的にコミットメッセージを生成","Size guard 機能をサポート"],"ko":["PydanticAI를 사용하여 과학 논문 리뷰를 생성 및 평가","3단계 평가 방법：전통적인 지표, LLM-as-a-Judge, 그래프 기반 복잡도 분석","Git diff 및 Git log 명령어 지원","자동으로 커밋 메시지를 생성","Size guard 기능 지원"],"es":["Evaluación de cambios de código con PydanticAI","Uso de Git para analizar cambios de código","Generación de mensajes de confirmación personalizados","Análisis de complejidad de gráficos","Soporte para LLM-as-a-Judge","Integración con sistemas de control de versiones"],"fr":["Évaluation de modifications de code avec PydanticAI","Utilisation de Git pour analyser les modifications de code","Génération de messages de confirmation personnalisés","Analyse de complexité de graphiques","Prise en charge de LLM-as-a-Judge","Intégration avec les systèmes de contrôle de version"],"de":["Bewertung von Code-Änderungen mit PydanticAI","Verwendung von Git zur Analyse von Code-Änderungen","Generierung von benutzerdefinierten Bestätigungsnachrichten","Analyse der Komplexität von Graphen","Unterstützung für LLM-as-a-Judge","Integration mit Versionierungssystemen"],"pt":["Análise de mudanças com `git diff --staged`","Geração de mensagens com base em estatísticas de mudanças","Utilização de PydanticAI para avaliação de artigos científicos","Avaliação de complexidade com base em análise de grafos","Integração com o CLI do Git"],"ru":["Анализ изменений с помощью `git diff --staged`","Генерация сообщений на основе статистики изменений","Использование PydanticAI для оценки научных статей","Оценка сложности на основе анализа графов","Интеграция с CLI Git"],"ar":["تحليل التغييرات باستخدام `git diff --staged`","توليد الرسائل dựa على إحصائيات التغييرات","استخدام PydanticAI لتقييم الأبحاث العلمية","تقييم التعقيد باستخدام تحليل الرسوم البيانية","دمج مع CLI Git"]},"keywords":{"en":["how to use committing-staged-with-message","what is committing-staged-with-message","committing-staged-with-message alternative","committing-staged-with-message vs Git hooks","committing-staged-with-message install","committing-staged-with-message setup guide","PydanticAI Git workflow automation","Bash Git workflow scripting","automating Git commit messages"],"zh":["Committing-Staged-With-Message","PydanticAI","多代理系统评估框架","科学论文审查","Git diff","Git log","AI工具","自动化评估"],"ja":["Committing-Staged-With-Message","PydanticAI","マルチエージェントシステム評価フレームワーク","科学論文のレビュー","Git diff","Git log","AIエージェント","自動評価"],"ko":["Committing-Staged-With-Message","PydanticAI","多代理システム 평가 프레임워크","과학 논문 리뷰","Git diff","Git log","AI 에이전트","자동 평가"],"es":["committing-staged-with-message","Agentes de IA","PydanticAI","Git","evaluación de cambios de código","generación de mensajes de confirmación","análisis de complejidad de gráficos","LLM-as-a-Judge","sistemas de control de versiones"],"fr":["committing-staged-with-message","Outils d''IA","PydanticAI","Git","évaluation de modifications de code","génération de messages de confirmation","analyse de complexité de graphiques","LLM-as-a-Judge","systèmes de contrôle de version"],"de":["committing-staged-with-message","KI-Tools","PydanticAI","Git","Bewertung von Code-Änderungen","Generierung von Bestätigungsnachrichten","Analyse der Komplexität von Graphen","LLM-as-a-Judge","Versionierungssysteme"],"pt":["committing-staged-with-message","PydanticAI","avaliação de artigos científicos","git diff","CLI do Git","análise de mudanças","geração de mensagens","tópicos de desenvolvimento"],"ru":["committing-staged-with-message","PydanticAI","оценка научных статей","git diff","CLI Git","анализ изменений","генерация сообщений","темы разработки"],"ar":["committing-staged-with-message","PydanticAI","تقييم الأبحاث العلمية","git diff","CLI Git","تحليل التغييرات","توليد الرسائل","مواضيع التطوير"]}},"owner":"qte77","repo":"Agents-eval","repoPath":"qte77/Agents-eval","stars":2,"forks":1,"updatedAt":"2026-02-22T21:51:31Z","topics":[],"category":"community","skillMd":{"name":"committing-staged-with-message","description":"Generate commit message for staged changes, pause for approval, then commit. Stage files first with `git add`, then run this skill.","bodyPreview":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2:","body":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2: Generate Commit Message\n\nUse the Read tool to check `.gitmessage` for commit message format and syntax.\n\n**The commit message body MUST include (concisely — no padding, no redundancy):**\n\n1. **What changed**: bullet points per file or logical group\n2. **Symbols added/removed** (when applicable): functions, classes, tests\n3. **Diff stats**: lines added/removed (from `--stat` summary line) — MUST be the last line of the body\n   - Format: `+ symbol_name`, `- symbol_name`\n   - Omit for config/docs/formatting-only changes\n\nKeep the message laser-focused. Do not repeat the subject line in the body.\n\n## Step 3: Pause for Approval\n\n**Please review the commit message.**\n\n- **Approve**: \"yes\", \"y\", \"commit\", \"go ahead\"\n- **Edit**: Provide your preferred message\n- **Cancel**: \"no\", \"cancel\", \"stop\"\n\n## Step 4: Commit\n\nOnce approved:\n\n- `git commit --gpg-sign -m \"[message]\"` - Commit staged changes with approved message (GPG signature mandatory)\n- `git status` - Verify success\n"},"lastSynced":"2026-03-06T07:04:11.980Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated Git workflow management with staged change analysis.","zh":"非常适合需要自动化 Git 工作流管理和分阶段变更分析的开发代理。","ja":"開発エージェントが自動化された Git ワークフロー管理とステージされた変更分析を必要とする場合に最適です。","ko":"자동화된 Git 워크플로우 관리 및 단계적 변경 분석이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan gestión de flujo de trabajo automatizada de Git con análisis de cambios con estado","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow Git automatisée avec analyse des changements de mise en scène","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Git-Workflow-Verwaltung mit Analyse von geänderten Stadien benötigen","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de fluxo de trabalho automatizado do Git com análise de alterações em estágio.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированное управление рабочим процессом Git с анализом изменений на стадии.","ar":"مثالي لوسائل وكالات التطوير التي تحتاج إلى إدارة تدفق العمل التلقائي ل Git مع تحليل التغييرات في المرحلة."},"recommendation":{"en":"Empowers agents to automate Git workflows by analyzing staged changes using Git commands like ''git diff --staged'' and generating commit messages based on the analysis, including file and line change statistics.","zh":"赋予代理人自动化 Git 工作流的能力，通过分析分阶段的变化，使用诸如 ''git diff --staged'' 的 Git 命令，并根据分析生成提交消息，包括文件和行变化统计。","ja":"エージェントが ''git diff --staged'' のような Git コマンドを使用してステージされた変更を分析し、分析に基づいてコミットメッセージを生成することで、Git ワークフローを自動化する能力を提供します。生成されたコミットメッセージには、ファイルと行の変更統計も含まれます。","ko":"에이전트가 ''git diff --staged''와 같은 Git 명령을 사용하여 단계적으로 변경된 내용을 분석하고, 분석 결과를 바탕으로 커밋 메시지를 생성하여 Git 워크플로우를 자동화할 수 있는 능력을 제공합니다. 생성된 커밋 메시지는 파일 및 행 변경 통계도 포함합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de Git analizando los cambios con estado mediante comandos de Git como ''git diff --staged'' y generando mensajes de confirmación basados en el análisis, incluyendo estadísticas de cambios de archivo y línea","fr":"Permet aux agents d''automatiser les flux de travail Git en analysant les changements de mise en scène à l''aide de commandes Git comme ''git diff --staged'' et en générant des messages de validation basés sur l''analyse, y compris des statistiques de modifications de fichiers et de lignes","de":"Ermöglicht es Agenten, Git-Workflows zu automatisieren, indem sie geänderte Stadien mit Git-Befehlen wie ''git diff --staged'' analysieren und Commit-Nachrichten basierend auf der Analyse generieren, einschließlich Statistiken zu Datei- und Zeilenänderungen","pt":"Habilita os agentes a automatizar fluxos de trabalho do Git analisando alterações em estágio usando comandos do Git como ''git diff --staged'' e gerando mensagens de commit com base na análise, incluindo estatísticas de alteração de arquivos e linhas.","ru":"Позволяет агентам автоматизировать рабочие процессы Git, анализируя изменения на стадии с помощью команд Git, таких как ''git diff --staged'', и генерируя сообщения о фиксации на основе анализа, включая статистику изменений файлов и строк.","ar":"تمكّن الوكالات من تلقين عمليات العمل التلقائية ل Git من خلال تحليل التغييرات في المرحلة باستخدام أوامر Git مثل ''git diff --staged'' وتوليد رسائل Commit بناءً على التحليل، بما في ذلك إحصائيات التغييرات في الملفات والأسطر."},"useCases":{"en":["Automating commit message generation for staged changes","Analyzing staged files and changes for code review","Generating detailed commit messages based on ''git diff --staged --stat'' output"],"zh":["为分阶段的变化自动化生成提交消息","分析分阶段的文件和变化以进行代码审查","根据 ''git diff --staged --stat'' 输出生成详细的提交消息"],"ja":["ステージされた変更の自動コミットメッセージ生成","コードレビューのためのステージされたファイルと変更の分析"," ''git diff --staged --stat'' 出力に基づいて詳細なコミットメッセージを生成する"],"ko":["단계적으로 변경된 내용에 대한 자동 커밋 메시지 생성","코드 리뷰를 위한 단계적으로 변경된 파일 및 변경 사항 분석"," ''git diff --staged --stat'' 출력을 기반으로 자세한 커밋 메시지 생성"],"es":["Automatizar la generación de mensajes de confirmación para cambios con estado","Analizar archivos y cambios con estado para revisión de código","Generar mensajes de confirmación detallados basados en la salida de ''git diff --staged --stat''"],"fr":["Automatiser la génération de messages de validation pour les changements de mise en scène","Analyser les fichiers et les changements de mise en scène pour la révision de code","Générer des messages de validation détaillés basés sur la sortie de ''git diff --staged --stat''"],"de":["Automatisieren der Generierung von Commit-Nachrichten für geänderte Stadien","Analysieren von Dateien und geänderten Stadien für Code-Review","Generieren detaillierter Commit-Nachrichten basierend auf der Ausgabe von ''git diff --staged --stat''"],"pt":["Automatizar a geração de mensagens de commit para alterações em estágio","Analisar arquivos e alterações em estágio para revisão de código","Gerar mensagens de commit detalhadas com base na saída de ''git diff --staged --stat''"],"ru":["Автоматизировать генерацию сообщений о фиксации для изменений на стадии","Анализировать файлы и изменения на стадии для проверки кода","Генерировать подробные сообщения о фиксации на основе вывода ''git diff --staged --stat''"],"ar":["تلقين توليد رسائل Commit للتعديلات في المرحلة","تحليل الملفات والتغييرات في المرحلة لمراجعة الشفرة","توليد رسائل Commit مفصلة بناءً على إخراج ''git diff --staged --stat''"]},"limitations":{"en":["Requires Git installation and configuration","Limited to analyzing staged changes, not entire repository history","Size guard limits detailed diff review to <10 files or <500 lines changed"],"zh":["需要 Git 安装和配置","仅限于分析分阶段的变化，而不是整个仓库历史","大小守护限制详细的差异审查到 <10 个文件或 <500 行变化"],"ja":["Git のインストールと設定が必要","ステージされた変更のみを分析し、全リポジトリ履歴を分析しない","サイズガードにより、詳細な diff レビューは <10 ファイルまたは <500 行の変更に制限される"],"ko":["Git 설치 및 구성이 필요합니다.","단계적으로 변경된 내용만 분석하며, 전체 리포지토리 기록은 분석하지 않음","크기 감시로 인해 자세한 디프 리뷰는 <10개의 파일 또는 <500행의 변경으로 제한됨"],"es":["Requiere instalación y configuración de Git","Limitado a analizar cambios con estado, no la historia completa del repositorio","La protección de tamaño limita la revisión detallada de la diferencia a <10 archivos o <500 líneas cambiadas"],"fr":["Nécessite l''installation et la configuration de Git","Limité à l''analyse des changements de mise en scène, et non à l''historique complet du référentiel","La protection de taille limite la révision détaillée de la différence à <10 fichiers ou <500 lignes modifiées"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf die Analyse von geänderten Stadien, nicht auf die gesamte Repository-Historie","Die Größenschutzbegrenzung limitiert die detaillierte Überprüfung der Differenz auf <10 Dateien oder <500 geänderte Zeilen"],"pt":["Requer instalação e configuração do Git","Limitado à análise de alterações em estágio, não à história completa do repositório","Guarda de tamanho limita a revisão detalhada da diferença a <10 arquivos ou <500 linhas alteradas"],"ru":["Требуется установка и настройка Git","Ограничен анализом изменений на стадии, а не всей истории репозитория","Ограничитель размера ограничивает подробный обзор различий <10 файлами или <500 измененными строками"],"ar":["يتطلب تثبيت وتكوين Git","محدود بتحليل التغييرات في المرحلة، وليس تاريخ المستودع الكامل","حارس الحجم يقيد المراجعة التفصيلية للفرق إلى <10 ملفات أو <500 سطر معدّل"]},"version":4},"contentHash":"7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7","qualityScore":26}');
