INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('odysseyalive/omarchy-seashells-theme/self-heal', 'self-heal', 'odysseyalive', 'omarchy-seashells-theme', 'community', 'self-heal odysseyalive omarchy-seashells-theme community Self-Heal is a quiet companion skill that watches for friction caused by skill instructions and proposes surgical fixes. It benefits AI agent developers by streamlining task resolution. Self-Heal 技术是一种自动故障诊断和修复工具，能够检测和解决技能指令中的问题 Self-Heal AIエージェントは自動診断と修復ツールで、スキル指令の問題を検出して解決 Self-Heal 기술은 자동 오류 진단 및 수정 도구로, 기술 지침에서 발생하는 문제를 감지하고 해결합니다 Self-Heal es una habilidad de AI Agent que detecta y soluciona fricciones en sesiones en vivo. Se integra en otras habilidades como observador y propone soluciones quirúrgicas Self-Heal est une compétence d''AI Agent qui détecte et résout les frictions lors de sessions en direct. Elle s''intègre dans d''autres compétences en tant qu''observateur et propose des solutions chirurgicales Self-Heal ist eine Fähigkeit von AI Agent, die Reibungspunkte in Live-Sitzungen erkennt und behebt. Sie integriert sich in andere Fähigkeiten als Beobachter und schlägt chirurgische Lösungen vor O Self-Heal é uma habilidade que observa e corrige fontes de fricção em sessões ao vivo, propondo soluções cirúrgicas com aprovação do usuário. Self-Heal — это навык, который наблюдает и исправляет источники трения в живых сессиях, предлагая хирургические решения с одобрения пользователя. Self-Heal هو مهارة تقوم بمراقبة ومعالجة مصادر الاحتكاك في الجلسات الحية، وتقترح حلولا جراحية مع موافقة المستخدم. how to use self-heal self-heal setup guide what is self-heal self-heal alternative self-heal vs other AI agent skills self-heal install self-heal for AI agent development automated friction detection surgical fixes for AI agent skills Self-Heal 技术 自动故障诊断 修复工具 技能指令问题 开发环境 SeaShells 主题 AI 工具 自动化技术 Watches for friction caused by skill instructions during live sessions Diagnoses root cause of friction and proposes surgical fixes with user approval Embedded into other skills as an observer for seamless integration Surfaces automatically when detecting a fixable source of friction Complies with directives for surgical updates to skills, ensuring minimal changes Self-heal is a skill that automatically detects and diagnoses root causes of friction in AI agent skills, providing targeted fixes for improved efficiency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('asamawi/mawareeth/bmad-agent-cis-storyteller', 'community', 'asamawi', 'mawareeth', 'asamawi/mawareeth', 'bmad-agent-cis-storyteller', 2, 2, 26, '2026-03-03T01:40:48Z', '2026-03-06T07:08:46.437Z', '745c01f0b24f8d4dd95e7fde8daf5946ff8cf64373f17b95d33635a67e5c4a75', '{"id":"asamawi/mawareeth/bmad-agent-cis-storyteller","name":"bmad-agent-cis-storyteller","description":{"en":"The bmad-agent-cis-storyteller skill enables developers to embody a specific agent persona and follow precise activation instructions. It benefits developers working with AI agents.","zh":"bmad-agent-cis-storyteller 是一个需要精确激活和执行的 AI 代理，包括加载特定文件和遵循菜单系统","ja":"bmad-agent-cis-storyteller は，正確なアクティベーションと実行が必要な AI エージェントです。特定のファイルのロードとメニュー システムの遵守を含みます","ko":"bmad-agent-cis-storyteller는 정확한 활성화와 실행이 필요한 AI 에이전트입니다. 특정 파일 로드 및 메뉴 시스템 준수를 포함합니다","es":"El agente bmad-agent-cis-storyteller requiere una configuración precisa. Sigue nuestros pasos para cargar y ejecutar el agente de manera efectiva.","fr":"L''agent bmad-agent-cis-storyteller nécessite une configuration précise. Suivez nos étapes pour charger et exécuter l''agent de manière efficace.","de":"Der Agent bmad-agent-cis-storyteller erfordert eine präzise Konfiguration. Befolgen Sie unsere Schritte, um den Agenten effektiv zu laden und auszuführen.","pt":"O bmad-agent-cis-storyteller é um agente que requer configuração precisa. Carregue o arquivo de agente e execute os comandos para ativá-lo.","ru":"ИИ Агент bmad-agent-cis-storyteller требует точной настройки. Загрузите файл агента и выполните команды для активации.","ar":"العميل الذكي bmad-agent-cis-storyteller يتطلب إعدادًا دقيقًا. حمل ملف العميل وشن تشغيل الأوامر لتنشيطه."},"seo":{"title":{"en":"bmad-agent-cis-storyteller: Activation Guide for AI Agents","zh":"bmad-agent-cis-storyteller 设置指南","ja":"bmad-agent-cis-storyteller 導入ガイド","ko":"bmad-agent-cis-storyteller 설치 가이드","es":"Guía de configuración para bmad-agent-cis-storyteller","fr":"Configurer bmad-agent-cis-storyteller : Guide étape par é...","de":"Einrichtung von bmad-agent-cis-storyteller: Schritt-für-S...","pt":"Guia de Configuração do bmad-agent-cis-storyteller","ru":"Настройка ИИ Агента bmad-agent-cis-storyteller","ar":"دليل إعداد العميل الذكي bmad-agent-cis-storyteller"},"description":{"en":"Unlock the full potential of bmad-agent-cis-storyteller with our expert activation guide - learn how to load, read, and execute agent files with precision","zh":"了解如何激活和使用 bmad-agent-cis-storyteller，包括加载和执行特定步骤","ja":"bmad-agent-cis-storyteller のアクティベーションと使用方法を学ぶ，ロードと実行の手順を含む","ko":"bmad-agent-cis-storyteller를 활성화하고 사용하는 방법을 알아보세요. 로드 및 실행 단계 포함","es":"Aprende a configurar bmad-agent-cis-storyteller con nuestra guía paso a paso. Descubre cómo cargar y ejecutar el agente de manera efectiva.","fr":"Découvrez comment configurer bmad-agent-cis-storyteller avec notre guide étape par étape. Apprenez à charger et exécuter l''agent de manière efficace.","de":"Erfahren Sie, wie Sie bmad-agent-cis-storyteller mit unserer Schritt-für-Schritt-Anleitung konfigurieren. Entdecken Sie, wie Sie den Agenten effektiv laden u...","pt":"Aprenda a configurar o bmad-agent-cis-storyteller com o nosso guia passo a passo. Descubra como carregar arquivos e executar comandos com precisão.","ru":"Узнайте, как настроить ИИ Агента bmad-agent-cis-storyteller с помощью нашего пошагового руководства. Откройте для себя, как загружать файлы и выполнять коман...","ar":"تعلم كيفية إعداد العميل الذكي bmad-agent-cis-storyteller باستخدام دليلنا خطوة بخطوة. اكتشف كيفية تحميل الملفات والتشغيل الدقيق للأوامر."},"definition":{"en":"bmad-agent-cis-storyteller is a specialized AI agent skill that requires exact execution of activation steps and adherence to a predefined persona and menu system","zh":"bmad-agent-cis-storyteller 是一个 AI 代理，需要用户遵循特定步骤来激活和使用","ja":"bmad-agent-cis-storyteller は，ユーザー