INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('asamawi/mawareeth/bmad-agent-cis-storyteller', 'bmad-agent-cis-storyteller', 'asamawi', 'mawareeth', 'community', 'bmad-agent-cis-storyteller asamawi mawareeth community The bmad-agent-cis-storyteller skill enables developers to embody a specific agent persona and follow precise activation instructions. It benefits developers working with AI agents. bmad-agent-cis-storyteller 是一个需要精确激活和执行的 AI 代理，包括加载特定文件和遵循菜单系统 bmad-agent-cis-storyteller は，正確なアクティベーションと実行が必要な AI エージェントです。特定のファイルのロードとメニュー システムの遵守を含みます bmad-agent-cis-storyteller는 정확한 활성화와 실행이 필요한 AI 에이전트입니다. 특정 파일 로드 및 메뉴 시스템 준수를 포함합니다 El agente bmad-agent-cis-storyteller requiere una configuración precisa. Sigue nuestros pasos para cargar y ejecutar el agente de manera efectiva. L''agent bmad-agent-cis-storyteller nécessite une configuration précise. Suivez nos étapes pour charger et exécuter l''agent de manière efficace. Der Agent bmad-agent-cis-storyteller erfordert eine präzise Konfiguration. Befolgen Sie unsere Schritte, um den Agenten effektiv zu laden und auszuführen. O bmad-agent-cis-storyteller é um agente que requer configuração precisa. Carregue o arquivo de agente e execute os comandos para ativá-lo. ИИ Агент bmad-agent-cis-storyteller требует точной настройки. Загрузите файл агента и выполните команды для активации. العميل الذكي bmad-agent-cis-storyteller يتطلب إعدادًا دقيقًا. حمل ملف العميل وشن تشغيل الأوامر لتنشيطه. how to use bmad-agent-cis-storyteller bmad-agent-cis-storyteller setup guide bmad-agent-cis-storyteller alternative what is bmad-agent-cis-storyteller bmad-agent-cis-storyteller install bmad-agent-cis-storyteller vs other AI agents activating bmad-agent-cis-storyteller bmad-agent-cis-storyteller documentation bmad-agent-cis-storyteller tutorial bmad-agent-cis-storyteller AI 代理 AI 工具 CLI 命令 菜单系统 激活步骤 加载文件 执行步骤 使用指南 Loads full agent file from {project-root}/_bmad/cis/agents/storyteller/storyteller.md Executes all activation steps exactly as written in the agent file Follows the agent''s persona and menu system precisely Requires reading the entire contents of the agent file for complete activation Utilizes <agent-activation> commands with CRITICAL flags Executes activation instructions in a specific order for optimal performance bmad-agent-cis-storyteller is a specialized AI agent skill that requires exact execution of activation steps and adherence to a predefined persona and menu system');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cwilliams5/Alt-Tabby/review-tool-coverage', 'community', 'cwilliams5', 'Alt-Tabby', 'cwilliams5/Alt-Tabby', 'review-tool-coverage', 1, 0, 26, '2026-02-25T02:02:59Z', '2026-03-06T07:10:45.015Z', '1e73ebaf48415347d7ec9714594bf48c792c06bddd8ac3fa3d693640798e1d41', '{"id":"cwilliams5/Alt-Tabby/review-tool-coverage","name":"review-tool-coverage","description":{"en":"The review-tool-coverage skill provides a fast and responsive Alt-Tab replacement for Windows, integrated with Komorebi, benefiting developers seeking efficient window management.","zh":"review-tool-coverage是一款快速响应的Alt-Tab替代工具，支持Komorebi集成，用于优化Windows体验","ja":"review-tool-coverageは、Komorebi統合をサポートする高速なAlt-Tabの代替ツールです","ko":"review-tool-coverage는 Komorebi 통합을 지원하는 빠른 Alt-Tab 대체 도구입니다","es":"Review-tool-coverage es una herramienta de reemplazo de Alt-Tab para Windows que utiliza Autohotkey y Komorebi para mejorar la productividad","fr":"Review-tool-coverage est un outil de remplacement de Alt-Tab pour Windows qui utilise Autohotkey et Komorebi pour améliorer la productivité","de":"Review-tool-coverage ist ein Alt-Tab-Ersatztool für Windows, das Autohotkey und Komorebi verwendet, um die Produktivität zu steigern","pt":"O review-tool-coverage é uma ferramenta de otimização de query tools para Windows com integração do Komorebi, visando melhorar a produtividade","ru":"Review-tool-coverage - это инструмент оптимизации query tools для Windows с интеграцией Komorebi, направленный на повышение производительности","ar":"review-tool-coverage هو أداة لتحسين أدوات الاستعلام للويندوز مع دمج Komorebi، يهدف إلى تحسين الإنتاجية"},"seo":{"title":{"en":"review-tool-coverage: Windows Alt-Tab Replacement Setup G...","zh":"review-tool-coverage_SETUP指南 - AIエージェント工具","ja":"review-tool-coverage セットアップガイド - AIエージェント","ko":"review-tool-coverage 설정 가이드 - AI 에이전트","es":"Guía de