INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cwilliams5/Alt-Tabby/review-tool-coverage', 'review-tool-coverage', 'cwilliams5', 'Alt-Tabby', 'community', 'review-tool-coverage cwilliams5 Alt-Tabby community alt-tab autohotkey komorebi productivity window-manager windows The review-tool-coverage skill provides a fast and responsive Alt-Tab replacement for Windows, integrated with Komorebi, benefiting developers seeking efficient window management. review-tool-coverage是一款快速响应的Alt-Tab替代工具，支持Komorebi集成，用于优化Windows体验 review-tool-coverageは、Komorebi統合をサポートする高速なAlt-Tabの代替ツールです review-tool-coverage는 Komorebi 통합을 지원하는 빠른 Alt-Tab 대체 도구입니다 Review-tool-coverage es una herramienta de reemplazo de Alt-Tab para Windows que utiliza Autohotkey y Komorebi para mejorar la productividad Review-tool-coverage est un outil de remplacement de Alt-Tab pour Windows qui utilise Autohotkey et Komorebi pour améliorer la productivité Review-tool-coverage ist ein Alt-Tab-Ersatztool für Windows, das Autohotkey und Komorebi verwendet, um die Produktivität zu steigern O review-tool-coverage é uma ferramenta de otimização de query tools para Windows com integração do Komorebi, visando melhorar a produtividade Review-tool-coverage - это инструмент оптимизации query tools для Windows с интеграцией Komorebi, направленный на повышение производительности review-tool-coverage هو أداة لتحسين أدوات الاستعلام للويندوز مع دمج Komorebi، يهدف إلى تحسين الإنتاجية how to use review-tool-coverage review-tool-coverage alternative review-tool-coverage setup guide what is review-tool-coverage review-tool-coverage vs AutoHotkey review-tool-coverage install Komorebi integration with review-tool-coverage Windows Alt-Tab replacement with review-tool-coverage review-tool-coverage for developers review-tool-coverage and productivity review-tool-coverage AI工具 Alt-Tab替代 Komorebi集成 Autohotkey脚本 Windows优化 生产力提高 AIエージェント工具 Audits query tools in `tools/` for fitness using parallelism where possible Utilizes AutoHotkey for customized window management Integrates with Komorebi for enhanced productivity Supports structured answers via query tools (`tools/query_*.ps1`) without loading full files Allows for niche tool usage referenced by skills when relevant review-tool-coverage is a Windows productivity tool that replaces the traditional Alt-Tab function with a faster and more responsive alternative, leveraging Komorebi integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('superwall/docs/review-sdk-update-pr', 'community', 'superwall', 'docs', 'superwall/docs', 'review-sdk-update-pr', 1, 3, 26, '2026-02-25T22:00:01Z', '2026-03-06T07:15:43.934Z', 'd542b7525ef4c9237df6be6dbad510c2cb1024d899dce2e7639c11268f8f30b6', '{"id":"superwall/docs/review-sdk-update-pr","name":"review-sdk-update-pr","description":{"en":"The review-sdk-update-pr skill automates the validation of SDK updates, benefiting developers by ensuring consistency and accuracy. It checks out the PR branch, runs bun run download:references, and identifies previous versions.","zh":"review-sdk-update-pr AI工具用于验证SDK更新，确保代码质量和文档准确性","ja":"review-sdk-update-pr AIエージェントはSDK更新を検証し、コード品質とドキュメントの正確性を確保します","ko":"review-sdk-update-pr AI 에이전트는 SDK 업데이트를 검증하여 코드 품질과 문서의 정확성을 보장합니다","es":"El skill review-sdk-update-pr valida las actualizaciones de SDK mediante la creación de una línea de base y la verificación de cambios en la documentación","fr":"Le skill review-sdk-update-pr valide les mises à jour de SDK en créant une ligne de base et en vérifiant les modifications de la documentation","de":"Das Skill review-sdk-update-pr überprüft SDK-Updates durch die Erstellung einer Basislinie und die Überprüfung von Änderungen in der Dokumentation","pt":"O review-sdk-update-pr é uma habilidade que valida atualizações de SDK. Ele utiliza o fluxo de trabalho de revisão para verificar as alterações.","ru":"ИИ Агент review-sdk-update-pr - это навык, который проверяет обновления SDK. Он использует рабочий процесс проверки для подтверждения изменений.","ar":"وكيل مراجعة SDK بالغرض review-sdk-update-pr هو مهارة تتحقق من تحديثات SDK. يستخدم تدفق العمل لمراجعة التغييرات."},"seo":{"title":{"en":"review-sdk-update-pr: Automated SDK Review Setup Guide | ...","zh":"AI工具：review-sdk-update-pr Setup Guide","ja":"AIエージェント：review-sdk-update-pr ベストプラクティス","ko":"AI 에이전트: review-sdk-update-pr 설정 가이드","es":"Guía de configuración para review-sdk-update-pr: Validaci...","fr":"Guide de configuration pour review-sdk-update-pr : Valida...","de":"Konfigurationsleitfaden für review-sdk-update-pr: Überprü...","pt":"Guia de Configuração do review-sdk-update-pr para Desenvo...","ru":"Настройка ИИ Агента review-sdk-update-pr: Руководство для...","ar":"دليل إعداد وكيل مراجعة SDK بالغرض review-sdk-update-pr"},"description":{"en":"Streamline your SDK update process with review-sdk-update-pr. Learn how to automate validation and review of SDK updates using bun run and mdx files.","zh":"了解review-sdk-update-pr AI工具的设置和使用方法，优化SDK更新流程","ja":"review-sdk-update-pr AIエージェントの設定と使用方法を学び、SDK更新プロセスを最適化する","ko":"review-sdk-update-pr AI 에이전트의 설정과 사용 방법을 알아보고 SDK 업데이트 프로세스를 최적화하세요","es":"Aprende a validar actualizaciones de SDK con review-sdk-update-pr. Descubre cómo establecer una línea de base y verificar cambios en la documentación","fr":"Découvrez comment valider les mises à jour de SDK avec review-sdk-update-pr. Apprenez à établir une ligne de base et à vérifier les modifications de la docum...","de":"Erfahren Sie, wie Sie SDK-Updates mit review-sdk-update-pr überprüfen. Lernen Sie, eine Basislinie zu erstellen und Änderungen in der Dokumentation zu überpr...","pt":"Aprenda a configurar o review-sdk-update-pr para validar atualizações de SDK com eficiência. Leia mais sobre o fluxo de trabalho e requisitos de entrada.","ru":"Узнайте, как настроить ИИ Агент review-sdk-update-pr для проверки обновлений SDK. Получите информацию о рабочем процессе и необходимых входных данных.","ar":"تعرف على كيفية إعداد وكيل مراجعة SDK بالغرض review-sdk-update-pr لتحقق من تحديثات SDK بفعالية. اقرأ المزيد حول تدفق العمل والمدخلات المطلوبة."},"definition":{"en":"review-sdk-update-pr is a skill that automates the review process for SDK updates, using technical inputs like sdk, newVersion, and PR branch or number.","zh":"review-sdk-update-pr是用于验证SDK更新的AI工具","ja":"review-sdk-update-prはSDK更新を検証するAIエージェントです","ko":"review-sdk-update-pr는 SDK 업데이트를 검증하는 AI 에이전트입니다","es":"Review-sdk-update-pr es un skill que valida las actualizaciones de SDK mediante un flujo de trabajo de revisión","fr":"Review-sdk-update-pr est un skill qui valide les mises à jour de SDK via un flux de travail de révision","de":"Review-sdk-update-pr ist ein Skill, der SDK-Updates durch einen Überprüfungsworkflow validiert","pt":"O review-sdk-update-pr é uma habilidade de revisão que valida atualizações de SDK.","ru":"ИИ Агент review-sdk-update-pr - это навык проверки, который подтверждает обновления SDK.","ar":"وكيل مراجعة SDK بالغرض review-sdk-update-pr هو مهارة مراجعة لتأكيد تحديثات SDK."},"features":{"en":["Checks out the PR branch for validation","Runs bun run download:references for reference updates","Identifies previousVersion from base branch in index.mdx files","Validates work produced with update-sdk-docs","Uses mdx files for documentation updates","Supports PR branch or PR number for flexible review"],"zh":["建立基线：检查PR分支并运行bun run download:references","识别previousVersion从基线分支","使用update-sdk-docs作为检查清单","支持多种SDK文档格式","自动化代码质量检查"],"ja":["ベースラインの確立：PRブランチをチェックアウトし、bun run download:referencesを実行","ベースブランチからpreviousVersionを識別","update-sdk-docsをチェックリストとして使用","複数のSDKドキュメント形式をサポート","コード品質の自動化チェック"],"ko":["베이스라인 설정：PR 브랜치를 체크아웃하고 bun run download:references를 실행","베이스 브랜치에서 previousVersion를 식별","update-sdk-docs를 체크리스트로 사용","다양한 SDK 문서 형식을 지원","코드 품질 자동화 체크"],"es":["Establece una línea de base para comparar cambios","Verifica la versión anterior de la documentación de SDK","Ejecuta `bun run download:references` para descargar referencias","Identifica la versión anterior en `content/docs/<sdk>/index.mdx`","Verifica cambios en la documentación de SDK"],"fr":["Établit une ligne de base pour comparer les modifications","Vérifie la version précédente de la documentation de SDK","Exécute `bun run download:references` pour télécharger des références","Identifie la version précédente dans `content/docs/<sdk>/index.mdx`","Vérifie les modifications de la documentation de SDK"],"de":["Erstellt eine Basislinie zum Vergleich von Änderungen","Überprüft die vorherige Version der SDK-Dokumentation","Führt `bun run download:references` aus, um Referenzen herunterzuladen","Identifiziert die vorherige Version in `content/docs/<sdk>/index.mdx`","Überprüft Änderungen in der SDK-Dokumentation"],"pt":["Validação de atualizações de SDK","Uso do fluxo de trabalho de revisão","Verificação das alterações no arquivo index.mdx","Identificação da versão anterior do SDK","Execução do comando bun run download:references"],"ru":["Проверка обновлений SDK","Использование рабочего процесса проверки","Проверка изменений в файле index.mdx","Определение предыдущей версии SDK","Выполнение команды bun run download:references"],"ar":["التحقق من تحديثات SDK","استخدام تدفق العمل لمراجعة","مراجعة التغييرات في ملف index.mdx","تحديد الإصدار السابق من SDK","تشغيل الأمر bun run download:references"]},"keywords":{"en":["how to use review-sdk-update-pr","review-sdk-update-pr setup guide","automated sdk review process","bun run download:references","mdx file validation","review-sdk-update-pr vs manual review","sdk update automation","what is review-sdk-update-pr","review-sdk-update-pr install","review-sdk-update-pr tutorial"],"zh":["review-sdk-update-pr","AI工具","SDK更新","代码质量检查","文档准确性","bun run download:references","update-sdk-docs"],"ja":["review-sdk-update-pr","AIエージェント","SDK更新","コード品質チェック","ドキュメントの正確性","bun run download:references","update-sdk-docs"],"ko":["review-sdk-update-pr","AI 에이전트","SDK 업데이트","코드 품질 체크","문서의 정확성","bun run download:references","update-sdk-docs"],"es":["review-sdk-update-pr","validación de actualizaciones de SDK","flujo de trabajo de revisión","documentación de SDK","bun run download:references","SDK updates","validación de cambios","línea de base"],"fr":["review-sdk-update-pr","validation des mises à jour de SDK","flux de travail de révision","documentation de SDK","bun run download:references","mises à jour de SDK","validation des modifications","ligne de base"],"de":["review-sdk-update-pr","Überprüfung von SDK-Updates","Überprüfungsworkflow","SDK-Dokumentation","bun run download:references","SDK-Updates","Überprüfung von Änderungen","Basislinie"],"pt":["review-sdk-update-pr","validação de SDK","fluxo de trabalho de revisão","bun run download:references","SDK update","revisão de código","desenvolvimento de software"],"ru":["review-sdk-update-pr","проверка SDK","рабочий процесс проверки","bun run download:references","обновление SDK","проверка кода","разработка программного обеспечения"],"ar":["review-sdk-update-pr","التحقق من SDK","تدفق العمل لمراجعة","bun run download:references","تحديث SDK","مراجعة الكود","تطوير البرمجيات"]}},"owner":"superwall","repo":"docs","repoPath":"superwall/docs","stars":1,"forks":3,"updatedAt":"2026-02-25T22:00:01Z","topics":[],"category":"community","skillMd":{"name":"review-sdk-update-pr","description":"Review SDK docs update pull requests for ios, android, flutter, expo, or react-native in this repository. Use when asked to verify completeness and correctness of an SDK docs version bump by checking PR changes against upstream SDK git diff and changelog entries.","bodyPreview":"# Review SDK Update PR\n\nThis review skill validates work produced with `update-sdk-docs`.\nRead `../update-sdk-docs/SKILL.md` first, then use it as the canonical checklist.\n\n## Required Inputs\n1. `sdk`\n2. `newVersion`\n3. PR branch or PR number (or confirmation that `HEAD` is the candidate branch)\n\n## Review Workflow\n1. Establish baseline\n- Check out the PR branch.\n- Run `bun run download:references`.\n- Identify `previousVersion` from the base branch in:\n  - `content/docs/<sdk>/index.mdx`\n  - `con","body":"# Review SDK Update PR\n\nThis review skill validates work produced with `update-sdk-docs`.\nRead `../update-sdk-docs/SKILL.md` first, then use it as the canonical checklist.\n\n## Required Inputs\n1. `sdk`\n2. `newVersion`\n3. PR branch or PR number (or confirmation that `HEAD` is the candidate branch)\n\n## Review Workflow\n1. Establish baseline\n- Check out the PR branch.\n- Run `bun run download:references`.\n- Identify `previousVersion` from the base branch in:\n  - `content/docs/<sdk>/index.mdx`\n  - `content/docs/<sdk>/sdk-reference/index.mdx`\n- Confirm the PR updates both files to `newVersion`.\n\n2. Verify upstream source changes\n- In `reference/<sdk>/`, fetch tags and compute `<prevTag>...<newTag>` diff (`expo` tags are `v`-prefixed).\n- Review:\n  - `git log --oneline <prevTag>..<newTag>`\n  - `git diff --stat <prevTag>...<newTag>`\n  - Raw diff for API/setup changes\n  - Upstream changelog entry for `newVersion`\n- Build your own expected docs checklist before judging the PR.\n\n3. Audit PR changes for completeness and correctness\n- Compare changed docs against your expected checklist and the `update-sdk-docs` workflow.\n- Confirm changelog update is additive (history preserved), not replaced by only one new entry.\n- Confirm commit message and PR title format: `feat(<sdk>): update for <newVersion>`.\n- For `android`, explicitly verify `content/docs/android/quickstart/install.mdx` reflects the new version.\n- Check for stale version strings, outdated code samples, missing guide updates, and navigation/meta issues.\n\n4. Validate execution quality\n- Run `bun run build:cf`.\n- Run `bun test`.\n- Flag failures and note any verification steps the PR author skipped.\n\n## Reporting Format\n- Report findings first, ordered by severity.\n- For each finding include:\n  - Why it is incorrect or missing\n  - Exact file path(s) with line references\n  - Concrete fix guidance\n- If no findings exist, state that explicitly and list residual risk areas reviewed.\n\n## Common Misses to Hunt\n- Upstream API or behavior changes present in diff/changelog but absent from docs.\n- Only updating version markers while missing setup or guide updates.\n- Changelog history truncated by replacing old entries.\n- Android install page not updated.\n- Reviewing only file stats without checking raw upstream diff.\n"},"lastSynced":"2026-03-06T07:15:43.934Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated SDK validation and update capabilities.","zh":"适合需要自动化SDK验证和更新功能的开发代理。","ja":"自動化SDK検証および更新機能を必要とする開発エージェントに最適です。","ko":"自动화 SDK 검증 및 업데이트 기능이 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan capacidades de validación y actualización de SDK automatizadas.","fr":"Parfait pour les agents de développement ayant besoin de capacités de validation et de mise à jour de SDK automatisées.","de":"Perfekt für Entwicklungssagenten, die automatisierte SDK-Validierungs- und Updatefunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de validação e atualização automatizada de SDK.","ru":"Идеально для агентов разработки, которым необходима автоматизированная проверка и обновление SDK.","ar":"مثالي لعمليات تطوير الوكلاء الذين يحتاجون إلى التحقق التلقائي وتحديث SDK."},"recommendation":{"en":"Empowers agents to validate SDK updates using bun run download:references, ensuring consistency and accuracy by identifying previous versions and checking out PR branches, all while utilizing specific technical keywords like PR numbers and SDK documentation.","zh":"赋予代理验证SDK更新的能力，使用bun run download:references，确保一致性和准确性，通过识别以前的版本并检查PR分支，利用特定的技术关键词，如PR编号和SDK文档。","ja":"エージェントがSDKの更新を検証する能力を与え、bun run download:referencesを使用し、一貫性と正確性を確保し、以前のバージョンを識別し、PRブランチをチェックし、特定の技術キーワードsuch as PR番号とSDKドキュメントを利用します。","ko":"에이전트가 SDK 업데이트를 검증할 수 있는 능력을 부여하여 bun run download:references를 사용하고 일관성과 정확성을 보장하며 이전 버전을 식별하고 PR 분기를 확인하며 특정 기술 키워드such as PR 번호 및 SDK 문서를 활용합니다.","es":"Habilita a los agentes a validar las actualizaciones de SDK utilizando bun run download:references, lo que garantiza la coherencia y la precisión al identificar versiones anteriores y comprobar las ramas de PR, todo mientras se utilizan palabras clave técnicas específicas como números de PR y documentación de SDK.","fr":"Permet aux agents de valider les mises à jour de SDK en utilisant bun run download:references, ce qui assure la cohérence et la précision en identifiant les versions précédentes et en vérifiant les branches de PR, le tout en utilisant des mots-clés techniques spécifiques comme les numéros de PR et la documentation de SDK.","de":"Ermächtigt Agenten, SDK-Updates mithilfe von bun run download:references zu validieren, wodurch Konsistenz und Genauigkeit durch die Identifizierung vorheriger Versionen und das Überprüfen von PR-Zweigen sichergestellt werden, und zwar unter Verwendung spezifischer technischer Schlüsselwörter wie PR-Nummern und SDK-Dokumentation.","pt":"Habilita os agentes a validar atualizações de SDK usando bun run download: references, garantindo consistência e precisão identificando versões anteriores e verificando branches de PR, tudo isso utilizando palavras-chave técnicas específicas como números de PR e documentação de SDK.","ru":"Наделяет агентов возможностью проверять обновления SDK с помощью bun run download: references, обеспечивая последовательность и точность путем выявления предыдущих версий и проверки веток PR, все это при использовании конкретных технических ключевых слов, таких как номера PR и документация SDK.","ar":"يمنح الوكلاء القدرة على التحقق من تحديثات SDK باستخدام bun run download: references، ضامنًا الاتساق والدقة من خلال تحديد الإصدارات السابقة والتحقق من فروع PR، وكل ذلك باستخدام كلمات مفتاح تقنية محددة مثل أرقام PR ووثائق SDK."},"useCases":{"en":["Automating SDK update validation for consistency and accuracy","Identifying previous SDK versions for comparison and analysis","Checking out PR branches for thorough review and testing"],"zh":["自动化SDK更新验证以实现一致性和准确性","识别以前的SDK版本以进行比较和分析","检查PR分支以进行彻底审查和测试"],"ja":["一貫性と正確性を確保するためのSDK更新の自動化検証","比較と分析のための以前のSDKバージョンの識別","徹底的なレビューとテストのためのPRブランチのチェック"],"ko":["일관성과 정확성을 보장하기 위한 SDK 업데이트 자동화 검증","比較 및 분석을 위한 이전 SDK 버전 식별","彻底한 검토 및 테스트를 위한 PR 분기 확인"],"es":["Automatizar la validación de actualizaciones de SDK para la coherencia y la precisión","Identificar versiones anteriores de SDK para la comparación y el análisis","Comprobar las ramas de PR para una revisión y pruebas exhaustivas"],"fr":["Automatiser la validation des mises à jour de SDK pour la cohérence et la précision","Identifier les versions précédentes de SDK pour la comparaison et l''analyse","Vérifier les branches de PR pour une révision et des tests exhaustifs"],"de":["Automatisierung der SDK-Update-Validierung für Konsistenz und Genauigkeit","Identifizierung vorheriger SDK-Versionen für Vergleich und Analyse","Überprüfung von PR-Zweigen für eine gründliche Überprüfung und Testung"],"pt":["Automatizar a validação de atualização de SDK para consistência e precisão","Identificar versões anteriores de SDK para comparação e análise","Verificar branches de PR para revisão e teste aprofundados"],"ru":["Автоматизировать проверку обновления SDK для последовательности и точности","Определить предыдущие версии SDK для сравнения и анализа","Проверить ветки PR для тщательного обзора и тестирования"],"ar":["توفير التحقق التلقائي من تحديث SDK من أجل الاتساق والدقة","تحديد الإصدارات السابقة من SDK للمقارنة والتحليل","التحقق من فروع PR من أجل المراجعة والاختبار الشامل"]},"limitations":{"en":["Requires PR branch or PR number","Needs specific SDK and newVersion inputs","Limited to SDK updates using update-sdk-docs"],"zh":["需要PR分支或PR编号","需要特定的SDK和newVersion输入","仅限使用update-sdk-docs的SDK更新"],"ja":["PRブランチまたはPR番号が必要","特定のSDKとnewVersion入力が必要","update-sdk-docsを使用したSDK更新のみ"],"ko":["PR 분기 또는 PR 번호가 필요","특정 SDK 및 newVersion 입력이 필요","update-sdk-docs를 사용한 SDK 업데이트ーのみ"],"es":["Requiere rama de PR o número de PR","Necesita SDK y nuevasVersiones de entrada específicas","Limitado a actualizaciones de SDK que utilizan update-sdk-docs"],"fr":["Nécessite une branche de PR ou un numéro de PR","A besoin de SDK et de nouvellesVersiones d''entrée spécifiques","Limité aux mises à jour de SDK qui utilisent update-sdk-docs"],"de":["Benötigt PR-Zweig oder PR-Nummer","Benötigt spezifische SDK- und newVersion-Eingaben","Begrenzt auf SDK-Updates, die update-sdk-docs verwenden"],"pt":["Exige branch de PR ou número de PR","Necessita de SDK e novosVersion específicos","Limitado a atualizações de SDK usando update-sdk-docs"],"ru":["Требует ветки PR или номера PR","Требует конкретного SDK и новых версий","Ограничен обновлениями SDK с использованием update-sdk-docs"],"ar":["يتطلب فرع PR أو رقم PR","يحتاج إلى SDK وإدخال الإصدار الجديد","محدود بتحديثات SDK باستخدام update-sdk-docs"]},"version":4},"contentHash":"d542b7525ef4c9237df6be6dbad510c2cb1024d899dce2e7639c11268f8f30b6","qualityScore":26}');
