INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('superwall/docs/review-sdk-update-pr', 'review-sdk-update-pr', 'superwall', 'docs', 'community', 'review-sdk-update-pr superwall docs community The review-sdk-update-pr skill automates the validation of SDK updates, benefiting developers by ensuring consistency and accuracy. It checks out the PR branch, runs bun run download:references, and identifies previous versions. review-sdk-update-pr AI工具用于验证SDK更新，确保代码质量和文档准确性 review-sdk-update-pr AIエージェントはSDK更新を検証し、コード品質とドキュメントの正確性を確保します review-sdk-update-pr AI 에이전트는 SDK 업데이트를 검증하여 코드 품질과 문서의 정확성을 보장합니다 El skill review-sdk-update-pr valida las actualizaciones de SDK mediante la creación de una línea de base y la verificación de cambios en la documentación Le skill review-sdk-update-pr valide les mises à jour de SDK en créant une ligne de base et en vérifiant les modifications de la documentation Das Skill review-sdk-update-pr überprüft SDK-Updates durch die Erstellung einer Basislinie und die Überprüfung von Änderungen in der Dokumentation O review-sdk-update-pr é uma habilidade que valida atualizações de SDK. Ele utiliza o fluxo de trabalho de revisão para verificar as alterações. ИИ Агент review-sdk-update-pr - это навык, который проверяет обновления SDK. Он использует рабочий процесс проверки для подтверждения изменений. وكيل مراجعة SDK بالغرض review-sdk-update-pr هو مهارة تتحقق من تحديثات SDK. يستخدم تدفق العمل لمراجعة التغييرات. how to use review-sdk-update-pr review-sdk-update-pr setup guide automated sdk review process bun run download:references mdx file validation review-sdk-update-pr vs manual review sdk update automation what is review-sdk-update-pr review-sdk-update-pr install review-sdk-update-pr tutorial review-sdk-update-pr AI工具 SDK更新 代码质量检查 文档准确性 bun run download:references update-sdk-docs Checks out the PR branch for validation Runs bun run download:references for reference updates Identifies previousVersion from base branch in index.mdx files Validates work produced with update-sdk-docs Uses mdx files for documentation updates Supports PR branch or PR number for flexible review review-sdk-update-pr is a skill that automates the review process for SDK updates, using technical inputs like sdk, newVersion, and PR branch or number.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Renkunzhao/motion_viewer/commit', 'community', 'Renkunzhao', 'motion_viewer', 'Renkunzhao/motion_viewer', 'commit', 1, 0, 26, '2026-03-01T07:05:03Z', '2026-03-07T12:50:19.225Z', '31e84ee71a05e56c5e78d9fe4274c23025ff28ed0b8ee171393cf9db5e8fe0ce', '{"id":"Renkunzhao/motion_viewer/commit","name":"commit","description":{"en":"Commit is a web-based visualization tool for robot models and motion data, benefiting developers and robotics engineers. It summarizes changes based on git state and proposes commit messages following repository standards.","zh":"Commit是一种基于Web的可视化工具，用于robotics模型和motion数据，能够根据git状态生成提交消息","ja":"Commitは、ロボティクスモデルとモーションデータのWebベースの可視化ツールであり、git状態に基づいてコミットメッセージを生成します","ko":"Commit는 로봇 모델 및 모션 데이터의 웹 기반 시각화 도구로 git 상태에 따라 커밋 메시지를 생성합니다","es":"Commit es una herramienta de visualización web para modelos de robots y datos de movimiento que resume los cambios en el estado del repositorio","fr":"Commit est un outil de visualisation web pour les modèles de robots et les données de mouvement qui résume les modifications dans l''état du référentiel","de":"Commit ist ein webbasiertes Visualisierungstool für Robotmodelle und Bewegungsdaten, das die Änderungen im Repository-Zustand zusammenfasst","pt":"O commit é uma ferramenta de visualização de robótica que resume alterações com base no estado do Git. Ele executa comandos Git para coletar informações","ru":"Коммит - это инструмент визуализации робототехники, который суммирует изменения на основе состояния Git. Он выполняет команды Git для сбора информации для ИИ Агентов","ar":"Commit هو أداة تصور الروبوتات التي تómم الزيادات بناءً على حالة Git. وهو ينفذ أوامر Git لجمع المعلومات للوكلاء الذكيين"},"seo":{"title":{"en":"Commit: Git-Based Motion Viewer Setup Guide | AI Agent Skill","zh":"Commit_setup_guide_for_robotics_visualization","ja":"Commitのセットアップガイド：AIエージェントによるロボティクス可視化","ko":"Commit설정 가이드: 로봇 모델 및 모션 데이터 시각화","es":"Guía de configuración de commit para robots","fr":"Guide de mise en place de commit pour la robotique","de":"Commit-Setup-Leitfaden für Robotik","pt":"Guia de Configuração do Commit: Ferramenta de Visualizaçã...","ru":"Настройка Коммита: Инструмент Визуализации Робототехники ...","ar":"دليل إعداد Commit: أداة تصور الروبوتات للوكلاء الذكيين"},"description":{"en":"Unlock efficient robot model visualization with Commit. Discover how to leverage git state and diff outputs for streamlined motion data analysis and commit m...","zh":"使用Commit实现robotics可视化，了解git状态和提交消息的生成","ja":"Commitを使用してロボティクス可視化を実現し、git状態とコミットメッセージの生成を理解する","ko":"Commit를 사용하여 로봇 모델 및 모션 데이터 시각화를 구현하고 git 상태 및 커밋 메시지 생성을 이해합니다","es":"Aprende a utilizar commit para visualizar modelos de robots y datos de movimiento de manera efectiva","fr":"Découvrez comment utiliser commit pour visualiser des modèles de robots et des données de mouvement de manière efficace","de":"Erfahren Sie, wie Sie commit für die Visualisierung von Robotmodellen und Bewegungsdaten nutzen können","pt":"Aprenda a configurar o commit, uma ferramenta de visualização de robótica baseada na web que resume alterações com base no estado do Git","ru":"Узнайте, как настроить коммит, веб-инструмент визуализации робототехники, который суммирует изменения на основе состояния Git для ИИ Агентов","ar":"تعلم كيفية設定 Commit ، أداة تصور الروبوتات المبنية على الويب التي تómم الزيادات بناءً على حالة Git للوكلاء الذكيين"},"definition":{"en":"Commit is a tool that summarizes current work based on a repository''s git state and proposes commit messages, facilitating efficient motion data analysis and version control.","zh":"Commit：一种用于robotics可视化的Web工具，根据git状态生成提交消息","ja":"Commit：ロボティクス可視化用のWebツールであり、git状態に基づいてコミットメッセージを生成する","ko":"Commit: 로봇 모델 및 모션 데이터 시각화를 위한 웹 도구로 git 상태에 따라 커밋 메시지를 생성합니다","es":"Commit es una herramienta de visualización para robots que resume los cambios en el repositorio","fr":"Commit est un outil de visualisation pour les robots qui résume les modifications dans le référentiel","de":"Commit ist ein Visualisierungstool für Robotik, das die Änderungen im Repository zusammenfasst","pt":"O commit é uma ferramenta de visualização de robótica que resume alterações com base no estado do Git","ru":"Коммит - это инструмент визуализации робототехники, который суммирует изменения на основе состояния Git","ar":"Commit هو أداة تصور الروبوتات التي تómم الزيادات بناءً على حالة Git"},"features":{"en":["Collects git state using `git status`, `git diff`, and `git diff --staged` commands","Summarizes changes by file/module, highlighting behavior changes, refactors, and docs changes","Proposes commit messages following repository standards","Utilizes git diff outputs as the source of truth for change summarization","Supports analysis of motion data for robot models"],"zh":["根据git状态生成提交消息","支持git diff和git status命令","能够总结更改并突出行为变化","支持多语言，包括中文"],"ja":["git状態に基づいてコミットメッセージを生成","git diffとgit statusコマンドをサポート","変更を総合し、動作の変更を強調","複数言語をサポート、包括中国語"],"ko":["git 상태에 따라 커밋 메시지를 생성","git diff 및 git status 명령어 지원","변경 사항을 요약하고 동작 변경을 강조","다중 언어 지원, 포함 중국어"],"es":["Resumen de cambios en el estado del repositorio mediante git status y git diff","Propuesta de mensajes de commit según el estándar del repositorio","Visualización de modelos de robots y datos de movimiento","Resumen de cambios por archivo o módulo","Destacado de cambios de comportamiento, refactorizaciones y cambios de documentación"],"fr":["Résumé des modifications dans l''état du référentiel via git status et git diff","Proposition de messages de commit selon la norme du référentiel","Visualisation de modèles de robots et de données de mouvement","Résumé des modifications par fichier ou module","Mise en évidence des modifications de comportement, refactorisations et modifications de documentation"],"de":["Zusammenfassung von Änderungen im Repository-Zustand über git status und git diff","Vorschlag von Commit-Mitteilungen gemäß dem Repository-Standard","Visualisierung von Robotmodellen und Bewegungsdaten","Zusammenfassung von Änderungen pro Datei oder Modul","Hervorhebung von Verhaltensänderungen, Refactorings und Dokumentationsänderungen"],"pt":["Executa comandos Git para coletar informações","Sumariza alterações com base no estado do Git","Destaca mudanças de comportamento versus refatorações versus alterações de documentos","Propõe mensagens de commit seguindo o padrão do repositório","Coleta informações do Git com `git status`, `git diff` e `git diff --staged`"],"ru":["Выполняет команды Git для сбора информации","Суммирует изменения на основе состояния Git","Выделяет изменения поведения против рефакторинга против изменений документов для ИИ Агентов","Предлагает сообщения коммита, следующее стандарту репозитория","Собирает информацию из Git с помощью `git status`, `git diff` и `git diff --staged`"],"ar":["ينفذ أوامر Git لجمع المعلومات","تómم الزيادات بناءً على حالة Git","تسلط الضوء على تغييرات السلوك مقابل إعادة هيكلة مقابل تغييرات الوثائق للوكلاء الذكيين","تقترح رسائل Commit اتباع معيار المستودع","تجمع المعلومات من Git باستخدام `git status` و `git diff` و `git diff --staged`"]},"keywords":{"en":["how to use commit for motion data analysis","commit alternative for robotics engineers","commit setup guide for AI agents","what is commit in robotics","commit vs other visualization tools","install commit for git-based motion viewer"],"zh":["Commit工具","robotics可视化","git状态","提交消息生成","AIエージェント","Web可视化工具"],"ja":["Commitツール","ロボティクス可視化","git状態","コミットメッセージ生成","AIエージェント","Web可視化ツール"],"ko":["Commit도구","로봇 모델 시각화","git 상태","커밋 메시지 생성","AI 에이전트","웹 시각화 도구"],"es":["commit para robots","visualización de modelos de robots","datos de movimiento","git status","git diff","mensajes de commit","estándar del repositorio","herramientas de visualización para robots"],"fr":["commit pour les robots","visualisation de modèles de robots","données de mouvement","git status","git diff","messages de commit","norme du référentiel","outils de visualisation pour les robots"],"de":["commit für Robotik","Visualisierung von Robotmodellen","Bewegungsdaten","git status","git diff","Commit-Mitteilungen","Repository-Standard","Visualisierungstools für Robotik"],"pt":["commit","ferramenta de visualização de robótica","Git","visualização de robótica","sumarizar alterações","propor mensagens de commit","configuração do commit","Guia de configuração do commit"],"ru":["коммит","инструмент визуализации робототехники","Git","визуализация робототехники","суммировать изменения","предлагать сообщения коммита","настройка коммита","ИИ Агенты","инструменты ИИ"],"ar":["commit","أداة تصور الروبوتات","Git","تصور الروبوتات","تómم الزيادات","تقترح رسائل Commit","إعداد Commit","الوكلاء الذكيين","أدوات الذكاء الاصطناعي"]}},"owner":"Renkunzhao","repo":"motion_viewer","repoPath":"Renkunzhao/motion_viewer","stars":1,"forks":0,"updatedAt":"2026-03-01T07:05:03Z","topics":["robotics","visualization"],"category":"community","skillMd":{"name":"commit","description":"Summarize current session changes using git status/diff, then propose 3 Conventional Commit messages with scope limited to model|motion|ui. Only run git commands that read state; never commit/push without approval.","bodyPreview":"# Motion Viewer Commit Helper\n\n## Purpose\nWhen invoked, summarize all current work based on the repository''s git state (diff), then propose commit messages following the repo standard.\n\n## Steps (always follow)\n1) Collect git state (read-only)\n   - Run:\n     - `git status`\n     - `git diff`\n     - `git diff --staged`\n   - Use these outputs as the source of truth.\n\n2) Summarize changes (Chinese)\n   - Summarize by file/module.\n   - Highlight behavior changes vs refactors vs docs changes.\n   - If c","body":"# Motion Viewer Commit Helper\n\n## Purpose\nWhen invoked, summarize all current work based on the repository''s git state (diff), then propose commit messages following the repo standard.\n\n## Steps (always follow)\n1) Collect git state (read-only)\n   - Run:\n     - `git status`\n     - `git diff`\n     - `git diff --staged`\n   - Use these outputs as the source of truth.\n\n2) Summarize changes (Chinese)\n   - Summarize by file/module.\n   - Highlight behavior changes vs refactors vs docs changes.\n   - If changes are large, suggest whether splitting into multiple commits would improve clarity.\n\n3) Propose commit messages (required)\n   - Provide 3 candidate messages:\n     - Conventional Commits: `<type>(<scope>): <subject>`\n   - Allowed scopes: `model`, `motion`, `ui`\n   - Types: feat, fix, refactor, perf, docs, test, build, ci, chore\n   - Subject: English imperative, no trailing period, prefer <= 72 chars\n   - For each candidate, add one Chinese sentence explaining why that type/scope fits.\n\n4) Safety\n   - Do NOT run `git commit`, `git push`, or `gh pr create`.\n   - If the user asks to commit/push, first print the exact commands you would run and wait for explicit approval (per AGENTS.md)."},"lastSynced":"2026-03-07T12:50:19.225Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated commit message generation and git state analysis.","zh":"非常适合需要自动化提交消息生成和git状态分析的代码审查代理。","ja":"コードレビュー代理が自動コミットメッセージ生成とGit状態分析を必要とする場合に最適です。","ko":"자동 커밋 메시지 생성 및 Git 상태 분석이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan generación automática de mensajes de confirmación y análisis de estado de git.","fr":"Parfait pour les agents de révision de code nécessitant une génération automatique de messages de validation et une analyse de l''état de git.","de":"Perfekt für Code-Review-Agents, die eine automatisierte Generierung von Commit-Mitteilungen und eine Analyse des Git-Zustands benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de geração automática de mensagens de commit e análise de estado do git.","ru":"Идеально подходит для Агентов Код-Ревью, которым требуется автоматическая генерация сообщений о коммите и анализ состояния git.","ar":"مثالي للوكلاء المراقبين للتعديلات التي تحتاج إلى إنشاء رسائل الإلتزام التلقائي وتحليل حالة جيت."},"recommendation":{"en":"Empowers agents to summarize changes based on git diff and propose commit messages following repository standards, utilizing git protocols and commands like git status and git diff --staged.","zh":"赋予代理根据git diff总结更改并提出符合仓库标准的提交消息的能力，利用git协议和命令，如git status和git diff --staged。","ja":"Git diffに基づいて変更を要約し、リポジトリの標準に従ったコミットメッセージを提案するエージェントを可能にします。Gitプロトコルとコマンド（git statusやgit diff --stagedなど）を利用します。","ko":"에이전트가 Git diff를 기반으로 변경 사항을 요약하고 저장소 표준을 따르는 커밋 메시지를 제안할 수 있도록 합니다. Git 프로토콜 및 명령어(git status 및 git diff --staged 등)를 활용합니다.","es":"Habilita a los agentes a resumir los cambios en función de git diff y proponer mensajes de confirmación que siguen los estándares del repositorio, utilizando protocolos y comandos de git como git status y git diff --staged.","fr":"Permet aux agents de résumer les modifications en fonction de git diff et de proposer des messages de validation suivant les normes du référentiel, en utilisant des protocoles et des commandes git comme git status et git diff --staged.","de":"Ermächtigt die Agenten, Änderungen basierend auf git diff zusammenzufassen und Commit-Mitteilungen vorzuschlagen, die den Repository-Standards entsprechen, unter Verwendung von Git-Protokollen und -Befehlen wie git status und git diff --staged.","pt":"Habilita os agentes a resumir alterações com base no git diff e propor mensagens de commit seguindo os padrões do repositório, utilizando protocolos e comandos git como git status e git diff --staged.","ru":"Наделяет агентов возможностью суммировать изменения на основе git diff и предлагать сообщения о коммите, следуя стандартам репозитория, используя протоколы и команды git, такие как git status и git diff --staged.","ar":"تمكين الوكلاء من تلخيص التغييرات على أساس جيت ديف ومقترح رسائل الإلتزام اتباعًا لمعايير المستودع، باستخدام بروتوكولات وأوامر جيت مثل جيت ستاتس وجيت ديف --ستيجد."},"useCases":{"en":["Automating commit message generation","Analyzing git state for code changes","Summarizing behavior changes vs refactors vs docs changes"],"zh":["自动化提交消息生成","分析Git状态以检测代码更改","总结行为更改与重构与文档更改"],"ja":["コミットメッセージの自動化","コードの変更を検出するためのGit状態の分析","動作の変更とリファクタリングとドキュメントの変更の要約"],"ko":["커밋 메시지 자동 생성","코드 변경 사항을 감지하기 위한 Git 상태 분석","동작 변경, 리팩토링, 문서 변경 요약"],"es":["Automatización de la generación de mensajes de confirmación","Análisis del estado de git para cambios de código","Resumen de cambios de comportamiento frente a refactores frente a cambios de documentación"],"fr":["Automatisation de la génération de messages de validation","Analyse de l''état de git pour les modifications de code","Résumé des modifications de comportement par rapport aux refacturations par rapport aux modifications de documentation"],"de":["Automatisierung der Generierung von Commit-Mitteilungen","Analyse des Git-Zustands für Code-Änderungen","Zusammenfassung von Verhaltensänderungen im Vergleich zu Refactorings im Vergleich zu Dokumentationsänderungen"],"pt":["Automatizar a geração de mensagens de commit","Analizar o estado do git para alterações de código","Resumir alterações de comportamento vs refactors vs alterações de docs"],"ru":["Автоматизировать генерацию сообщений о коммите","Анализировать состояние git для изменений кода","Суммировать изменения поведения vs рефакторинги vs изменения документации"],"ar":["تأتميم إنشاء رسائل الإلتزام","تحليل حالة جيت من أجل تغييرات تعديل الكود","تلخيص التغييرات السلوكية مقابل إعادة الهيكلة مقابل تغييرات الوثائق"]},"limitations":{"en":["Requires read-only access to git repository","Limited to repositories with established commit message standards"],"zh":["需要对Git仓库的只读访问","仅限于具有既定提交消息标准的仓库"],"ja":["Gitリポジトリへの読み取り専用アクセスが必要","既存のコミットメッセージ標準を持つリポジトリのみに限定"],"ko":["Git 저장소에 대한 읽기 전용 액세스가 필요함","既存의 커밋 메시지 표준을 갖춘 저장소에만 제한됨"],"es":["Requiere acceso de solo lectura al repositorio de git","Limitado a repositorios con estándares de mensaje de confirmación establecidos"],"fr":["Nécessite un accès en lecture seule au référentiel git","Limité aux référentiels avec des normes de message de validation établies"],"de":["Benötigt Lesezugriff auf das Git-Repository","Begrenzt auf Repositorys mit etablierten Commit-Mitteilungsstandards"],"pt":["Requer acesso somente leitura ao repositório git","Limitado a repositórios com padrões de mensagens de commit estabelecidos"],"ru":["Требует доступа только для чтения к репозиторию git","Ограничен репозиториями с установленными стандартами сообщений о коммите"],"ar":["يتطلب الوصول القراءة فقط إلى مستودع جيت","محدود بالمستودعات التي لديها معايير رسائل الإلتزام المحددة"]},"version":4},"contentHash":"31e84ee71a05e56c5e78d9fe4274c23025ff28ed0b8ee171393cf9db5e8fe0ce","qualityScore":26}');
