INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Renkunzhao/motion_viewer/commit', 'commit', 'Renkunzhao', 'motion_viewer', 'community', 'commit Renkunzhao motion_viewer community robotics visualization Commit is a web-based visualization tool for robot models and motion data, benefiting developers and robotics engineers. It summarizes changes based on git state and proposes commit messages following repository standards. Commit是一种基于Web的可视化工具，用于robotics模型和motion数据，能够根据git状态生成提交消息 Commitは、ロボティクスモデルとモーションデータのWebベースの可視化ツールであり、git状態に基づいてコミットメッセージを生成します Commit는 로봇 모델 및 모션 데이터의 웹 기반 시각화 도구로 git 상태에 따라 커밋 메시지를 생성합니다 Commit es una herramienta de visualización web para modelos de robots y datos de movimiento que resume los cambios en el estado del repositorio Commit est un outil de visualisation web pour les modèles de robots et les données de mouvement qui résume les modifications dans l''état du référentiel Commit ist ein webbasiertes Visualisierungstool für Robotmodelle und Bewegungsdaten, das die Änderungen im Repository-Zustand zusammenfasst O commit é uma ferramenta de visualização de robótica que resume alterações com base no estado do Git. Ele executa comandos Git para coletar informações Коммит - это инструмент визуализации робототехники, который суммирует изменения на основе состояния Git. Он выполняет команды Git для сбора информации для ИИ Агентов Commit هو أداة تصور الروبوتات التي تómم الزيادات بناءً على حالة Git. وهو ينفذ أوامر Git لجمع المعلومات للوكلاء الذكيين how to use commit for motion data analysis commit alternative for robotics engineers commit setup guide for AI agents what is commit in robotics commit vs other visualization tools install commit for git-based motion viewer Commit工具 robotics可视化 git状态 提交消息生成 AIエージェント Web可视化工具 Collects git state using `git status`, `git diff`, and `git diff --staged` commands Summarizes changes by file/module, highlighting behavior changes, refactors, and docs changes Proposes commit messages following repository standards Utilizes git diff outputs as the source of truth for change summarization Supports analysis of motion data for robot models Commit is a tool that summarizes current work based on a repository''s git state and proposes commit messages, facilitating efficient motion data analysis and version control.');
