INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('igorder-dev/apex/devil-advocate', 'devil-advocate', 'igorder-dev', 'apex', 'community', 'devil-advocate igorder-dev apex community The devil-advocate skill converts raw ideas into production-ready documentation packs, benefiting developers and architects by providing a structured approach to decision-making. devil-advocate 技术文档生成工具，根据技术选择和架构决策生成生产就绪的文档包 devil-advocate AIエージェントは、技術選択やアーキテクチャ決定時のドキュメント生成をサポートします devil-advocate 문서 자동 생성 도구는 기술문서를 생성하여 개발자들의 생산성을 향상시킵니다 El agente devil-advocate es una herramienta para analizar tecnologías y tomar decisiones informadas. Convierte ideas en documentación de producción lista. L''agent devil-advocate est un outil pour analyser les technologies et prendre des décisions éclairées. Il convertit les idées en packs de documentation de production prêts. Der devil-advocate-Agent ist ein Werkzeug zur Analyse von Technologien und zur fundierten Entscheidungsfindung. Er wandelt Ideen in produktionsbereite Dokumentationspakete um. O Devil-Advocate é um agente de ideia-para-documentação que converte ideias brutas em pacotes de documentação prontos para produção, incluindo análise de tecnologia e escolhas de arquitetura ИИ Агент Devil-Advocate — это агент от идеи до документации, который преобразует сырые идеи в пакеты документации, готовые к производству, включая анализ технологий и архитектурные решения Devil-Advocate هو وكيل فكرة-إلى-توثيق يتحول الأفكار الخام إلى حزم وثائقية جاهزة للإنتاج، بما في ذلك تحليل التكنولوجيا واختيارات الهندسة المعمارية how to use devil-advocate what is devil-advocate devil-advocate alternative devil-advocate vs competitor devil-advocate install devil-advocate setup guide idea-to-documentation conversion structured analysis for AI agents devil-advocate 技术文档生成工具 技术选择文档生成 架构决策文档生成 数据库文档生成 框架文档生成 ADR 文档生成 构建与购买决策文档生成 自动文档生成工具 Activates on technology choices, such as database or framework selections Supports Architectural Decision Records (ADRs) documentation Facilitates build-vs-buy decisions with a structured approach Automatically triggers after every document generation Helps with feature prioritization involving significant tradeoffs devil-advocate is a skill that performs enhanced analysis for idea-to-documentation conversion, using trigger conditions for technology choices and architectural decisions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qte77/RDI-AgentBeats-TestBehaveAlign/committing-staged-with-message', 'community', 'qte77', 'RDI-AgentBeats-TestBehaveAlign', 'qte77/RDI-AgentBeats-TestBehaveAlign', 'committing-staged-with-message', 0, 0, 26, '2026-02-22T21:30:31Z', '2026-03-07T03:41:46.989Z', '7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7', '{"id":"qte77/RDI-AgentBeats-TestBehaveAlign/committing-staged-with-message","name":"committing-staged-with-message","description":{"en":"The committing-staged-with-message skill helps developers analyze staged changes and generate commit messages using Git commands. It benefits developers working with Git version control.","zh":"提交暂存代码并生成提交消息，使用Git命令分析代码变更和提交历史","ja":"ステージ済みコードをコミットし、メッセージを生成します。Gitコマンドを使用してコードの変更を分析し、コミット履歴を確認します","ko":"스테이징된 코드를 커밋하고 커밋 메시지를 생성합니다. Git 명령을 사용하여 코드 변경을 분석하고 커밋 기록을 확인합니다","es":"Comprometer cambios con mensaje generado es crucial para un control de versiones eficaz. Esta guía cubre los pasos necesarios para lograrlo.","fr":"L''engagement de modifications avec message généré est essentiel pour un contrôle de version efficace. Cette guide présente les étapes à suivre.","de":"Das Committen von geänderten Dateien mit generierter Nachricht ist für eine effektive Versionierung unerlässlich. Dieser Leitfaden erklärt die notwendigen Schritte.","pt":"O commit de arquivos com mensagens geradas automaticamente utiliza comandos Git e Bash para analisar alterações e criar mensagens de commit personalizadas.","ru":"Commit изменений с сгенерированным сообщением использует команды Git и Bash для анализа изменений и создания индивидуальных сообщений коммита в ИИ Агентах","ar":"يستخدم-commit الملفات مع رسائل محددة آليا أوامر Git و Bash لتحليل التغييرات وإنشاء رسائل commit مخصصة"},"seo":{"title":{"en":"committing-staged-with-message: Git Commit Setup Guide | ...","zh":"提交暂存代码的最佳实践 - 生成提交消息","ja":"ステージ済みコードのコミット - メッセージ生成ガイド","ko":"커밋 메시지 생성을 위한 스테이징된 코드提交 방법","es":"Guía de configuración para comprometer cambios con mensaj...","fr":"Configurer l''engagement de modifications avec message généré","de":"Einrichtungsleitfaden für das Committen von geänderten Da...","pt":"Guia de Configuração para Commit de Arquivos com Mensagem...","ru":"Настройка ИИ Агентов для Commit Изменений с Сгенерированн...","ar":"دليل إعداد-commit مع رسائل محددة آليا"},"description":{"en":"Streamline your Git workflow with committing-staged-with-message. Learn how to analyze staged changes and generate commit messages using Bash commands like g...","zh":"了解如何使用Git命令提交暂存代码并生成提交消息，包括代码变更分析和提交历史查看","ja":"ステージ済みコードをコミットし、メッセージを生成する方法を学びましょう。Gitコマンドを使用してコードの変更を分析し、コミット履歴を確認します","ko":"커밋 메시지를 생성하여 스테이징된 코드를 제출하는 방법을 알아보세요. Git 명령을 사용하여 코드 변경을 분석하고 커밋 기록을 확인합니다","es":"Aprende a comprometer cambios con mensaje generado de manera efectiva con esta guía paso a paso para desarrolladores","fr":"Découvrez comment configurer l''engagement de modifications avec message généré pour améliorer votre workflow de développement","de":"Erfahren Sie, wie Sie geänderte Dateien mit generierter Nachricht committen, um Ihren Entwicklungsprozess zu optimieren","pt":"Aprenda a configurar o commit de arquivos com mensagens geradas automaticamente utilizando o Git e Bash","ru":"Узнайте, как настроить commit изменений с сгенерированным сообщением, используя Git и Bash в ИИ Агентах","ar":"تعرف على كيفية إعداد-commit الملفات مع رسائل محددة آليا باستخدام Git و Bash"},"definition":{"en":"committing-staged-with-message is a skill that automates Git commit messages based on staged changes, utilizing commands like git diff --staged and git log --oneline.","zh":"提交暂存代码的过程，包括代码变更分析和提交历史查看，以生成提交消息","ja":"ステージ済みコードをコミットするプロセスです。コードの変更を分析し、コミット履歴を確認してメッセージを生成します","ko":"스테이징된 코드를 커밋하는 과정으로, 코드 변경을 분석하고 커밋 기록을 확인하여 커밋 메시지를 생성합니다","es":"Comprometer cambios con mensaje generado es una función que permite a los desarrolladores confirmar cambios en el código con un mensaje automáticamente generado","fr":"L''engagement de modifications avec message généré est une fonctionnalité qui permet aux développeurs de valider des modifications de code avec un message généré automatiquement","de":"Das Committen von geänderten Dateien mit generierter Nachricht ist eine Funktion, die es Entwicklern ermöglicht, Änderungen im Code mit einer automatisch generierten Nachricht zu bestätigen","pt":"Commit de arquivos com mensagens geradas é uma técnica que utiliza comandos Git e Bash para criar mensagens de commit personalizadas","ru":"Commit изменений с сгенерированным сообщением - это техника, использующая команды Git и Bash для создания индивидуальных сообщений коммита в ИИ Агентах","ar":"commit الملفات مع رسائل محددة آليا هو تقنية تستخدم أوامر Git و Bash لإنشاء رسائل commit مخصصة"},"features":{"en":["Analyzes staged changes using git diff --staged --name-only and git diff --staged --stat","Generates commit messages based on staged changes","Reviews detailed staged changes using git diff --staged","Applies a size guard to skip full diff if more than 10 files or 500 lines are changed","Utilizes git log --oneline -5 to review recent commit style"],"zh":["使用Git diff --staged --name-only命令列出暂存文件","使用Git diff --staged --stat命令查看代码变更统计","使用Git log --oneline -5命令查看最近的提交历史","使用Git diff --staged命令查看详细的暂存代码变更","支持 Size guard，自动跳过大量代码变更的提交"],"ja":["Git diff --staged --name-onlyコマンドを使用してステージ済みファイルをリストします","Git diff --staged --statコマンドを使用してコードの変更を統計します","Git log --oneline -5コマンドを使用して最近のコミット履歴を確認します","Git diff --stagedコマンドを使用してステージ済みコードの変更を詳細に確認します","Size guardに対応し、大量のコード変更のコミットを自動でスキップします"],"ko":["Git diff --staged --name-only 명령을 사용하여 스테이징된 파일을 목록화합니다","Git diff --staged --stat 명령을 사용하여 코드 변경을 통계합니다","Git log --oneline -5 명령을 사용하여 최근의 커밋 기록을 확인합니다","Git diff --staged 명령을 사용하여 스테이징된 코드의 변경을详细히 확인합니다","Size guard에 대응하여大量의 코드 변경의 커밋을 자동으로 건너뛰습니다"],"es":["Análisis de cambios con `git diff --staged --name-only`","Resumen de estadísticas de diferencias con `git diff --staged --stat`","Revisión de cambios detallados con `git diff --staged`","Protección de tamaño para evitar mensajes largos","Integración con Git para un flujo de trabajo eficiente"],"fr":["Analyse des modifications avec `git diff --staged --name-only`","Résumé des statistiques de différences avec `git diff --staged --stat`","Examen de modifications détaillées avec `git diff --staged`","Protection de taille pour éviter les messages longs","Intégration avec Git pour un workflow efficace"],"de":["Analyse von Änderungen mit `git diff --staged --name-only`","Zusammenfassung von Statistiken der Differenzen mit `git diff --staged --stat`","Überprüfung von detaillierten Änderungen mit `git diff --staged`","Größenschutz, um lange Nachrichten zu vermeiden","Integration mit Git für einen effizienten Workflow"],"pt":["Utiliza comandos Git como `git diff --staged --name-only` e `git diff --staged --stat`","Análise de alterações com `git log --oneline -5` e `git diff --staged`","Criação de mensagens de commit personalizadas com base nas alterações","Suporte a limites de tamanho de alterações com `--stat` e `--name-only`","Integração com Bash para automação de tarefas"],"ru":["Использует команды Git, такие как `git diff --staged --name-only` и `git diff --staged --stat`","Анализ изменений с помощью `git log --oneline -5` и `git diff --staged` в ИИ Агентах","Создание индивидуальных сообщений коммита на основе изменений","Поддержка ограничений размера изменений с помощью `--stat` и `--name-only`","Интеграция с Bash для автоматизации задач"],"ar":["يستخدم أوامر Git مثل `git diff --staged --name-only` و `git diff --staged --stat`","تحليل التغييرات باستخدام `git log --oneline -5` و `git diff --staged`","إنشاء رسائل commit مخصصة بناءً على التغييرات","دعم حدود حجم التغييرات مع `--stat` و `--name-only`","التكامل مع Bash لأتمتة المهام"]},"keywords":{"en":["how to use committing-staged-with-message","what is committing-staged-with-message","committing-staged-with-message alternative","committing-staged-with-message vs git commit","committing-staged-with-message setup guide","committing-staged-with-message install"],"zh":["提交暂存代码","生成提交消息","Git命令","代码变更分析","提交历史查看","AI工具","自动化提交"],"ja":["ステージ済みコードのコミット","メッセージ生成","Gitコマンド","コードの変更分析","コミット履歴の確認","AIエージェント","自動化コミット"],"ko":["스테이징된 코드 제출","커밋 메시지 생성","Git 명령","코드 변경 분석","커밋 기록 확인","AI 도구","자동화 제출"],"es":["comprometer cambios con mensaje generado","git diff","control de versiones","desarrollo de software","integración con Git","herramientas de desarrollo","mejora del flujo de trabajo"],"fr":["engagement de modifications avec message généré","git diff","contrôle de version","développement de logiciels","intégration avec Git","outils de développement","amélioration du workflow"],"de":["committen von geänderten Dateien mit generierter Nachricht","git diff","Versionierung","Softwareentwicklung","Integration mit Git","Entwicklungstools","Workflow-Optimierung"],"pt":["commit de arquivos com mensagens geradas","git diff","git log","bash","automatização de tarefas","controle de versão"],"ru":["commit изменений с сгенерированным сообщением","ИИ Агенты","git diff","git log","bash","автоматизация задач","контроль версий"],"ar":["commit الملفات مع رسائل محددة آليا","أدوات الذكاء الاصطناعي","git diff","git log","bash","أتمتة المهام","مراقبة الإصدار"]}},"owner":"qte77","repo":"RDI-AgentBeats-TestBehaveAlign","repoPath":"qte77/RDI-AgentBeats-TestBehaveAlign","stars":0,"forks":0,"updatedAt":"2026-02-22T21:30:31Z","topics":[],"category":"community","skillMd":{"name":"committing-staged-with-message","description":"Generate commit message for staged changes, pause for approval, then commit. Stage files first with `git add`, then run this skill.","bodyPreview":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2:","body":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2: Generate Commit Message\n\nUse the Read tool to check `.gitmessage` for commit message format and syntax.\n\n**The commit message body MUST include (concisely — no padding, no redundancy):**\n\n1. **What changed**: bullet points per file or logical group\n2. **Symbols added/removed** (when applicable): functions, classes, tests\n3. **Diff stats**: lines added/removed (from `--stat` summary line) — MUST be the last line of the body\n   - Format: `+ symbol_name`, `- symbol_name`\n   - Omit for config/docs/formatting-only changes\n\nKeep the message laser-focused. Do not repeat the subject line in the body.\n\n## Step 3: Pause for Approval\n\n**Please review the commit message.**\n\n- **Approve**: \"yes\", \"y\", \"commit\", \"go ahead\"\n- **Edit**: Provide your preferred message\n- **Cancel**: \"no\", \"cancel\", \"stop\"\n\n## Step 4: Commit\n\nOnce approved:\n\n- `git commit --gpg-sign -m \"[message]\"` - Commit staged changes with approved message (GPG signature mandatory)\n- `git status` - Verify success\n"},"lastSynced":"2026-03-07T03:41:46.989Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing automated Git commit message generation capabilities.","zh":"适合需要自动化 Git 提交消息生成能力的版本控制代理。","ja":"自動化されたGitコミットメッセージ生成機能を必要とするバージョンコントロールエージェントに適しています。","ko":"자동화된 Git 커밋 메시지 생성 기능이 필요한 버전 제어 에이전트에 적합합니다.","es":"Ideal para agentes de control de versiones que necesitan capacidades de generación automática de mensajes de confirmación de Git.","fr":"Idéal pour les agents de contrôle de version nécessitant des capacités de génération automatique de messages de commit Git.","de":"Ideal für Version Control Agents, die automatisierte Git-Commit-Nachrichtengenerierungsfunktionen benötigen.","pt":"Ideal para Agentes de Controle de Versão que necessitam de capacidades de geração automatizada de mensagens de commit do Git.","ru":"Идеально для агентов контроля версий, которым требуются автоматические возможности генерации сообщений о фиксации в Git.","ar":"مثالي لعميليات التحكم في الإصدار التي تحتاج إلى إمكانيات توليد رسائل الإلتزام الآلي في Git."},"recommendation":{"en":"Empowers agents to analyze staged changes using Git commands like `git diff --staged` and generate commit messages, streamlining the development workflow with Git version control and Bash tool integration.","zh":"赋予代理分析暂存更改使用 Git 命令如 `git diff --staged` 生成提交消息的能力，简化了 Git 版本控制和 Bash 工具集成的开发工作流程。","ja":"エージェントに、`git diff --staged` のような Git コマンドを使用してステージされた変更を分析し、コミットメッセージを生成する機能を付与し、Git のバージョン管理と Bash ツールの統合による開発ワークフローを最適化します。","ko":"에이전트가 `git diff --staged`와 같은 Git 명령을 사용하여 스테이징된 변경 사항을 분석하고 커밋 메시지를 생성할 수 있는 기능을 부여하여 Git 버전 제어와 Bash 툴 통합에 의한 개발 워크플로우를 최적화합니다.","es":"Habilita a los agentes a analizar los cambios en espera utilizando comandos de Git como `git diff --staged` y generar mensajes de confirmación, simplificando el flujo de trabajo de desarrollo con control de versiones de Git y integración de herramientas de Bash.","fr":"Permet aux agents d''analyser les modifications en attente en utilisant des commandes Git comme `git diff --staged` et de générer des messages de commit, rationalisant ainsi le flux de travail de développement avec le contrôle de version Git et l''intégration d''outils Bash.","de":"Ermächtigt Agenten, vorgemerkte Änderungen mithilfe von Git-Befehlen wie `git diff --staged` zu analysieren und Commit-Nachrichten zu generieren, wodurch der Entwicklungsworkflow mit Git-Versionskontrolle und Bash-Tool-Integration rationalisiert wird.","pt":"Habilita os agentes a analisar alterações em estágio usando comandos Git como `git diff --staged` e gerar mensagens de commit, otimizando o fluxo de trabalho de desenvolvimento com integração de controle de versão Git e ferramenta Bash.","ru":"Наделяет агентов возможностью анализировать изменённые файлы в очереди с помощью команд Git, таких как `git diff --staged`, и генерировать сообщения о фиксации, оптимизируя процесс разработки при помощи интеграции контроля версий Git и утилиты Bash.","ar":"تمكّن العميليات من تحليل التغييرات المحتضنة باستخدام أوامر Git مثل `git diff --staged` وتوليد رسائل الإلتزام، وتبسيط تدفق عمل التطوير مع إدماج التحكم في الإصدار Git وأداة Bash."},"useCases":{"en":["Automating commit message generation","Analyzing staged changes with `git diff --staged --stat`","Generating commit messages based on detailed staged changes"],"zh":["自动化提交消息生成","使用 `git diff --staged --stat` 分析暂存的变化","根据详细的暂存变化生成提交消息"],"ja":["コミットメッセージの自動生成","`git diff --staged --stat` を使用してステージされた変更を分析する","詳細なステージされた変更に基づいてコミットメッセージを生成する"],"ko":["커밋 메시지 자동 생성","`git diff --staged --stat`를 사용하여 스테이징된 변경 사항을 분석","상세한 스테이징된 변경 사항을 기반으로 커밋 메시지를 생성"],"es":["Automatizar la generación de mensajes de confirmación","Analizar los cambios en espera con `git diff --staged --stat`","Generar mensajes de confirmación en función de los cambios en espera detallados"],"fr":["Automatiser la génération de messages de commit","Analyser les modifications en attente avec `git diff --staged --stat`","Générer des messages de commit en fonction des modifications en attente détaillées"],"de":["Automatisierung der Commit-Nachrichtengenerierung","Analyse von vorgemerkten Änderungen mit `git diff --staged --stat`","Generierung von Commit-Nachrichten basierend auf detaillierten vorgemerkten Änderungen"],"pt":["Automatizar a geração de mensagens de commit","Analizar alterações em estágio com `git diff --staged --stat`","Gerar mensagens de commit com base em alterações em estágio detalhadas"],"ru":["Автоматизировать генерацию сообщений о фиксации","Анализировать изменённые файлы в очереди с помощью `git diff --staged --stat`","Генерировать сообщения о фиксации на основе подробных изменений в файле"],"ar":["تألييف رسائل الإلتزام آليا","تحليل التغييرات المحتضنة باستخدام `git diff --staged --stat`","توليد رسائل الإلتزام основة على التغييرات المحتضنة المفصلة"]},"limitations":{"en":["Requires Git installation","Bash tool access needed","Size guard limits detailed diff review to 10 files or 500 lines changed"],"zh":["需要 Git 安装","需要 Bash 工具访问","大小守护限制详细 diff 审查至 10 个文件或 500 行更改"],"ja":["Git のインストールが必要","Bash ツールへのアクセスが必要","サイズガードにより、詳細な diff レビューが 10 ファイルまたは 500 行の変更に制限される"],"ko":["Git 설치가 필요","Bash 툴 액세스가 필요","크기 감시로 인해详细한 diff 리뷰가 10개 파일 또는 500행의 변경으로 제한"],"es":["Requiere instalación de Git","Se necesita acceso a la herramienta Bash","El límite de tamaño limita la revisión detallada de la diferencia a 10 archivos o 500 líneas cambiadas"],"fr":["Nécessite l''installation de Git","L''accès à l''outil Bash est nécessaire","La limite de taille limite la révision détaillée de la différence à 10 fichiers ou 500 lignes modifiées"],"de":["Benötigt Git-Installation","Zugriff auf das Bash-Tool ist erforderlich","Die Größengrenze beschränkt die detaillierte Überprüfung der Differenz auf 10 Dateien oder 500 geänderte Zeilen"],"pt":["Requer instalação do Git","Acesso à ferramenta Bash necessário","Limitador de tamanho limita a revisão detalhada do diff a 10 arquivos ou 500 linhas alteradas"],"ru":["Требуется установка Git","Необходим доступ к утилите Bash","Ограничитель размера ограничивает подробный обзор diff до 10 файлов или 500 изменённых строк"],"ar":["يتطلب تثبيت Git","필요 وصول إلى أداة Bash","حاجز الحجم يقيد الاستعراض المفصل للفرق إلى 10 ملفات أو 500 سطر محدث"]},"version":4},"contentHash":"7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7","qualityScore":26}');
