INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('qte77/RDI-AgentBeats-TestBehaveAlign/committing-staged-with-message', 'committing-staged-with-message', 'qte77', 'RDI-AgentBeats-TestBehaveAlign', 'community', 'committing-staged-with-message qte77 RDI-AgentBeats-TestBehaveAlign community The committing-staged-with-message skill helps developers analyze staged changes and generate commit messages using Git commands. It benefits developers working with Git version control. 提交暂存代码并生成提交消息，使用Git命令分析代码变更和提交历史 ステージ済みコードをコミットし、メッセージを生成します。Gitコマンドを使用してコードの変更を分析し、コミット履歴を確認します 스테이징된 코드를 커밋하고 커밋 메시지를 생성합니다. Git 명령을 사용하여 코드 변경을 분석하고 커밋 기록을 확인합니다 Comprometer cambios con mensaje generado es crucial para un control de versiones eficaz. Esta guía cubre los pasos necesarios para lograrlo. L''engagement de modifications avec message généré est essentiel pour un contrôle de version efficace. Cette guide présente les étapes à suivre. Das Committen von geänderten Dateien mit generierter Nachricht ist für eine effektive Versionierung unerlässlich. Dieser Leitfaden erklärt die notwendigen Schritte. O commit de arquivos com mensagens geradas automaticamente utiliza comandos Git e Bash para analisar alterações e criar mensagens de commit personalizadas. Commit изменений с сгенерированным сообщением использует команды Git и Bash для анализа изменений и создания индивидуальных сообщений коммита в ИИ Агентах يستخدم-commit الملفات مع رسائل محددة آليا أوامر Git و Bash لتحليل التغييرات وإنشاء رسائل commit مخصصة how to use committing-staged-with-message what is committing-staged-with-message committing-staged-with-message alternative committing-staged-with-message vs git commit committing-staged-with-message setup guide committing-staged-with-message install 提交暂存代码 生成提交消息 Git命令 代码变更分析 提交历史查看 AI工具 自动化提交 Analyzes staged changes using git diff --staged --name-only and git diff --staged --stat Generates commit messages based on staged changes Reviews detailed staged changes using git diff --staged Applies a size guard to skip full diff if more than 10 files or 500 lines are changed Utilizes git log --oneline -5 to review recent commit style committing-staged-with-message is a skill that automates Git commit messages based on staged changes, utilizing commands like git diff --staged and git log --oneline.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cherryroots/voltgpt/go-check', 'community', 'cherryroots', 'voltgpt', 'cherryroots/voltgpt', 'go-check', 0, 0, 26, '2026-03-06T11:03:07Z', '2026-03-07T03:47:48.841Z', 'fd383fa11216defcd6753bdd41568a3509be3ff57caa0a551135eabfa984c3cb', '{"id":"cherryroots/voltgpt/go-check","name":"go-check","description":{"en":"The go-check skill validates Go projects by running specific commands, benefiting developers who need to ensure their code is error-free and up-to-date.","zh":"Go-Check 是一个运行 Go Vet 和 Build 命令的工具，用于检查代码质量和更新 binary","ja":"Go-Check は、コード品質をチェックし、バイナリを更新するために Go Vet とビルド コマンドを実行するツールです","ko":"Go-Check는 코드 품질을 확인하고 바이너리를 업데이트하기 위해 Go Vet 및 빌드 명령을 실행하는 도구입니다","es":"go-check es una herramienta que verifica y compila código Go. Se ejecuta en /home/bot/dev/bots/voltgpt y reporta resultados.","fr":"go-check est un outil qui vérifie et compile du code Go. Il s''exécute dans /home/bot/dev/bots/voltgpt et rapporte les résultats.","de":"go-check ist ein Tool, das Go-Code überprüft und compiliert. Es wird in /home/bot/dev/bots/voltgpt ausgeführt und berichtet Ergebnisse.","pt":"O go-check é uma ferramenta para verificar e compilar binários em projetos Go, garantindo a qualidade do código","ru":"ИИ Агент go-check предназначен для проверки и компиляции бинарных файлов в проектах на языке Go, обеспечивая качество кода","ar":"وظيفة go-check هي فحص وتجميع الملفات الثنائية في مشاريع Go، مما يضمن جودة الشفرة"},"seo":{"title":{"en":"go-check: Go Language Validation Setup Guide | AI Agent S...","zh":"Go-Check 设置指南：运行 Go Vet 和 Build","ja":"Go-Check セットアップガイド: Go Vet とビルドの実行","ko":"Go-Check 설정 가이드: Go Vet 및 빌드 실행","es":"Guía de configuración de go-check para desarrolladores","fr":"Guide de mise en œuvre de go-check pour les développeurs","de":"Einrichtungsleitfaden für go-check für Entwickler","pt":"Guia de Configuração do go-check para Desenvolvedores","ru":"Настройка ИИ Агента go-check: Лучшие Практики","ar":"دليل إعداد go-check للبرمجة"},"description":{"en":"Discover how to validate your Go projects with go-check. Learn to identify warnings, build errors, and update binaries successfully. Get started now!","zh":"了解如何使用 Go-Check 运行 Go Vet 和 Build 命令，确保代码质量和 binary 更新","ja":"Go-Check を使用して Go Vet とビルド コマンドを実行し、コード品質とバイナリの更新を確認する方法について学びます","ko":"Go-Check를 사용하여 Go Vet 및 빌드 명령을 실행하고 코드 품질 및 바이너리 업데이트를 확인하는 방법에 대해 알아보세요","es":"Aprende a utilizar go-check para verificar y compilar código Go de manera efectiva. Descubre cómo ejecutar comandos y solucionar errores.","fr":"Découvrez comment utiliser go-check pour vérifier et compiler du code Go de manière efficace. Apprenez à exécuter des commandes et à résoudre les erreurs.","de":"Erfahren Sie, wie Sie go-check verwenden, um Go-Code effektiv zu überprüfen und zu compilen. Lernen Sie, Befehle auszuführen und Fehler zu beheben.","pt":"Aprenda a configurar e executar o go-check com sucesso, incluindo a verificação de warnings e build de binários","ru":"Узнайте, как настроить и запустить go-check, включая проверку предупреждений и сборку бинарных файлов для ИИ Агентов","ar":"تعلم كيفية تشغيل وتثبيت go-check بنجاح، بما في ذلك فحص التحذيرات وإنشاء الملفات الثنائية"},"definition":{"en":"go-check is a validation tool that runs Go vet and build commands to identify warnings and errors, ensuring successful binary updates.","zh":"Go-Check 是一个用于运行 Go Vet 和 Build 命令的工具，用于检查代码质量和更新 binary","ja":"Go-Check は、Go Vet とビルド コマンドを実行してコード品質をチェックし、バイナリを更新するツールです","ko":"Go-Check는 Go Vet 및 빌드 명령을 실행하여 코드 품질을 확인하고 바이너리를 업데이트하는 도구입니다","es":"go-check es una herramienta de verificación y compilación de código Go que utiliza comandos como go vet y go build.","fr":"go-check est un outil de vérification et de compilation de code Go qui utilise des commandes comme go vet et go build.","de":"go-check ist ein Tool zur Überprüfung und Compilierung von Go-Code, das Befehle wie go vet und go build verwendet.","pt":"O go-check é uma ferramenta de linha de comando para verificar e compilar binários em projetos Go","ru":"ИИ Агент go-check - это командная утилита для проверки и компиляции бинарных файлов в проектах на языке Go","ar":"go-check هو أداة سطر أوامر لفحص وتجميع الملفات الثنائية في مشاريع Go"},"features":{"en":["Runs /usr/local/go/bin/go vet ./... to report all warnings","Executes /usr/local/go/bin/go build -o voltgpt to report build errors","Confirms binary updates upon successful validation","Displays full error output for failed validations"],"zh":["运行 Go Vet 命令检查代码质量","运行 Go Build 命令更新 binary","报告代码警告和错误","确认 binary 更新成功"],"ja":["Go Vet コマンドを実行してコード品質をチェック","Go Build コマンドを実行してバイナリを更新","コード警告とエラーを報告","バイナリの更新を確認"],"ko":["Go Vet 명령을 실행하여 코드 품질을 확인","Go Build 명령을 실행하여 바이너리를 업데이트","코드 경고와 오류를 보고","바이너리 업데이트를 확인"],"es":["Ejecuta go vet para reportar advertencias","Ejecuta go build para compilar el código","Reporta errores de compilación","Confirma la actualización del binario","Muestra la salida de error completa para solucionar problemas"],"fr":["Exécute go vet pour signaler les avertissements","Exécute go build pour compiler le code","Signale les erreurs de compilation","Confirme la mise à jour du binaire","Affiche la sortie d''erreur complète pour résoudre les problèmes"],"de":["Führt go vet aus, um Warnungen zu melden","Führt go build aus, um den Code zu compilen","Meldet Compilierungsfehler","Bestätigt die Aktualisierung des Binärs","Zeigt die vollständige Fehlerausgabe an, um Probleme zu beheben"],"pt":["Verificação de warnings com `/usr/local/go/bin/go vet ./...`","Compilação de binários com `/usr/local/go/bin/go build -o voltgpt`","Relatório de erros de compilação","Atualização de binários com sucesso","Suporte a projetos Go"],"ru":["Проверка предупреждений с помощью `/usr/local/go/bin/go vet ./...`","Сборка бинарных файлов с помощью `/usr/local/go/bin/go build -o voltgpt`","Отчет об ошибках сборки","Успешное обновление бинарных файлов","Поддержка проектов на языке Go для ИИ Агентов"],"ar":["فحص التحذيرات باستخدام `/usr/local/go/bin/go vet ./...`","إنشاء الملفات الثنائية باستخدام `/usr/local/go/bin/go build -o voltgpt`","تقرير الأخطاء في عملية البناء","تحديث الملفات الثنائية بنجاح","دعم مشاريع Go للأدوات الذكية"]},"keywords":{"en":["how to use go-check","go-check setup guide","go language validation","go-check alternative","go-check vs golint","go-check install","what is go-check","go-check for AI agents","go project validation"],"zh":["Go-Check","Go Vet","Go Build","代码质量检查","binary 更新","AIエージェント"],"ja":["Go-Check","Go Vet","Go Build","コード品質チェック","バイナリの更新","AIエージェント"],"ko":["Go-Check","Go Vet","Go Build","코드 품질 확인","바이너리 업데이트","AI 에이전트"],"es":["go-check","herramientas de desarrollo de Go","compilación de Go","verificación de código Go","go vet","go build","desarrollo de software"],"fr":["go-check","outils de développement Go","compilation Go","vérification de code Go","go vet","go build","développement de logiciels"],"de":["go-check","Go-Entwicklungstools","Go-Compilierung","Go-Code-Überprüfung","go vet","go build","Software-Entwicklung"],"pt":["go-check","ferramenta de linha de comando","verificação de warnings","compilação de binários","projetos Go","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["go-check","ИИ Агенты","командная утилита","проверка предупреждений","сборка бинарных файлов","проекты на языке Go","разработка программного обеспечения","инструменты разработки"],"ar":["go-check","أداة سطر أوامر","فحص التحذيرات","إنشاء الملفات الثنائية","مشاريع Go","برمجة","أدوات البرمجة","تطوير البرمجيات"]}},"owner":"cherryroots","repo":"voltgpt","repoPath":"cherryroots/voltgpt","stars":0,"forks":0,"updatedAt":"2026-03-06T11:03:07Z","topics":[],"category":"community","skillMd":{"name":"go-check","description":"Build and vet the voltgpt bot, reporting compilation or static analysis errors","bodyPreview":"Run the following commands in /home/bot/dev/bots/voltgpt and report results:\n\n1. `/usr/local/go/bin/go vet ./...` — report all warnings\n2. `/usr/local/go/bin/go build -o voltgpt` — report any build errors\n3. If both pass, confirm the binary was updated successfully\n4. If either fails, show the full error output so it can be fixed","body":"Run the following commands in /home/bot/dev/bots/voltgpt and report results:\n\n1. `/usr/local/go/bin/go vet ./...` — report all warnings\n2. `/usr/local/go/bin/go build -o voltgpt` — report any build errors\n3. If both pass, confirm the binary was updated successfully\n4. If either fails, show the full error output so it can be fixed\n"},"lastSynced":"2026-03-07T03:47:48.841Z","agentAnalysis":{"suitability":{"en":"Ideal for Go Development Agents requiring automated code validation and error detection.","zh":"适用于需要自动代码验证和错误检测的 Go 开发代理。","ja":"Go 開発エージェントが自動コード検証とエラーディテクションを必要とする場合に最適です。","ko":"자동 코드 검증 및 오류 감지 기능이 필요한 Go 개발 에이전트에게 적합합니다.","es":"Ideal para agentes de desarrollo de Go que requieren validación de código automatizada y detección de errores.","fr":"Idéal pour les agents de développement Go nécessitant une validation de code automatisée et une détection d''erreurs.","de":"Ideal für Go-Entwicklungsagenten, die eine automatisierte Codevalidierung und Fehlererkennung erfordern.","pt":"Ideal para Agentes de Desenvolvimento Go que exigem validação de código automatizada e detecção de erros.","ru":"Идеально для агентов разработки Go, требующих автоматизированной проверки кода и обнаружения ошибок.","ar":"مثالي لعميل تطوير Go الذي يتطلب التحقق التلقائي من الشفرة والكشف عن الأخطاء."},"recommendation":{"en":"Empowers agents to validate Go projects by running specific commands like `/usr/local/go/bin/go vet ./...` and `/usr/local/go/bin/go build -o voltgpt`, ensuring error-free and up-to-date code through Go''s built-in tools and protocols.","zh":"赋予代理运行特定命令（如 `/usr/local/go/bin/go vet ./...` 和 `/usr/local/go/bin/go build -o voltgpt`）以验证 Go 项目的能力，确保代码通过 Go 的内置工具和协议无误且最新。","ja":"エージェントが特定のコマンド（例： `/usr/local/go/bin/go vet ./...` および `/usr/local/go/bin/go build -o voltgpt`）を実行して Go プロジェクトを検証する機能を提供し、Go のビルトインツールとプロトコルを通じてエラーフリーで最新のコードを保証します。","ko":"에이전트가 특정 명령어(``/usr/local/go/bin/go vet ./...`` 및 `/usr/local/go/bin/go build -o voltgpt``)를 실행하여 Go 프로젝트를 검증할 수 있는 기능을 제공하여, Go의 내장 도구 및 프로토콜을 통해 오류가 없는 최신 코드를 보장합니다.","es":"Permite a los agentes validar proyectos de Go ejecutando comandos específicos como `/usr/local/go/bin/go vet ./...` y `/usr/local/go/bin/go build -o voltgpt`, garantizando un código sin errores y actualizado a través de las herramientas y protocolos integrados de Go.","fr":"Permet aux agents de valider les projets Go en exécutant des commandes spécifiques comme `/usr/local/go/bin/go vet ./...` et `/usr/local/go/bin/go build -o voltgpt`, garantissant un code sans erreurs et à jour grâce aux outils et protocoles intégrés de Go.","de":"Ermöglicht es den Agenten, Go-Projekte zu validieren, indem sie spezifische Befehle wie `/usr/local/go/bin/go vet ./...` und `/usr/local/go/bin/go build -o voltgpt` ausführen, und stellt so sicher, dass der Code fehlerfrei und aktuell ist, dank der integrierten Tools und Protokolle von Go.","pt":"Habilita os agentes a validar projetos Go executando comandos específicos como `/usr/local/go/bin/go vet ./...` e `/usr/local/go/bin/go build -o voltgpt`, garantindo um código sem erros e atualizado por meio das ferramentas e protocolos internos do Go.","ru":"Наделяет агентов возможностью проверять проекты Go, выполняя специальные команды, такие как `/usr/local/go/bin/go vet ./...` и `/usr/local/go/bin/go build -o voltgpt`, гарантируя код без ошибок и актуальный за счет встроенных инструментов и протоколов Go.","ar":"يمنح الوكلاء القدرة على التحقق من مشاريع Go من خلال تشغيل أوامر محددة مثل `/usr/local/go/bin/go vet ./...` و `/usr/local/go/bin/go build -o voltgpt` ، مما يضمن شفرة خالية من الأخطاء ومحدّثة من خلال أدوات وبروتوكولات Go المدمجة."},"useCases":{"en":["Validating Go code for errors and warnings","Automating Go project builds","Debugging Go binaries with detailed error outputs"],"zh":["验证 Go 代码中的错误和警告","自动化 Go 项目构建","使用详细错误输出调试 Go 二进制文件"],"ja":["Go コードのエラーと警告の検証","Go プロジェクトの自動ビルド","詳細なエラー出力で Go バイナリをデバッグ"],"ko":["Go 코드의 오류 및 경고 검증","Go 프로젝트 자동화 빌드","상세한 오류 출력으로 Go 바이너리 디버깅"],"es":["Validar el código de Go para errores y advertencias","Automatizar las compilaciones de proyectos de Go","Depurar binarios de Go con salidas de errores detalladas"],"fr":["Valider le code Go pour les erreurs et les avertissements","Automatiser la construction de projets Go","Déboguer les binaires Go avec des sorties d''erreurs détaillées"],"de":["Go-Code auf Fehler und Warnungen überprüfen","Automatisieren von Go-Projektbuilds","Go-Binaries mit detaillierten Fehlerausgaben debuggen"],"pt":["Validar código Go para erros e avisos","Automatizar compilações de projetos Go","Depurar binários Go com saídas de erro detalhadas"],"ru":["Проверка кода Go на ошибки и предупреждения","Автоматизация сборки проектов Go","Отладка двоичных файлов Go с подробными сообщениями об ошибках"],"ar":["التحقق من شفرة Go لأخطاء وتنبيهات","تأتمة بناء مشاريع Go","تصحيح أخطاء ثنائيات Go مع مخرجات أخطاء مفصلة"]},"limitations":{"en":["Requires Go installation and configuration","Limited to Go projects","Needs filesystem access to run commands"],"zh":["需要 Go 安装和配置","仅限 Go 项目","需要文件系统访问权限以运行命令"],"ja":["Go のインストールと設定が必要","Go プロジェクトのみ","コマンドを実行するためにファイルシステムへのアクセスが必要"],"ko":["Go 설치 및 구성이 필요","Go 프로젝트만 해당","명령어를 실행하기 위해 파일 시스템 접근 권한이 필요"],"es":["Requiere instalación y configuración de Go","Limitado a proyectos de Go","Necesita acceso al sistema de archivos para ejecutar comandos"],"fr":["Nécessite l''installation et la configuration de Go","Limité aux projets Go","Nécessite un accès au système de fichiers pour exécuter des commandes"],"de":["Benötigt Go-Installation und -Konfiguration","Begrenzt auf Go-Projekte","Benötigt Dateisystemzugriff, um Befehle auszuführen"],"pt":["Exige instalação e configuração do Go","Limitado a projetos Go","Necessita de acesso ao sistema de arquivos para executar comandos"],"ru":["Требует установки и настройки Go","Ограничен проектами Go","Требует доступа к файловой системе для выполнения команд"],"ar":["يتطلب تثبيت وتكوين Go","محدود لمشاريع Go","يحتاج إلى الوصول إلى نظام الملفات لتشغيل الأوامر"]},"version":4},"contentHash":"fd383fa11216defcd6753bdd41568a3509be3ff57caa0a551135eabfa984c3cb","qualityScore":26}');
