INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cherryroots/voltgpt/go-check', 'go-check', 'cherryroots', 'voltgpt', 'community', 'go-check cherryroots voltgpt community The go-check skill validates Go projects by running specific commands, benefiting developers who need to ensure their code is error-free and up-to-date. Go-Check 是一个运行 Go Vet 和 Build 命令的工具，用于检查代码质量和更新 binary Go-Check は、コード品質をチェックし、バイナリを更新するために Go Vet とビルド コマンドを実行するツールです Go-Check는 코드 품질을 확인하고 바이너리를 업데이트하기 위해 Go Vet 및 빌드 명령을 실행하는 도구입니다 go-check es una herramienta que verifica y compila código Go. Se ejecuta en /home/bot/dev/bots/voltgpt y reporta resultados. go-check est un outil qui vérifie et compile du code Go. Il s''exécute dans /home/bot/dev/bots/voltgpt et rapporte les résultats. go-check ist ein Tool, das Go-Code überprüft und compiliert. Es wird in /home/bot/dev/bots/voltgpt ausgeführt und berichtet Ergebnisse. O go-check é uma ferramenta para verificar e compilar binários em projetos Go, garantindo a qualidade do código ИИ Агент go-check предназначен для проверки и компиляции бинарных файлов в проектах на языке Go, обеспечивая качество кода وظيفة go-check هي فحص وتجميع الملفات الثنائية في مشاريع Go، مما يضمن جودة الشفرة how to use go-check go-check setup guide go language validation go-check alternative go-check vs golint go-check install what is go-check go-check for AI agents go project validation Go-Check Go Vet Go Build 代码质量检查 binary 更新 AIエージェント Runs /usr/local/go/bin/go vet ./... to report all warnings Executes /usr/local/go/bin/go build -o voltgpt to report build errors Confirms binary updates upon successful validation Displays full error output for failed validations go-check is a validation tool that runs Go vet and build commands to identify warnings and errors, ensuring successful binary updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vativa/WeatherForecast/Favourite Location', 'community', 'vativa', 'WeatherForecast', 'vativa/WeatherForecast', 'Favourite Location', 0, 0, 26, '2026-01-29T14:40:58Z', '2026-03-07T03:48:56.720Z', 'b6e95d3b1239156f6c205a104877ece1c0007a629970c61a0617995625cc70f4', '{"id":"vativa/WeatherForecast/Favourite Location","name":"Favourite Location","description":{"en":"The Favourite Location skill enables developers to create functionality for keeping favourite locations using JavaScript and Redux. It benefits AI software development engineers looking to enhance their applications.","zh":"Favourite Location 功能允许用户收藏和查看天气预报。该功能使用 JavaScript 和 Redux 实现，包括创建粘性导航栏和扩展 Redux 存储","ja":"Favourite Location 機能は、ユーザーが天気予報をお気に入り登録し、表示できるようにします。この機能は JavaScript と Redux を使用して実現され、スタッキー ナビバーの作成や Redux ストアの拡張が含まれます","ko":"Favourite Location 기능을 통해 사용자는 기상 예보를 즐겨찾기 등록하고查看할 수 있습니다. 이 기능은 JavaScript 및 Redux를 사용하여 구현되며, 스티키 네비게이션 바 생성 및 Redux 저장소 확장 등이 포함됩니다","es":"Implementa la función de ubicaciones favoritas con JavaScript y Redux, y persiste los datos en LocalStorage para una experiencia de usuario personalizada","fr":"Mettez en œuvre la fonction d''emplacement favori avec JavaScript et Redux, et persistez les données dans LocalStorage pour une expérience utilisateur personnalisée","de":"Implementieren Sie die Funktion von Favoritenorten mit JavaScript und Redux, und speichern Sie die Daten in LocalStorage für eine personalisierte Benutzererfahrung","pt":"Crie funcionalidades de localização favorita com JavaScript e Redux. Armazene entradas de localização favorita no armazenamento local","ru":"Создайте функциональность favorite location с помощью JavaScript и Redux. Сохраните записи favorite location в локальном хранилище","ar":"أنشئ وظائف الموقع المفضل باستخدام JavaScript و Redux. احفظ إدخالات الموقع المفضل في التخزين المحلي"},"seo":{"title":{"en":"Favourite Location: Setup Guide for AI Agents | AI Agent ...","zh":"Favourite Location 设置指南 - 使用 JavaScript 和 Redux","ja":"Favourite Location の設定方法 - JavaScript と Redux を使用","ko":"Favourite Location 설정 가이드 - JavaScript 및 Redux 사용","es":"Configuración de Ubicación Favorita con Redux y LocalStorage","fr":"Guide de mise en place de l''emplacement favori avec Redux...","de":"Einrichtung von Favoritenorten mit Redux und LocalStorage","pt":"Configuração de Localização Favorita: Guia de Implementação","ru":"Настройка Favorite Location: Руководство по реализации с ...","ar":"إعداد الموقع المفضل: دليل التركيب باستخدام أدوات الذكاء ا..."},"description":{"en":"Discover how to implement Favourite Location with Redux and local storage. Learn to create a sticky navbar and persist favourite entries with this step-by-st...","zh":"学习如何使用 JavaScript 和 Redux 创建 Favourite Location 功能，包括创建粘性导航栏、扩展 Redux 存储和持久化收藏项","ja":"JavaScript と Redux を使用して Favourite Location 機能を作成する方法を学びます。スタッキー ナビバーの作成、Redux ストアの拡張、 お気に入りアイテムの永続化など","ko":"JavaScript 및 Redux를 사용하여 Favourite Location 기능을 생성하는 방법을 배웁니다. 스티키 네비게이션 바 생성, Redux 저장소 확장, 즐겨찾기 항목 유지 등","es":"Aprende a implementar la función de ubicaciones favoritas con JavaScript, Redux y LocalStorage para una experiencia de usuario personalizada","fr":"Découvrez comment mettre en œuvre la fonction d''emplacement favori avec JavaScript, Redux et LocalStorage pour une expérience utilisateur personnalisée","de":"Erfahren Sie, wie Sie die Funktion von Favoritenorten mit JavaScript, Redux und LocalStorage für eine personalisierte Benutzererfahrung implementieren","pt":"Aprenda a criar funcionalidades de localização favorita com JavaScript, Redux e armazenamento local para desenvolvedores web","ru":"Узнайте, как создать функциональность favorite location с помощью JavaScript, Redux и локального хранилища для веб-разработчиков с ИИ Агентами","ar":"تعرف على كيفية إنشاء وظائف الموقع المفضل باستخدام JavaScript و Redux وتخزين المحلي لملحقات الويب مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Favourite Location is a JavaScript-based skill that allows users to save and manage favourite locations using a sticky navbar and local storage.","zh":"Favourite Location 是一个使用 JavaScript 和 Redux 实现的功能，允许用户收藏和查看天气预报","ja":"Favourite Location は、JavaScript と Redux を使用して実現された機能で、ユーザーが天気予報をお気に入り登録し、表示できるようにします","ko":"Favourite Location은 JavaScript 및 Redux를 사용하여 구현된 기능으로, 사용자가 기상 예보를 즐겨찾기 등록하고查看할 수 있습니다","es":"La ubicación favorita es una función que permite a los usuarios guardar y recuperar sus ubicaciones preferidas","fr":"L''emplacement favori est une fonction qui permet aux utilisateurs de sauvegarder et de récupérer leurs emplacements préférés","de":"Der Favoritenort ist eine Funktion, die es Benutzern ermöglicht, ihre bevorzugten Orte zu speichern und wiederzuerlangen","pt":"Localização favorita é uma funcionalidade que permite aos usuários salvar locais preferidos","ru":"Favorite location - это функциональность, которая позволяет пользователям сохранять предпочитаемые места","ar":"الموقع المفضل هو وظيفة تمكن المستخدمين من حفظ المواقع المفضلة لديهم"},"features":{"en":["Creates a sticky navbar with a Favourites button using a Heart icon","Extends Redux store to create actions for interacting with weather forecast buttons/cards","Persists favourite entries in local storage for page reload/refresh","Lists all favourite locations under the SearchBar component on clicking the Favourites button","Utilizes JavaScript and Redux for functionality"],"zh":["创建粘性导航栏","扩展 Redux 存储","持久化收藏项","使用 Heart 图标表示收藏","点击收藏按钮显示收藏列表","使用 local storage 存储收藏项"],"ja":["スタッキー ナビバーの作成","Redux ストアの拡張","お気に入りアイテムの永続化","Heart アイコンを使用してお気に入りを表示","お気に入りボタンをクリックしてお気に入りリストを表示","ローカルストレージを使用してお気に入りアイテムを保存"],"ko":["스티키 네비게이션 바 생성","Redux 저장소 확장","즐겨찾기 항목 유지","하트 아이콘을 사용하여 즐겨찾기 표시","즐겨찾기 버튼을 클릭하여 즐겨찾기 목록 표시","로컬 저장소를 사용하여 즐겨찾기 항목 저장"],"es":["Implementación de una barra de navegación con un botón de favoritos","Uso de Redux para gestionar el estado de las ubicaciones favoritas","Persistencia de datos en LocalStorage para una experiencia de usuario personalizada","Listado de ubicaciones favoritas bajo el componente de búsqueda","Uso de iconos de corazón para representar las ubicaciones favoritas"],"fr":["Mise en place d''une barre de navigation avec un bouton de favoris","Utilisation de Redux pour gérer l''état des emplacements favoris","Persistance des données dans LocalStorage pour une expérience utilisateur personnalisée","Liste des emplacements favoris sous le composant de recherche","Utilisation d''icônes de cœur pour représenter les emplacements favoris"],"de":["Implementierung einer Navigationsleiste mit einem Favoritenbutton","Verwendung von Redux zur Verwaltung des Zustands der Favoritenorte","Persistenz der Daten in LocalStorage für eine personalisierte Benutzererfahrung","Auflistung der Favoritenorte unter dem Suchkomponent","Verwendung von Herz-Ikonen zur Darstellung der Favoritenorte"],"pt":["Criação de barra de navegação fixa com botão de favoritos","Extensão do armazenamento de estado do Redux para ações de botões de previsão do tempo","Armazenamento de entradas de localização favorita no armazenamento local","Listagem de locais favoritos sob o componente de barra de pesquisa","Uso de ícone de coração para o botão de favoritos"],"ru":["Создание фиксированной навигационной панели с кнопкой favorite location","Расширение хранилища состояния Redux для действий кнопок прогноза погоды","Сохранение записей favorite location в локальном хранилище","Отображение списка favorite location под компонентом строки поиска","Использование иконки сердца для кнопки favorite location"],"ar":["إنشاء شريط导航 مثبت مع زر الموقع المفضل","تمديد مخزن الحالة من Redux إلى إجراءات أزرار توقعات الطقس","حفظ إدخالات الموقع المفضل في التخزين المحلي","عرض قائمة المواقع المفضلة تحت مكون شريط البحث","استخدام أيقونة القلب لزر الموقع المفضل"]},"keywords":{"en":["how to use Favourite Location","Favourite Location setup guide","Favourite Location alternative","Favourite Location vs Redux","what is Favourite Location","Favourite Location install","JavaScript favourite location management","Redux local storage implementation","AI agent favourite location skill"],"zh":["Favourite Location","JavaScript","Redux","粘性导航栏","天气预报","收藏功能","local storage","AIエージェント","前端开发"],"ja":["Favourite Location","JavaScript","Redux","スタッキー ナビバー","天気予報","お気に入り機能","ローカルストレージ","AIエージェント","フロントエンド開発"],"ko":["Favourite Location","JavaScript","Redux","스티키 네비게이션 바","기상 예보","즐겨찾기 기능","로컬 저장소","AI 에이전트","프론트엔드 개발"],"es":["ubicación favorita","Redux","LocalStorage","JavaScript","desarrollo de software","experiencia de usuario personalizada","navegación","favoritos","Herramientas de AI"],"fr":["emplacement favori","Redux","LocalStorage","JavaScript","développement de logiciels","expérience utilisateur personnalisée","navigation","favoris","Outils d''IA"],"de":["Favoritenort","Redux","LocalStorage","JavaScript","Softwareentwicklung","personalisierte Benutzererfahrung","Navigation","Favoriten","KI-Tools"],"pt":["localização favorita","javascript","redux","armazenamento local","barra de navegação fixa","botão de favoritos","previsão do tempo","desenvolvimento web"],"ru":["favorite location","javascript","redux","локальное хранилище","фиксированная навигационная панель","кнопка favorite location","прогноз погоды","веб-разработка","ИИ Агенты"],"ar":["الموقع المفضل","javascript","redux","التخزين المحلي","شريط导航 مثبت","زر الموقع المفضل","توقعات الطقس","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"vativa","repo":"WeatherForecast","repoPath":"vativa/WeatherForecast","stars":0,"forks":0,"updatedAt":"2026-01-29T14:40:58Z","topics":[],"category":"community","skillMd":{"name":"Favourite Location","description":"Persist favourite locations on page refresh, list under SearchBar, and fetch weather on click.","bodyPreview":"# Task: Create functionality for keeping favaoute locations\n- Create sticky navbar on top of the site having a \"Favourites\" button (preferably using Heart icon, keep right).\n- Extend Redux store to create actions when interacting with weather forecast buttons/cards.\n- Please persist favourite entries in local storage so that they are available on page reload/refresh.\n- Clicking on \"Favourites\" button in the navbar should list all favourite locations under the SearchBar component.\n- Each favourit","body":"# Task: Create functionality for keeping favaoute locations\n- Create sticky navbar on top of the site having a \"Favourites\" button (preferably using Heart icon, keep right).\n- Extend Redux store to create actions when interacting with weather forecast buttons/cards.\n- Please persist favourite entries in local storage so that they are available on page reload/refresh.\n- Clicking on \"Favourites\" button in the navbar should list all favourite locations under the SearchBar component.\n- Each favourite entry listed should be clickable, on click triggers \"Get Location\" button logic, and fetching/rendering weather results for that location.\n\n# Task: Autorefresh with predefined interval 15, 30, 60 minutes\n- Please add predefined interval list with mentioned count of minutes.\n- Custom interval should be supported to add to the bottom of predifined intervals.\n- Add intervals to the Redux store in their own slice/object.\n- Always use current location from the Redux store to fetch weather data.\n- Add autorefresh logic to fetch weather data for the current location based on selected interval.\n- Each custom interval entry has a \"X\" delete button to remove it from the list.\n- Activating a timer without current location will result in empty expectations by the user.\n- Please notify the user about missing curent location with warning.\n- Do not activate auto refresh interval without current location.\n- Do not disable interval buttonss on missing current location, just warn the user on click.\n\n# Code Standards\n- Keep files under 100 lines where possible.\n- DRY - Don''t Repeat Yourself.\n"},"lastSynced":"2026-03-07T03:48:56.720Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing location-based functionality with JavaScript and Redux integration.","zh":"非常适合需要基于位置的功能并集成JavaScript和Redux的前端代理。","ja":"JavaScriptとReduxの統合が必要なフロントエンドエージェントに最適です。","ko":"JavaScript와 Redux 통합이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan funcionalidad basada en ubicación con integración de JavaScript y Redux.","fr":"Parfait pour les agents Frontend ayant besoin de fonctionnalités basées sur l''emplacement avec une intégration de JavaScript et Redux.","de":"Perfekt für Frontend-Agents, die eine standortbasierte Funktionalität mit JavaScript- und Redux-Integration benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de funcionalidade baseada em localização com integração JavaScript e Redux.","ru":"Идеально подходит для агентов Frontend, которым требуется функциональность, основанная на местоположении, с интеграцией JavaScript и Redux.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى وظائف تعتمد على الموقع مع دمج JavaScript و Redux."},"recommendation":{"en":"Empowers agents to create interactive favourite location lists using Redux actions and local storage persistence, while utilizing JavaScript for dynamic functionality and a sticky navbar with a Heart icon for intuitive user interaction.","zh":"赋予代理创建交互式的最喜欢的位置列表的能力，使用Redux操作和本地存储的持久性，同时利用JavaScript实现动态功能和带有心形图标的粘性导航条以实现直观的用户交互。","ja":"エージェントがReduxアクションとローカルストレージの永続性を使用してインタラクティブなお気に入りの場所リストを作成し、JavaScriptを使用して動的機能と直感的なユーザーインタラクションのためのスティッキーナビバーを実現することができます。","ko":"에이전트가 Redux 액션과 로컬 스토리지의 지속성을 사용하여 상호작용형 좋아하는 위치 목록을 생성하고, JavaScript를 사용하여 동적 기능과 직관적인 사용자 상호작용을 위한 粘性 네비게이션 바를 구현할 수 있습니다.","es":"Habilita a los agentes a crear listas de ubicaciones favoritas interactivas utilizando acciones de Redux y persistencia de almacenamiento local, mientras utiliza JavaScript para funcionalidad dinámica y una barra de navegación adhesiva con un icono de corazón para una interacción del usuario intuitiva.","fr":"Permet aux agents de créer des listes de lieux favoris interactifs en utilisant des actions Redux et une persistance de stockage local, tout en utilisant JavaScript pour une fonctionnalité dynamique et une barre de navigation collante avec un icône de cœur pour une interaction utilisateur intuitive.","de":"Ermöglicht es Agents, interaktive Favoritenlisten für Orte zu erstellen, indem sie Redux-Aktionen und lokale Speicherpersistenz verwenden, während sie JavaScript für dynamische Funktionalität und eine klebende Navigationsleiste mit einem Herzsymbol für eine intuitive Benutzerinteraktion nutzen.","pt":"Habilita os agentes a criarem listas de localizações favoritas interativas usando ações Redux e persistência de armazenamento local, ao mesmo tempo em que utiliza JavaScript para funcionalidade dinâmica e uma barra de navegação fixa com um ícone de Coração para interação do usuário intuitiva.","ru":"Наделяет агентов возможностью создавать интерактивные списки любимых мест с использованием действий Redux и сохранения данных в локальном хранилище, а также использовать JavaScript для динамической функциональности и липкой панели навигации с иконкой Сердца для интуитивного взаимодействия пользователя.","ar":"يمنح العميل القدرة على إنشاء قوائم أماكن مفضلة تفاعلية باستخدام إجراءات Redux وتماسك التخزين المحلي، وفي الوقت نفسه يستخدم JavaScript للوظائف الديناميكية وشريط التنقل الثابت مع رمز القلب للتفاعل المستخدم بسهولة."},"useCases":{"en":["Creating favourite location lists","Persisting user preferences in local storage","Extending Redux stores for location-based actions"],"zh":["创建最喜欢的位置列表","在本地存储中持久化用户首选项","扩展Redux存储以实现基于位置的操作"],"ja":["お気に入りの場所リストの作成","ローカルストレージを使用したユーザー設定の永続化","Reduxストアの拡張による位置ベースのアクションの実現"],"ko":["좋아하는 위치 목록 생성","로컬 스토리지에 사용자首选项을 지속化","Redux 저장소 확장으로 위치 기반 액션 구현"],"es":["Creación de listas de ubicaciones favoritas","Persistencia de preferencias de usuario en almacenamiento local","Extensión de almacenes de Redux para acciones basadas en ubicación"],"fr":["Création de listes de lieux favoris","Persistance des préférences utilisateur dans le stockage local","Extension des magasins Redux pour les actions basées sur l''emplacement"],"de":["Erstellung von Favoritenlisten für Orte","Beibehaltung von Benutzervorlieben im lokalen Speicher","Erweiterung von Redux-Speichern für standortbasierte Aktionen"],"pt":["Criar listas de localizações favoritas","Manter preferências do usuário no armazenamento local","Estender lojas Redux para ações baseadas em localização"],"ru":["Создание списков любимых мест","Сохранение предпочтений пользователя в локальном хранилище","Расширение магазинов Redux для действий, основанных на местоположении"],"ar":["إنشاء قوائم أماكن مفضلة","الحفاظ على تفضيلات المستخدم في التخزين المحلي","توسيع مخازن Redux لأفعال تعتمد على الموقع"]},"limitations":{"en":["Requires JavaScript and Redux setup","Limited to client-side storage using local storage"],"zh":["需要JavaScript和Redux设置","仅限使用本地存储进行客户端存储"],"ja":["JavaScriptとReduxの設定が必要","ローカルストレージを使用したクライアント側ストレージのみ"],"ko":["JavaScript와 Redux 설정이 필요","로컬 스토리지 사용에 의한 클라이언트 측 저장소限定"],"es":["Requiere configuración de JavaScript y Redux","Limitado al almacenamiento en el lado del cliente utilizando almacenamiento local"],"fr":["Nécessite une configuration de JavaScript et Redux","Limité au stockage côté client en utilisant le stockage local"],"de":["Benötigt eine JavaScript- und Redux-Konfiguration","Begrenzt auf Client-seitigen Speicher unter Verwendung von lokalem Speicher"],"pt":["Requer configuração JavaScript e Redux","Limitado ao armazenamento do lado do cliente usando armazenamento local"],"ru":["Требует настройки JavaScript и Redux","Ограничен хранением на стороне клиента с использованием локального хранилища"],"ar":["يتطلب إعداد JavaScript و Redux","محدود بالتخزين الجانبي للعميل باستخدام التخزين المحلي"]},"version":4},"contentHash":"b6e95d3b1239156f6c205a104877ece1c0007a629970c61a0617995625cc70f4","qualityScore":26}');
