INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Wolf-Tungsten/wolvrix-playground/convert-develop', 'convert-develop', 'Wolf-Tungsten', 'wolvrix-playground', 'community', 'convert-develop Wolf-Tungsten wolvrix-playground community The convert-develop skill enables AI agents to extract step numbers, normalize data, and capture target plans. It benefits developers by streamlining development workflows. Convert Develop 是一个用于步骤提取和规范化的工具，通过读取文档和处理依赖关系来实现 Convert Develop はステップ抽出と正規化を実行するツールで、ドキュメントの読み取りと依存関係の処理で機能します Convert Develop는 단계 추출 및 정규화를 수행하는 도구로 문서 읽기 및 종속성 처리를 통해 작동합니다 Convert-develop es una herramienta de desarrollo que permite a los desarrolladores convertir y mejorar su código. Nuestra guía ofrece una visión general técnica de cómo configurar y utilizar esta herramienta Convert-develop est un outil de développement qui permet aux développeurs de convertir et d''améliorer leur code. Notre guide offre une vue d''ensemble technique de la manière de configurer et d''utiliser cet outil Convert-develop ist ein Entwicklungstool, das es Entwicklern ermöglicht, ihren Code zu konvertieren und zu verbessern. Unser Leitfaden bietet eine technische Übersicht darüber, wie Sie dieses Tool konfigurieren und verwenden können O Convert Develop é uma ferramenta que ajuda a extrair números de etapas e normalizar para 4 dígitos, além de abrir arquivos de documentação para capturar alvos e planos. Инструмент Convert Develop помогает извлекать номера шагов и нормализовать их до 4 цифр, а также открывать файлы документации для захвата целей и планов. أداة Convert Develop تساعد في استخراج أرقام الخطوات وتعديلها إلى 4 أرقام، بالإضافة إلى فتح ملفات الوثائق لالتقاط الأهداف والمخططات. how to use convert-develop convert-develop setup guide what is convert-develop convert-develop alternative convert-develop vs competing tools convert-develop install convert-develop technical documentation AI 工具 步骤提取 规范化 文档处理 依存关系 Convert Develop AI 에이전트 技术文档 Extracts step numbers from requests and normalizes to 4 digits Locates matching STEP sections in convert-progress.md Aligns with current design and flow by reading convert-architecture.md and convert-workflow.md Identifies dependencies and prior steps for revision Marks superseded content with strikethroughs convert-develop is a technical skill that automates step extraction, data normalization, and workflow alignment for efficient development processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('qte77/claude-code-utils-plugin/committing-staged-with-message', 'community', 'qte77', 'claude-code-utils-plugin', 'qte77/claude-code-utils-plugin', 'committing-staged-with-message', 0, 0, 26, '2026-03-01T20:02:46Z', '2026-03-07T13:07:24.819Z', '7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7', '{"id":"qte77/claude-code-utils-plugin/committing-staged-with-message","name":"committing-staged-with-message","description":{"en":"The committing-staged-with-message skill automates Git commits with generated messages, benefiting developers who need to track changes efficiently. It analyzes staged changes using Git commands like git diff and git log.","zh":"Committing-Staged-With-Message插件提供了自动化Git提交消息的解决方案，通过分析暂存代码和最近的提交记录来生成提交消息","ja":"AIエージェントを使用したステージ済みコードのコミットメッセージ自動生成プラグイン","ko":"커밋 메시지 자동 생성을 위한 Committing-Staged-With-Message 플러그인은暂存 코드와 최근의 커밋 기록을 분석하여 제출 메시지를 생성","es":"El plugin de Claude Code ''committing-staged-with-message'' proporciona una forma automatizada de generar mensajes de commit para cambios en etapas","fr":"Le plugin Claude Code ''committing-staged-with-message'' offre une façon automatisée de générer des messages de commit pour les modifications en attente","de":"Das Claude Code-Plugin ''committing-staged-with-message'' bietet eine automatisierte Möglichkeit, Commit-Nachrichten für gestufte Änderungen zu generieren","pt":"O plugin Claude Code fornece uma forma eficiente de committar alterações estágias com mensagens geradas automaticamente.","ru":"Плагин Claude Code предоставляет эффективный способ коммита временных изменений с сгенерированными сообщениями.","ar":"مكون إضافي Claude Code يوفر طريقة فعالة لالالتزام بالمراحل مع رسائل مُولدة تلقائيًا."},"seo":{"title":{"en":"committing-staged-with-message: Git Automation Setup Guid...","zh":"提交暂存代码的消息设置指南 - Committing-Staged-With-Message","ja":"AIエージェントを使用したステージ済みコードのコミットメッセージ設定方法","ko":"커밋 메시지 생성을 위한暂存 코드 커밋 가이드 - Committing-Staged-With-Message","es":"Guía de Configuración de Commit con Mensaje Generado","fr":"Paramétrer le Commit avec Message Généré - Meilleures Pra...","de":"Einrichten von Commits mit Generierter Nachricht - Anleitung","pt":"Guia de Configuração do Committar Estágios com Mensagem G...","ru":"Настройка Коммита Временных Изменений с Сгенерированным С...","ar":"دليل إعداد الالتزام بالمراحل مع رسالة مُولدة - أدوات الذك..."},"description":{"en":"Streamline your Git workflow with committing-staged-with-message. Learn how to automate commits with generated messages and improve your development efficien...","zh":"了解如何使用Committing-Staged-With-Message插件自动化Git提交消息，提高开发效率","ja":"AIエージェントを活用してステージ済みコードのコミットメッセージを自動生成し、開発効率を向上させる方法","ko":"커밋 메시지 자동 생성을 위한 Committing-Staged-With-Message 플러그인 사용법 및 개발 효율성 향상","es":"Aprende a configurar commits con mensajes generados en Claude Code, con pasos detallados y ejemplos prácticos para desarrolladores","fr":"Découvrez comment paramétrer les commits avec messages générés dans Claude Code, avec des étapes détaillées et des exemples pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Commits mit generierten Nachrichten in Claude Code einrichten, mit detaillierten Schritten und praktischen Beispielen für Entwickler","pt":"Aprenda a committar alterações estágias com mensagens geradas automaticamente usando o plugin Claude Code","ru":"Узнайте, как коммитить временные изменения с сгенерированными сообщениями, используя плагин Claude Code - ИИ Агенты","ar":"تعرف على كيفية الالتزام بالمراحل مع رسائل مُولدة تلقائيًا باستخدام مكون إضافي Claude Code - أدوات الذكاء الاصطناعي"},"definition":{"en":"committing-staged-with-message is a Claude Code plugin that automates Git commits with generated messages based on staged changes, using commands like git diff --staged and git log --oneline.","zh":"Committing-Staged-With-Message是一种自动化Git提交消息的插件，通过分析暂存代码和最近的提交记录来生成提交消息","ja":"AIエージェントを使用したステージ済みコードのコミットメッセージ自動生成プラグインの定義","ko":"커밋 메시지 자동 생성을 위한 Committing-Staged-With-Message 플러그인의 정의","es":"Un plugin de Claude Code que genera mensajes de commit automáticamente para cambios en etapas, utilizando comandos Git como ''git diff'' y ''git log''","fr":"Un plugin Claude Code qui génère des messages de commit automatiquement pour les modifications en attente, en utilisant des commandes Git telles que ''git diff'' et ''git log''","de":"Ein Claude Code-Plugin, das Commit-Nachrichten automatisch für gestufte Änderungen generiert, indem es Git-Befehle wie ''git diff'' und ''git log'' verwendet","pt":"Committar estágios com mensagem gerada é uma técnica de controle de versão que usa comandos Git para gerar mensagens de commit automaticamente.","ru":"Коммит временных изменений с сгенерированным сообщением - это техника контроля версий, которая использует команды Git для генерации сообщений коммита автоматически - ИИ Агенты","ar":"الالتزام بالمراحل مع رسالة مُولدة هي تقنية لمراقبة الإصدارات التي تستخدم أوامر Git لتوليد رسائل الالتزام تلقائيًا - أدوات الذكاء الاصطناعي"},"features":{"en":["Analyzes staged changes using Git commands like git diff --staged --name-only and git diff --staged --stat","Generates commit messages based on diff stats summary and recent commit style","Reviews detailed staged changes using git diff --staged","Applies a size guard to skip full diff for large changes (>10 files or >500 lines)","Utilizes Bash tool for command execution"],"zh":["自动化Git提交消息","分析暂存代码和最近的提交记录","支持Bash工具","生成详细的提交消息","支持Size Guard功能"],"ja":["AIエージェントを使用したステージ済みコードのコミットメッセージ自動生成","ステージ済みコードと最近のコミット履歴の分析","Bashツールのサポート","詳細なコミットメッセージの生成","Size Guard機能のサポート"],"ko":["커밋 메시지 자동 생성","暂存 코드와 최근의 커밋 기록 분석","Bash 툴 지원","詳細한 제출 메시지 생성","Size Guard 기능 지원"],"es":["Generación automática de mensajes de commit","Uso de comandos Git como ''git diff'' y ''git log''","Análisis de cambios en etapas con ''git diff --staged --name-only'' y ''git diff --staged --stat''","Revisión de cambios detallados con ''git diff --staged''","Limitación de tamaño para evitar mensajes de commit largos"],"fr":["Génération automatique de messages de commit","Utilisation de commandes Git comme ''git diff'' et ''git log''","Analyse de modifications en attente avec ''git diff --staged --name-only'' et ''git diff --stated --stat''","Révision de modifications détaillées avec ''git diff --staged''","Limitation de taille pour éviter les messages de commit longs"],"de":["Automatische Generierung von Commit-Nachrichten","Verwendung von Git-Befehlen wie ''git diff'' und ''git log''","Analyse von gestuften Änderungen mit ''git diff --staged --name-only'' und ''git diff --staged --stat''","Überprüfung von detaillierten Änderungen mit ''git diff --staged''","Größenbegrenzung, um lange Commit-Nachrichten zu vermeiden"],"pt":["Análise de alterações estágias usando `git diff --staged --name-only`","Geração de mensagens de commit automaticamente com base em estatísticas de diff","Suporte a limites de tamanho para evitar diffs grandes","Integração com o fluxo de trabalho de desenvolvimento de produção","Uso de `git log --oneline -5` para revisar commits recentes","Compatibilidade com o Bash tool"],"ru":["Анализ временных изменений с помощью `git diff --staged --name-only`","Генерация сообщений коммита автоматически на основе статистики диффа","Поддержка ограничений размера для避ания крупных диффов","Интеграция с производственным рабочим процессом разработки","Использование `git log --oneline -5` для просмотра недавних коммитов","Совместимость с инструментом Bash"],"ar":["تحليل التغييرات المرحلية باستخدام `git diff --staged --name-only`","توليد رسائل الالتزام تلقائيًا بناءً على إحصائيات DIFF","دعم حدود الحجم لتجنب DIFF الكبيرة","_integration مع تدفق العمل الإنتاجي","استخدام `git log --oneline -5` لمراجعة الالتزامات الأخيرة","التوافق مع أداة Bash"]},"keywords":{"en":["how to use committing-staged-with-message","what is committing-staged-with-message","committing-staged-with-message alternative","committing-staged-with-message vs git commit","committing-staged-with-message install","committing-staged-with-message setup guide","git automation with committing-staged-with-message","automating git commits with generated messages"],"zh":["Git提交消息","自动化提交","AI工具","Committing-Staged-With-Message","Bash工具","Size Guard"],"ja":["AIエージェント","ステージ済みコード","コミットメッセージ自動生成","Git","Bashツール","Size Guard"],"ko":["AI 에이전트","커밋 메시지 자동 생성","Git","Bash 툴","Size Guard","Committing-Staged-With-Message"],"es":["committing-staged-with-message","plugin de Claude Code","generación automática de mensajes de commit","comandos Git","análisis de cambios en etapas","desarrollo de software","herramientas de desarrollo","AI Agentes","automatización de commits"],"fr":["committing-staged-with-message","plugin Claude Code","génération automatique de messages de commit","commandes Git","analyse de modifications en attente","développement de logiciels","outils de développement","Agents IA","automatisation de commits"],"de":["committing-staged-with-message","Claude Code-Plugin","automatische Generierung von Commit-Nachrichten","Git-Befehle","Analyse von gestuften Änderungen","Software-Entwicklung","Entwicklertools","KI-Agents","Automatisierung von Commits"],"pt":["committar estágios","mensagem gerada","plugin Claude Code","controle de versão","Git","Bash tool","desenvolvimento de software","fluxo de trabalho de produção"],"ru":["коммит временных изменений","сгенерированное сообщение","плагин Claude Code","контроль версий","Git","инструмент Bash","разработка программного обеспечения","производственный рабочий процесс","ИИ Агенты"],"ar":["الالتزام بالمراحل","رسالة مُولدة","مكون إضافي Claude Code","مراقبة الإصدارات","Git","أداة Bash","تطوير البرمجيات","تدفق العمل الإنتاجي","أدوات الذكاء الاصطناعي"]}},"owner":"qte77","repo":"claude-code-utils-plugin","repoPath":"qte77/claude-code-utils-plugin","stars":0,"forks":0,"updatedAt":"2026-03-01T20:02:46Z","topics":[],"category":"community","skillMd":{"name":"committing-staged-with-message","description":"Generate commit message for staged changes, pause for approval, then commit. Stage files first with `git add`, then run this skill.","bodyPreview":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2:","body":"# Commit staged with Generated Message\n\n## Step 1: Analyze Staged Changes\n\nRun these commands using the Bash tool to gather context:\n\n- `git diff --staged --name-only` - List staged files\n- `git diff --staged --stat` - Diff stats summary\n- `git log --oneline -5` - Recent commit style\n- `git diff --staged` - Review detailed staged changes. **Size guard**: if `--stat` shows >10 files or >500 lines changed, skip the full diff and rely on `--stat` + `--name-only` to generate the message.\n\n## Step 2: Generate Commit Message\n\nUse the Read tool to check `.gitmessage` for commit message format and syntax.\n\n**The commit message body MUST include (concisely — no padding, no redundancy):**\n\n1. **What changed**: bullet points per file or logical group\n2. **Symbols added/removed** (when applicable): functions, classes, tests\n3. **Diff stats**: lines added/removed (from `--stat` summary line) — MUST be the last line of the body\n   - Format: `+ symbol_name`, `- symbol_name`\n   - Omit for config/docs/formatting-only changes\n\nKeep the message laser-focused. Do not repeat the subject line in the body.\n\n## Step 3: Pause for Approval\n\n**Please review the commit message.**\n\n- **Approve**: \"yes\", \"y\", \"commit\", \"go ahead\"\n- **Edit**: Provide your preferred message\n- **Cancel**: \"no\", \"cancel\", \"stop\"\n\n## Step 4: Commit\n\nOnce approved:\n\n- `git commit --gpg-sign -m \"[message]\"` - Commit staged changes with approved message (GPG signature mandatory)\n- `git status` - Verify success\n"},"lastSynced":"2026-03-07T13:07:24.819Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated Git commit management with generated messages.","zh":"非常适合需要自动化 Git 提交管理和生成消息的开发代理。","ja":"開発エージェントが自動化された Git コミット管理と生成されたメッセージを必要とする場合に最適です。","ko":"자동화된 Git 커밋 관리 및 생성된 메시지가 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de confirmaciones de Git automatizada con mensajes generados.","fr":"Parfait pour les agents de développement qui ont besoin d''une gestion de commit Git automatisée avec des messages générés.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Git-Commit-Verwaltung mit generierten Nachrichten benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de commit do Git automatizado com mensagens geradas.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированное управление коммитами Git с сгенерированными сообщениями.","ar":"مناسب تماما لموكلات التطوير التي تحتاج إلى إدارة التزامات Git آلي مع رسائل متгенرة."},"recommendation":{"en":"Empowers agents to automate Git commits using bash commands like git diff and git log, streamlining development workflows with efficient change tracking and generated commit messages.","zh":"赋予代理自动化 Git 提交的能力，使用诸如 git diff 和 git log 的 bash 命令，通过高效的更改跟踪和生成的提交消息来简化开发工作流程。","ja":"エージェントに Git コミットを自動化する機能を提供し、git diff や git log などの bash コマンドを使用して、効率的な変更の追跡と生成されたコミットメッセージで開発ワークフローを最適化します。","ko":"에이전트에 자동화된 Git 커밋 기능을 제공하여 bash 명령어인 git diff 및 git log를 사용하여 효율적인 변경 추적 및 생성된 커밋 메시지를 통해 개발 워크플ロー 최적화에 도움을 줍니다.","es":"Permite a los agentes automatizar los commits de Git utilizando comandos bash como git diff y git log, simplificando los flujos de trabajo de desarrollo con un seguimiento de cambios eficiente y mensajes de commit generados.","fr":"Permet aux agents d''automatiser les commits Git en utilisant des commandes bash comme git diff et git log, rationalisant les flux de travail de développement avec un suivi de modifications efficace et des messages de commit générés.","de":"Ermöglicht es den Mitteln, Git-Commits mithilfe von Bash-Befehlen wie git diff und git log zu automatisieren, wodurch die Entwicklungsaufgaben durch effizientes Änderungsmanagement und generierte Commit-Nachrichten rationalisiert werden.","pt":"Permite que os agentes automatizem os commits do Git usando comandos bash como git diff e git log, racionalizando os fluxos de trabalho de desenvolvimento com acompanhamento eficiente de alterações e mensagens de commit geradas.","ru":"Позволяет агентам автоматизировать коммиты Git с помощью команд bash, таких как git diff и git log, оптимизируя рабочие процессы разработки с эффективным отслеживанием изменений и сгенерированными сообщениями о коммитах.","ar":"تمكّن الموكلات من تطبيق التزامات Git آليا باستخدام أوامر bash مثل git diff و git log، وتبسيط سير عمل التطوير مع تتبع فعال للتغييرات ورسائل الالتزام المتولدة."},"useCases":{"en":["Automating Git commits with detailed change summaries","Generating commit messages based on staged file changes","Debugging commit history using git log and diff statistics"],"zh":["自动化 Git 提交并提供详细的更改摘要","根据暂存文件更改生成提交消息","使用 git log 和 diff 统计调试提交历史"],"ja":["Git コミットを自動化し、詳細な変更の要約を提供する","ステージングされたファイルの変更に基づいてコミットメッセージを生成する","git log と diff 統計を使用してコミット履歴をデバッグする"],"ko":["Git 커밋 자동화 및详细 변경 요약 제공","暂存된 파일 변경 사항을 기준으로 커밋 메시지 생성","git log 및 diff 통계를 사용한 커밋 기록 디버깅"],"es":["Automatizar commits de Git con resúmenes de cambios detallados","Generar mensajes de commit en función de los cambios de archivos en espera","Depurar el historial de commits utilizando estadísticas de git log y diff"],"fr":["Automatiser les commits Git avec des résumés de modifications détaillés","Générer des messages de commit en fonction des modifications de fichiers en attente","Déboguer l''historique des commits en utilisant des statistiques de git log et diff"],"de":["Automatisieren von Git-Commits mit detaillierten Änderungszusammenfassungen","Generieren von Commit-Nachrichten basierend auf geänderten Dateien in der Warteschlange","Fehlerbehebung der Commit-Historie mithilfe von git log- und diff-Statistiken"],"pt":["Automatizar commits do Git com resumos detalhados de alterações","Gerar mensagens de commit com base em alterações de arquivos em estágio","Depurar histórico de commits usando estatísticas git log e diff"],"ru":["Автоматизировать коммиты Git с подробными сводками изменений","Генерировать сообщения о коммитах на основе изменений в файлах в стадии","Отлаживать историю коммитов с помощью статистики git log и diff"],"ar":["تطبيق التزامات Git آليا مع ملخصات تفصيلية للتغييرات","توليد رسائل الالتزام بناءً على تغييرات الملفات في مرحلة الإعداد","تصحيح أخطاء سجل الالتزام باستخدام إحصائيات git log و diff"]},"limitations":{"en":["Requires Git installation and configuration","Limited to 10 files or 500 lines of changes for detailed diff review","Bash tool dependency for command execution"],"zh":["需要 Git 安装和配置","仅限 10 个文件或 500 行的更改进行详细 diff 审查","bash 工具依赖于命令执行"],"ja":["Git のインストールと構成が必要","詳細な diff レビューは 10 個のファイルまたは 500 行の変更に限定","bash ツールの依存関係によるコマンド実行"],"ko":["Git 설치 및 구성 필요","詳細한 diff 리뷰는 10개 파일 또는 500줄의 변경 사항으로 제한","bash 도구 종속성에 따른 명령어 실행"],"es":["Requiere la instalación y configuración de Git","Limitado a 10 archivos o 500 líneas de cambios para la revisión detallada de diff","Dependencia de la herramienta Bash para la ejecución de comandos"],"fr":["Nécessite l''installation et la configuration de Git","Limité à 10 fichiers ou 500 lignes de modifications pour l''examen détaillé de diff","Dépendance de l''outil Bash pour l''exécution de commandes"],"de":["Erfordert die Installation und Konfiguration von Git","Begrenzt auf 10 Dateien oder 500 Zeilen von Änderungen für die detaillierte Überprüfung von diff","Abhängigkeit von der Bash-Tool für die Befehlsausführung"],"pt":["Exige instalação e configuração do Git","Limitado a 10 arquivos ou 500 linhas de alterações para revisão detalhada do diff","Dependência da ferramenta bash para execução de comandos"],"ru":["Требует установки и настройки Git","Ограничен до 10 файлов или 500 строк изменений для подробного обзора diff","Зависимость от инструмента bash для выполнения команд"],"ar":["يتطلب تثبيت إعدادات Git","محدود ب 10 ملفات أو 500 سطر من التغييرات لاستعراض تفصيلي للفرق","اعتماد أداة bash لتنفيذ الأوامر"]},"version":4},"contentHash":"7bd4fb38382a790c45118be86c8c2cfe8575f24724a5d252f142c9c6652083f7","qualityScore":26}');
