INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kenLovesToCode/mobile-lilstore/bmad-agent-cis-storyteller', 'bmad-agent-cis-storyteller', 'kenLovesToCode', 'mobile-lilstore', 'community', 'bmad-agent-cis-storyteller kenLovesToCode mobile-lilstore community The bmad-agent-cis-storyteller skill enables developers to embody the agent''s persona and follow activation instructions exactly as specified, ensuring precise execution and optimal results. bmad-agent-cis-storyteller是一个需要精确激活和执行的AIエージェント，了解其技术细节和激活步骤对于开发至关重要 bmad-agent-cis-storytellerは正確なアクティベーションと実行が必要なAIエージェントです。その技術的詳細とアクティベーション手順を理解することは開発者にとって非常に重要です bmad-agent-cis-storyteller는 정확한 활성화와 실행이 필요한 AI 에이전트입니다. 그 기술적 세부 사항과 활성화 단계를 이해하는 것은 개발자에게 매우 중요합니다 El agente bmad-agent-cis-storyteller es una herramienta de inteligencia artificial que requiere una configuración precisa. Sigue nuestras instrucciones para cargar y ejecutar el agente correctamente. L''agent bmad-agent-cis-storyteller est un outil d''intelligence artificielle qui nécessite une configuration précise. Suivez nos instructions pour charger et exécuter l''agent correctement. Der Agent bmad-agent-cis-storyteller ist ein KI-Tool, das eine genaue Konfiguration erfordert. Befolgen Sie unsere Anweisungen, um den Agenten richtig zu laden und auszuführen. O bmad-agent-cis-storyteller é um agente de inteligência artificial que requer configuração e ativação precisas. ИИ Агент bmad-agent-cis-storyteller требует точной настройки и активации. وحدة bmad-agent-cis-storyteller هي وحدة ذكاء اصطناعي تتطلب إعداد و تشغيل دقيق how to use bmad-agent-cis-storyteller bmad-agent-cis-storyteller activation guide bmad-agent-cis-storyteller setup instructions what is bmad-agent-cis-storyteller bmad-agent-cis-storyteller vs other AI agents bmad-agent-cis-storyteller install and configuration bmad-agent-cis-storyteller AIエージェント开发 AI工具 激活步骤 agent文件 菜单系统 开发最佳实践 Loads the full agent file from {project-root}/_bmad/cis/agents/storyteller/storyteller.md Executes all activation steps exactly as written in the agent file Follows the agent''s persona and menu system with precision Requires strict adherence to critical rules for optimal performance Utilizes the <agent-activation> command with CRITICAL="TRUE" parameter Reads the entire contents of the agent file for complete persona and instructions bmad-agent-cis-storyteller is a highly specialized AI agent skill that requires precise activation and execution to unlock its full capabilities');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gardenvanities/garden-vanities/design-system', 'community', 'gardenvanities', 'garden-vanities', 'gardenvanities/garden-vanities', 'design-system', 0, 0, 26, '2026-02-25T09:03:36Z', '2026-03-07T13:08:27.548Z', '9f5c8de52c93bf55b41ccbee09b4dbac1266310245781fa2ad3d357668441aa4', '{"id":"gardenvanities/garden-vanities/design-system","name":"design-system","description":{"en":"The design-system skill helps developers manage UI, layout, styles, tokens, and interaction states. It benefits developers working on tasks that touch UI components and styles.","zh":"设计系统技能用于优化UI、布局、样式、令牌和交互状态。","ja":"デザインシステムスキルは、UI、レイアウト、スタイル、トークン、インタラクション状態を最適化するために使用されます。","ko":"디자인 시스템 스킬은 UI, 레이아웃, 스타일, 토큰 및 상호 작용 상태를 최적화하는 데 사용됩니다.","es":"El design-system es una habilidad que permite a los agentes de IA gestionar la interfaz de usuario y el diseño de layouts de manera eficiente","fr":"Le design-system est une compétence qui permet aux outils d''IA de gérer l''interface utilisateur et la conception de layouts de manière efficace","de":"Das design-system ist eine Fähigkeit, die es KI-Agents ermöglicht, die Benutzeroberfläche und das Layout-Design effizient zu verwalten","pt":"O design system é uma habilidade que ajuda a melhorar a experiência do usuário e otimizar o desenvolvimento de interfaces","ru":"Design system - это навык, который помогает улучшить пользовательский опыт и оптимизировать разработку интерфейсов","ar":"النظام التصميمي هو مهارة تساعد على تحسين تجربة المستخدم وتحسين تطوير الواجهات"},"seo":{"title":{"en":"Design-System: Setup Guide for AI Agents | AI Agent Skill","zh":"设计系统集成指南 - AIエージェント开发最佳实践","ja":"デザインシステムの構築 - AIエージェントのベストプラクティス","ko":"디자인 시스템 구축 가이드 - AI 에이전트 개발 모범 사례","es":"Guía de configuración de design-system para agentes de IA","fr":"Guide de mise en place de design-system pour les outils d''IA","de":"Einrichtungsleitfaden für design-system in KI-Agents","pt":"Guia de Configuração de Design System para Desenvolvedores","ru":"Настройка ИИ Агентов: Руководство по Design System","ar":"دليل تصميم النظام للبرمجة"},"description":{"en":"Unlock efficient UI development with design-system skill. Discover how to classify task scopes and manage tokens, components, and styles. Get started now!","zh":"了解设计系统的技术细节和工作流程，优化您的AIエージェント开发体验。","ja":"デザインシステムの技術的な詳細とワークフローを学び、AIエージェント開発を最適化する。","ko":"디자인 시스템의 기술적인 세부 정보와 워크플로우를 배우고 AI 에이전트 개발을 최적화하십시오.","es":"Aprende a implementar design-system en tus proyectos de IA con nuestra guía paso a paso","fr":"Découvrez comment mettre en place design-system dans vos projets d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie design-system in Ihren KI-Projekten implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o design system para melhorar a experiência do usuário e otimizar o desenvolvimento de interfaces","ru":"Узнайте, как настроить design system для улучшения пользовательского опыта и оптимизации разработки интерфейсов с помощью ИИ Агентов","ar":"تعرف على كيفية تصميم النظام لتحسين تجربة المستخدم وتحسين تطوير الواجهات"},"definition":{"en":"Design-system is a skill that provides a primary source of truth for UI development, using .agents/design-system.md as the canonical source.","zh":"设计系统是一种用于管理UI组件和样式的方法，确保一致性和可重用性。","ja":"デザインシステムは、UIコンポーネントとスタイルを管理するための方法で、一貫性と再利用性を確保する。","ko":"디자인 시스템은 UI 컴포넌트와 스타일을 관리하기 위한 방법으로 일관성과 재사용성을 보장합니다.","es":"Un design-system es un conjunto de reglas y estilos para la creación de interfaces de usuario coherentes","fr":"Un design-system est un ensemble de règles et de styles pour la création d''interfaces utilisateur cohérentes","de":"Ein design-system ist eine Sammlung von Regeln und Stilen für die Erstellung kohärenter Benutzeroberflächen","pt":"O que é design system? É um conjunto de regras e diretrizes para criar interfaces consistentes e coesas","ru":"Что такое design system? Это набор правил и руководств для создания согласованных и последовательных интерфейсов","ar":"ما هو النظام التصميمي? هو مجموعة من القواعد والإرشادات لإنشاء واجهات متسقة وملائمة"},"features":{"en":["Classifies task scopes into token-level and component-level","Manages tokens and styles using src/styles/tokens/ and src/styles/utilities.css","Follows .agents/design-system.md as the primary source of truth","Handles implementation layers for UI components and interaction states","Utilizes .agents/context.md for project context"],"zh":["基于令牌的样式管理","组件级别的UI行为控制","交互状态的统一管理","canonical源的优先级排序","项目上下文的集成"],"ja":["トークンベースのスタイル管理","コンポーネントレベルのUI動作制御","インタラクション状態の統一管理","カノニカルソースの優先順位付け","プロジェクトコンテキストの統合"],"ko":["토큰 기반 스타일 관리","컴포넌트 수준의 UI 동작 제어","상호 작용 상태의 통일 관리","정식 출처의 우선 순위 설정","프로젝트 컨텍스트의 통합"],"es":["Gestión de tokens de diseño","Creación de componentes de interfaz de usuario","Definición de estilos y layouts","Implementación de estados de interacción","Integración con src/styles/tokens y src/styles/utilities.css"],"fr":["Gestion des jetons de conception","Création de composants d''interface utilisateur","Définition de styles et de layouts","Mise en œuvre d''états d''interaction","Intégration avec src/styles/tokens et src/styles/utilities.css"],"de":["Verwaltung von Design-Tokens","Erstellung von Benutzeroberflächen-Komponenten","Definition von Stilen und Layouts","Implementierung von Interaktionszuständen","Integration mit src/styles/tokens und src/styles/utilities.css"],"pt":["Classificação de escopo de tarefas em nível de token ou componente","Utilização de fontes canônicas para garantir a consistência","Implementação de estilos e layouts personalizados","Definição de estados de interação e comportamentos de UI","Integração com tecnologias como React e CSS"],"ru":["Классификация задач по уровню токена или компонента","Использование канонических источников для обеспечения согласованности","Реализация индивидуальных стилей и макетов","Определение состояний взаимодействия и поведения UI","Интеграция с технологиями như React и CSS"],"ar":["تصنيف نطاق المهام على مستوى الرمز أو المكون","استخدام المصادر القانونية لضمان الاتساق","تنفيذ الأنماط والتخطيطات المخصصة","تحديد حالات التفاعل وسلوكيات الواجهة","التكامل مع التكنولوجيا مثل React و CSS"]},"keywords":{"en":["how to use design-system","design-system setup guide","what is design-system","design-system alternative","design-system vs material ui","design-system install","design-system for ai agents","ui design system","token-level design system","component-level design system"],"zh":["设计系统","AIエージェント","UI组件","样式管理","令牌管理","交互状态","canonical源","项目上下文"],"ja":["デザインシステム","AIエージェント","UIコンポーネント","スタイル管理","トークン管理","インタラクション状態","カノニカルソース","プロジェクトコンテキスト"],"ko":["디자인 시스템","AI 에이전트","UI 컴포넌트","스타일 관리","토큰 관리","상호 작용 상태","정식 출처","프로젝트 컨텍스트"],"es":["design-system para agentes de IA","implementación de design-system","guias de diseño de interfaz de usuario","tokens de diseño","estilos y layouts","interacción de usuario","src/styles/tokens","src/styles/utilities.css"],"fr":["design-system pour les outils d''IA","mise en place de design-system","guides de conception d''interface utilisateur","jetons de conception","styles et layouts","interaction utilisateur","src/styles/tokens","src/styles/utilities.css"],"de":["design-system für KI-Agents","Einrichtung von design-system","Leitfäden für die Gestaltung von Benutzeroberflächen","Design-Tokens","Stile und Layouts","Benutzerinteraktion","src/styles/tokens","src/styles/utilities.css"],"pt":["design system","desenvolvimento de interfaces","experiência do usuário","React","CSS","tokens","componentes","estilos","layouts"],"ru":["design system","ИИ Агенты","разработка интерфейсов","пользовательский опыт","React","CSS","токены","компоненты","стили","макеты"],"ar":["النظام التصميمي","أدوات الذكاء الاصطناعي","تطوير الواجهات","تجربة المستخدم","React","CSS"," الرموز","المكونات","الأنماط","التخطيطات"]}},"owner":"gardenvanities","repo":"garden-vanities","repoPath":"gardenvanities/garden-vanities","stars":0,"forks":0,"updatedAt":"2026-02-25T09:03:36Z","topics":[],"category":"community","skillMd":{"name":"design-system","description":"Operational guide for applying the Garden Vanities design system in implementation tasks","bodyPreview":"# Design System Skill\n\nUse this skill whenever a task touches UI, layout, styles, tokens, or interaction states.\n\n## Canonical Sources\n\n1. Primary source of truth: `.agents/design-system.md`\n2. Project context: `.agents/context.md`\n3. Implementation layer: `src/styles/tokens/` and `src/styles/utilities.css`\n\nIf any source conflicts, follow `.agents/design-system.md`.\n\n## Required Workflow\n\n### 1) Classify the task scope\n\n- `token-level` (new/changed tokens)\n- `component-level` (UI component beha","body":"# Design System Skill\n\nUse this skill whenever a task touches UI, layout, styles, tokens, or interaction states.\n\n## Canonical Sources\n\n1. Primary source of truth: `.agents/design-system.md`\n2. Project context: `.agents/context.md`\n3. Implementation layer: `src/styles/tokens/` and `src/styles/utilities.css`\n\nIf any source conflicts, follow `.agents/design-system.md`.\n\n## Required Workflow\n\n### 1) Classify the task scope\n\n- `token-level` (new/changed tokens)\n- `component-level` (UI component behavior/appearance)\n- `layout-level` (grid, spacing, rhythm)\n- `interaction-level` (states, focus, motion)\n\n### 2) Apply system constraints\n\n- Use semantic tokens, not raw values.\n- Prefer semantic layout wrappers/props (`Section[density]`, `Container[gutter]`, `Grid[gap]`) for structural rhythm.\n- Preserve light matrix with dark parity.\n- Keep Layered Dark Editorial (LDE) coherence: subtle layered surfaces, restrained accent, modular composition.\n- Respect max depth levels (`0..3` only).\n- Keep motion within allowed durations/easing.\n- Keep spacing/radius/shadow within system scales.\n\n### 3) Validate mandatory interaction rules\n\nFor every interactive element, ensure:\n\n1. default\n2. hover (desktop)\n3. focus-visible\n4. active\n5. disabled (if applicable)\n\n### 4) Block forbidden patterns\n\n- Hardcoded colors in components.\n- Arbitrary spacing/radius values unless tokenized (`var(...)`) or tokenized structural `calc(...)`.\n- Decorative animation.\n- New visual variants without semantic reason.\n- Truncation of critical/reading content.\n- Any UI exception outside system rules.\n- Visual drift from LDE baseline (neon accents, heavy blur/glow, decorative gradients in reading surfaces).\n\n### 5) Report decisions in output\n\nWhen finishing, include:\n\n- Section `Applied rules` with the exact system constraints used.\n- Section `Residual debt` with any mismatch that could not be resolved in this task.\n\nFor UI-related tasks, these two sections are mandatory.\n\n### 6) Run spacing policy check (when touching layout/tokens)\n\n- Run `bun run check:spacing` after spacing/layout/token changes.\n- Treat only new violations as blockers (baseline entries are migration debt).\n\n## Token Change Policy\n\nOnly add a new token when:\n\n- there is a real semantic gap\n- no equivalent token exists\n- reuse is expected in multiple contexts\n- it works in both light and dark\n- usage is documented\n\nIf those conditions are not met, reuse existing tokens.\n"},"lastSynced":"2026-03-07T13:08:27.548Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring streamlined UI component management and style consistency.","zh":"适合需要简化UI组件管理和样式一致性的前端代理","ja":"フロントエンドエージェントがストリームライン化されたUIコンポーネント管理とスタイルの一貫性を必要とする場合に適しています","ko":"스트림 라인化 된 UI 컴포넌트 관리 및 스타일 일관성이 필요한 프론트 엔드 에이전트에 적합합니다","es":"Ideal para agentes de Frontend que requieren una gestión de componentes de interfaz de usuario optimizada y consistencia de estilo.","fr":"Idéal pour les agents Frontend nécessitant une gestion de composants d''interface utilisateur rationalisée et une cohérence de style.","de":"Ideal für Frontend-Agents, die eine optimierte UI-Komponentenverwaltung und Stil-Konsistenz erfordern.","pt":"Ideal para Agentes Frontend que requerem gerenciamento de componentes de interface de usuário simplificado e consistência de estilo.","ru":"Идеально подходит для агентов Frontend, требующих упрощенного управления компонентами пользовательского интерфейса и согласованности стилей.","ar":"مثالية للوكلاء الأمامية الذين يتطلبون إدارة مركبات واجهة المستخدم المُبسطة والاتساق في الأسلوب."},"recommendation":{"en":"Empowers agents to manage UI, layout, styles, tokens, and interaction states efficiently, utilizing canonical sources like `.agents/design-system.md` and implementation layers such as `src/styles/tokens/` and `src/styles/utilities.css` to ensure design system integrity.","zh":"赋予代理管理UI、布局、样式、令牌和交互状态的能力，利用像`.agents/design-system.md`这样的规范源和像`src/styles/tokens/`和`src/styles/utilities.css`这样的实现层，以确保设计系统的完整性","ja":"エージェントがUI、レイアウト、スタイル、トークン、インタラクション状態を効率的に管理できるようにし、`.agents/design-system.md`のような正典的なソースや`src/styles/tokens/`および`src/styles/utilities.css`のような実装レイヤーを使用して、デザインシステムの完全性を確保する","ko":"에이전트가 UI, 레이아웃, 스타일, 토큰 및 상호 작용 상태를 효율적으로 관리 할 수 있도록 하여 `.agents/design-system.md`와 같은 표준 소스 및 `src/styles/tokens/` 및 `src/styles/utilities.css`와 같은 구현 레이어를 사용하여 디자인 시스템의 무결성을 보장합니다","es":"Permite a los agentes gestionar la UI, el diseño, los estilos, los tokens y los estados de interacción de manera eficiente, utilizando fuentes canónicas como `.agents/design-system.md` y capas de implementación como `src/styles/tokens/` y `src/styles/utilities.css` para garantizar la integridad del sistema de diseño.","fr":"Permet aux agents de gérer l''interface utilisateur, la disposition, les styles, les jetons et les états d''interaction de manière efficace, en utilisant des sources canoniques comme `.agents/design-system.md` et des couches d''implémentation telles que `src/styles/tokens/` et `src/styles/utilities.css` pour assurer l''intégrité du système de conception.","de":"Ermöglicht es Agenten, UI, Layout, Styles, Token und Interaktionszustände effizient zu verwalten, indem es kanonische Quellen wie `.agents/design-system.md` und Implementierungsebenen wie `src/styles/tokens/` und `src/styles/utilities.css` nutzt, um die Integrität des Design-Systems sicherzustellen.","pt":"Habilita os agentes a gerenciar UI, layout, estilos, tokens e estados de interação de forma eficiente, utilizando fontes canônicas como `.agents/design-system.md` e camadas de implementação como `src/styles/tokens/` e `src/styles/utilities.css` para garantir a integridade do sistema de design.","ru":"Наделяет агентов возможностью эффективно управлять UI, макетом, стилями, токенами и состояниями взаимодействия, используя канонические источники, такие как `.agents/design-system.md` и слои реализации, такие как `src/styles/tokens/` и `src/styles/utilities.css`, для обеспечения целостности системы дизайна.","ar":"تمكين الوكلاء من إدارة واجهة المستخدم والتخطيط والأسلوب والعلامات والتفاعلات بفعالية، باستخدام المصادر القانونية مثل `.agents/design-system.md` وطبقات التنفيذ مثل `src/styles/tokens/` و `src/styles/utilities.css` لضمان سلامة نظام التصميم."},"useCases":{"en":["Classifying task scopes into token-level or component-level changes","Maintaining consistency across UI components and styles","Resolving design system conflicts by referencing the primary source of truth"],"zh":["将任务范围分类为令牌级或组件级更改","在UI组件和样式中保持一致性","通过引用主要真相源来解决设计系统冲突"],"ja":["タスクのスコープをトークンレベルまたはコンポーネントレベルの変更に分類する","UIコンポーネントとスタイルでの一貫性を維持する","主な真実源を参照してデザインシステムのコンフリクトを解決する"],"ko":["작업 범위를 토큰 수준 또는 구성 요소 수준 변경으로 분류","UI 구성 요소 및 스타일에서 일관성을 유지","주된 진실 소스를 참조하여 디자인 시스템의 충돌을 해결"],"es":["Clasificar los alcances de las tareas en cambios a nivel de token o de componente","Mantener la consistencia en los componentes y estilos de la interfaz de usuario","Resolver conflictos del sistema de diseño haciendo referencia a la fuente principal de verdad"],"fr":["Classer les portées des tâches en modifications au niveau du jeton ou du composant","Maintenir la cohérence des composants et des styles de l''interface utilisateur","Résoudre les conflits du système de conception en faisant référence à la source principale de vérité"],"de":["Die Aufgabenbereiche in Token- oder Komponentenebene-Änderungen klassifizieren","Die Konsistenz über UI-Komponenten und -Styles hinweg aufrechterhalten","Design-System-Konflikte durch Bezugnahme auf die primäre Wahrheitsquelle lösen"],"pt":["Classificar os escopos de tarefas em alterações de nível de token ou de componente","Manter a consistência em todo o componente de interface de usuário e estilos","Resolver conflitos do sistema de design referenciando a fonte primária de verdade"],"ru":["Классифицировать объемы задач на уровне токенов или компонентов","Поддерживать согласованность во всех компонентах пользовательского интерфейса и стилях","Решать конфликты системы дизайна, ссылаясь на основной источник правды"],"ar":["تصنيف نطاقات المهام إلى تغييرات على مستوى العلامة أو المكون","الحفاظ على الاتساق عبر جميع مكونات واجهة المستخدم والأسلوب","حل النزاعات في نظام التصميم من خلال الإشارة إلى المصدر الأساسي للصحة"]},"limitations":{"en":["Requires access to `.agents/design-system.md` for primary source of truth","Limited to managing UI, layout, styles, tokens, and interaction states"],"zh":["需要访问`.agents/design-system.md`以获取主要真相源","仅限于管理UI、布局、样式、令牌和交互状态"],"ja":["`.agents/design-system.md`へのアクセスが必要であるため、主要な真実源を取得する","UI、レイアウト、スタイル、トークン、インタラクション状態の管理のみに限定される"],"ko":["`.agents/design-system.md`에 접근하여 주요 진실 소스를 얻는 것이 필요","UI, 레이아웃, 스타일, 토큰 및 상호 작용 상태 관리에만 제한"],"es":["Requiere acceso a `.agents/design-system.md` para la fuente principal de verdad","Limitado a la gestión de la UI, el diseño, los estilos, los tokens y los estados de interacción"],"fr":["Nécessite un accès à `.agents/design-system.md` pour la source principale de vérité","Limité à la gestion de l''interface utilisateur, de la disposition, des styles, des jetons et des états d''interaction"],"de":["Erfordert Zugriff auf `.agents/design-system.md` für die primäre Wahrheitsquelle","Begrenzt auf die Verwaltung von UI, Layout, Styles, Token und Interaktionszuständen"],"pt":["Requer acesso a `.agents/design-system.md` para fonte primária de verdade","Limitado a gerenciar UI, layout, estilos, tokens e estados de interação"],"ru":["Требует доступа к `.agents/design-system.md` в качестве основного источника правды","Ограничен управлением UI, макетом, стилями, токенами и состояниями взаимодействия"],"ar":["يتطلب الوصول إلى `.agents/design-system.md` كمصدر أساسي للصحة","محدود بإدارة واجهة المستخدم والتخطيط والأسلوب والعلامات والتفاعلات"]},"version":4},"contentHash":"9f5c8de52c93bf55b41ccbee09b4dbac1266310245781fa2ad3d357668441aa4","qualityScore":26}');
