INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gardenvanities/garden-vanities/design-system', 'design-system', 'gardenvanities', 'garden-vanities', 'community', 'design-system gardenvanities garden-vanities community The design-system skill helps developers manage UI, layout, styles, tokens, and interaction states. It benefits developers working on tasks that touch UI components and styles. 设计系统技能用于优化UI、布局、样式、令牌和交互状态。 デザインシステムスキルは、UI、レイアウト、スタイル、トークン、インタラクション状態を最適化するために使用されます。 디자인 시스템 스킬은 UI, 레이아웃, 스타일, 토큰 및 상호 작용 상태를 최적화하는 데 사용됩니다. El design-system es una habilidad que permite a los agentes de IA gestionar la interfaz de usuario y el diseño de layouts de manera eficiente Le design-system est une compétence qui permet aux outils d''IA de gérer l''interface utilisateur et la conception de layouts de manière efficace Das design-system ist eine Fähigkeit, die es KI-Agents ermöglicht, die Benutzeroberfläche und das Layout-Design effizient zu verwalten O design system é uma habilidade que ajuda a melhorar a experiência do usuário e otimizar o desenvolvimento de interfaces Design system - это навык, который помогает улучшить пользовательский опыт и оптимизировать разработку интерфейсов النظام التصميمي هو مهارة تساعد على تحسين تجربة المستخدم وتحسين تطوير الواجهات how to use design-system design-system setup guide what is design-system design-system alternative design-system vs material ui design-system install design-system for ai agents ui design system token-level design system component-level design system 设计系统 AIエージェント UI组件 样式管理 令牌管理 交互状态 canonical源 项目上下文 Classifies task scopes into token-level and component-level Manages tokens and styles using src/styles/tokens/ and src/styles/utilities.css Follows .agents/design-system.md as the primary source of truth Handles implementation layers for UI components and interaction states Utilizes .agents/context.md for project context Design-system is a skill that provides a primary source of truth for UI development, using .agents/design-system.md as the canonical source.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryharrin/emilyidle/bmad-gds-create-story', 'community', 'ryharrin', 'emilyidle', 'ryharrin/emilyidle', 'bmad-gds-create-story', 0, 0, 26, '2026-02-27T18:52:48Z', '2026-03-07T04:03:43.283Z', 'b37540729037e66584f193605c67ccfc25bd66e5109c51b0b0a792753c90d7e1', '{"id":"ryharrin/emilyidle/bmad-gds-create-story","name":"bmad-gds-create-story","description":{"en":"The bmad-gds-create-story skill automates workflows by loading and executing workflow configurations. It benefits developers by streamlining create-story workflows.","zh":"bmad-gds-create-story 技术集成需要加载和读取特定的工作流配置文件，才能执行创建故事的任务","ja":"bmad-gds-create-story AIエージェントは、特定のワークフロー設定ファイルを読み込んで実行する必要があります","ko":"bmad-gds-create-story 개발자 설정은 특정 워크플로우 구성 파일을 로드하고 읽어야 합니다","es":"bmad-gds-create-story es una habilidad que permite crear historias mediante la carga y ejecución de workflows. Requiere la carga del archivo workflow.xml y la lectura de su contenido","fr":"bmad-gds-create-story est une compétence qui permet de créer des histoires en chargeant et en exécutant des workflows. Elle nécessite le chargement du fichier workflow.xml et la lecture de son contenu","de":"bmad-gds-create-story ist eine Fähigkeit, die das Erstellen von Geschichten durch das Laden und Ausführen von Workflows ermöglicht. Sie erfordert das Laden der Datei workflow.xml und das Lesen ihres Inhalts","pt":"O bmad-gds-create-story é um skill que executa workflows de criação de histórias com base no arquivo workflow.yaml","ru":"ИИ Агент bmad-gds-create-story выполняет рабочие процессы создания историй на основе файла workflow.yaml","ar":"العامل الذكي bmad-gds-create-story ينفذ سير عمل إنشاء القصص بناءً على ملف workflow.yaml"},"seo":{"title":{"en":"bmad-gds-create-story: Workflow Automation Setup Guide | ...","zh":"bmad-gds-create-story 技术集成指南","ja":"bmad-gds-create-story AIエージェント設定ガイド","ko":