INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('khushveer007/Webdev/bmad-agent-cis-storyteller', 'bmad-agent-cis-storyteller', 'khushveer007', 'Webdev', 'community', 'bmad-agent-cis-storyteller khushveer007 Webdev community The bmad-agent-cis-storyteller skill enables developers to embody a specific agent persona and follow precise activation instructions. It benefits developers working with AI agents. bmad-agent-cis-storyteller 是一个需要精确激活和执行的 AI エージェント，通过加载和读取特定文件来实现其功能 bmad-agent-cis-storyteller は、正確な設定と実行が必要な AI エージェントで、特定のファイルを読み込み実行して機能を実現する bmad-agent-cis-storyteller 는 정확한 활성화와 실행이 필요한 AI 에이전트로, 특정 파일을 로드하고 읽어 들여 기능을 구현 El agente de storytelling de bmad-agent-cis es una herramienta de desarrollo que requiere una configuración precisa para funcionar correctamente L''agent de storytelling bmad-agent-cis est un outil de développement qui nécessite une configuration précise pour fonctionner correctement Der bmad-agent-cis-Storyteller ist ein Entwicklungstool, das eine präzise Konfiguration erfordert, um korrekt zu funktionieren O bmad-agent-cis-storyteller é um agente de inteligência artificial que requer configuração precisa para funcionar corretamente. Siga nossas instruções para configurá-lo ИИ Агент bmad-agent-cis-storyteller требует точной настройки для правильной работы. Следуйте нашим инструкциям для его настройки العامل الذكي bmad-agent-cis-storyteller يتطلب إعدادًا دقيقًا للعمل بشكل صحيح. اتبع إرشاداتنا لإعداده how to use bmad-agent-cis-storyteller bmad-agent-cis-storyteller setup guide what is bmad-agent-cis-storyteller bmad-agent-cis-storyteller alternative bmad-agent-cis-storyteller vs other AI agents activating bmad-agent-cis-storyteller bmad-agent-cis-storyteller installation bmad-agent-cis-storyteller persona embodiment bmad-agent-cis-storyteller AI エージェント 激活步骤 技术要求 实现方法 LOAD 文件 READ 文件内容 Loads the full agent file from {project-root}/_bmad/cis/agents/storyteller/storyteller.md Executes all activation steps exactly as written in the agent file Follows the agent''s persona and menu system precisely Requires reading the entire contents of the agent file for complete persona and instructions Demands strict adherence to activation instructions with no character breaks until exit command bmad-agent-cis-storyteller is a specialized AI agent skill that requires strict adherence to activation protocols and persona embodiment');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gordonwatts/exam-helper/github-issue-workflow', 'community', 'gordonwatts', 'exam-helper', 'gordonwatts/exam-helper', 'github-issue-workflow', 0, 0, 26, '2026-03-05T06:37:45Z', '2026-03-07T13:11:09.191Z', 'b0e24f285206ce249f4a1d3faf96b0209fe889a1c116a8bd65c9d046eaaabdba', '{"id":"gordonwatts/exam-helper/github-issue-workflow","name":"github-issue-workflow","description":{"en":"The github-issue-workflow skill enables developers to manage GitHub issues efficiently using the `gh` command. It streamlines the issue development flow, ensuring alignment with repository policies.","zh":"Github Issue Workflow 是一个使用 gh 命令行工具来管理 Github 问题的工作流程","ja":"Github Issue Workflow は、gh コマンドラインツールを使用して Github の問題を管理するワークフローです","ko":"Github Issue Workflow는 gh 명령줄 도구를 사용하여 Github 문제를 관리하는 워크플로입니다","es":"Utiliza `gh` para descubrir y inspeccionar issues, y sigue el flujo de desarrollo de issues requerido por el repositorio","fr":"Utilisez `gh` pour découvrir et inspecter les issues, puis suivez le flux de développement d''issues requis par le référentiel","de":"Verwenden Sie `gh`, um Issues zu entdecken und zu untersuchen, und folgen Sie dem erforderlichen Issue-Entwicklungsfluss des Repositorys","pt":"O fluxo de trabalho de issues do Github é uma ferramenta essencial para equipes de desenvolvimento. Use o comando gh para descobrir e inspecionar issues","ru":"Workflow Github Issue - это важнейший инструмент для команд разработчиков. Используйте команду gh, чтобы обнаружить и осмотреть issues с помощью ИИ Агентов","ar":"Fluxo de Trabalho de Issues do Github هو أداة أساسية لفريق التطوير. استخدم الأمر gh لاكتشاف ومعاينة Issues مع أداة الذكاء الاصطناعي"},"seo":{"title":{"en":"github-issue-workflow: Streamlined Issue Management for A...","zh":"Github Issue Workflow Setup Guide - AIエージェント","ja":"Github Issue Workflow ベストプラクティス - AIエージェント","ko":"Github Issue Workflow 설정 가이드 - AI 도구","es":"Guía de configuración de flujo de trabajo de issues de Gi...","fr":"Guide de mise en place du workflow des issues Github","de":"Einrichtungsleitfaden für Github Issue-Workflow","pt":"Guia de Configuração do Fluxo de Trabalho de Issues do Gi...","ru":"Настройка ИИ Агентов: Руководство по Workflow Github Issue","ar":"دليل إعداد أداة الذكاء الاصطناعي: Fluxo de Trabalho de Is..."},"description":{"en":"Discover how to efficiently manage GitHub issues with the github-issue-workflow skill. Learn to scan, inspect, and resolve issues with ease. Get started now!","zh":"使用 gh 命令行工具来发现和检查 Github 问题，遵循仓库的 issue 开发流程","ja":"gh コマンドラインツールを使用して Github の問題を発見して調査し、リポジトリの issue 開発フローに従う","ko":"gh 명령줄 도구를 사용하여 Github 문제를发现하고 조사하고, 저장소의 이슈 개발 흐름을 따르세요","es":"Aprende a utilizar el flujo de trabajo de issues de Github con comandos deterministas y alineados con la política de ramas y PR","fr":"Découvrez comment utiliser le workflow des issues Github avec des commandes déterministes et alignées sur la politique de branches et PR","de":"Erfahren Sie, wie Sie den Issue-Workflow von Github mit deterministischen Befehlen und einer Ausrichtung auf die Verzweigungs- und PR-Richtlinie nutzen","pt":"Aprenda a configurar o fluxo de trabalho de issues do Github com o comando gh e melhore a produtividade da sua equipe de desenvolvimento","ru":"Узнайте, как настроить workflow Github Issue с помощью команды gh и повысьте производительность вашей команды разработчиков с помощью ИИ Агентов","ar":"تعلم كيفية إعداد Fluxo de Trabalho de Issues do Github باستخدام الأمر gh وزيادة إنتاجية فريق التطوير الخاص بك مع أداة الذكاء الاصطناعي"},"definition":{"en":"github-issue-workflow is a skill that utilizes the `gh` command to discover, inspect, and manage GitHub issues, following a deterministic and policy-compliant approach.","zh":"Github Issue Workflow 是一个使用 gh 命令行工具来管理 Github 问题的工作流程","ja":"Github Issue Workflow は、gh コマンドラインツールを使用して Github の問題を管理するワークフローです","ko":"Github Issue Workflow는 gh 명령줄 도구를 사용하여 Github 문제를 관리하는 워크플로입니다","es":"El flujo de trabajo de issues de Github es un proceso que utiliza `gh` para gestionar y desarrollar issues de manera determinista","fr":"Le workflow des issues Github est un processus qui utilise `gh` pour gérer et développer des issues de manière déterministe","de":"Der Issue-Workflow von Github ist ein Prozess, der `gh` verwendet, um Issues deterministisch zu verwalten und zu entwickeln","pt":"Fluxo de trabalho de issues do Github é um processo que utiliza o comando gh para gerenciar issues no Github","ru":"Workflow Github Issue - это процесс, который использует команду gh для управления issues в Github с помощью ИИ Агентов","ar":"Fluxo de Trabalho de Issues do Github هو عملية تستخدم الأمر gh لإدارة Issues في Github مع أداة الذكاء الاصطناعي"},"features":{"en":["Lists open issues using `gh issue list --state open --limit 200`","Views individual issues with `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`","Displays issue discussions using `gh issue view <issue-number> --comments`","Follows repository-required issue development flow","Prefer deterministic commands for issue management","Keeps work aligned to branch and PR policy"],"zh":["使用 gh issue list 命令列出打开的问题","使用 gh issue view 命令查看单个问题","使用 gh issue view --comments 命令查看问题讨论","遵循仓库的 issue 开发流程","使用 CLI 命令管理 Github 问题","支持查看问题的标题、正文、状态、标签和分配者"],"ja":["gh issue list コマンドを使用してオープン問題をリストする","gh issue view コマンドを使用して個々の問題を表示する","gh issue view --comments コマンドを使用して問題の議論を表示する","リポジトリの issue 開発フローに従う","CLI コマンドを使用して Github の問題を管理する","問題のタイトル、ボディ、状態、ラベル、割り当て者を表示するサポート"],"ko":["gh issue list 명령을 사용하여 열린 문제를 나열합니다","gh issue view 명령을 사용하여 개별 문제를 표시합니다","gh issue view --comments 명령을 사용하여 문제 토론을 표시합니다","저장소의 이슈 개발 흐름을 따릅니다","CLI 명령을 사용하여 Github 문제를 관리합니다","문제의 제목, 본문, 상태, 레이블, 할당자를 표시하는 지원"],"es":["Lista de issues abiertos con `gh issue list --state open --limit 200`","Visualización de un issue con `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`","Visualización de un issue con discusión con `gh issue view <issue-number> --comments`","Seguimiento del flujo de desarrollo de issues requerido por el repositorio","Uso de comandos deterministas para gestionar issues","Alineación con la política de ramas y PR"],"fr":["Liste des issues ouverts avec `gh issue list --state open --limit 200`","Visualisation d''un issue avec `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`","Visualisation d''un issue avec discussion avec `gh issue view <issue-number> --comments`","Suivi du flux de développement d''issues requis par le référentiel","Utilisation de commandes déterministes pour gérer les issues","Alignement sur la politique de branches et PR"],"de":["Liste der offenen Issues mit `gh issue list --state open --limit 200`","Anzeige eines Issues mit `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`","Anzeige eines Issues mit Diskussion mit `gh issue view <issue-number> --comments`","Verfolgung des erforderlichen Issue-Entwicklungsflusses des Repositorys","Verwendung deterministischer Befehle zur Verwaltung von Issues","Ausrichtung auf die Verzweigungs- und PR-Richtlinie"],"pt":["Listar issues abertas com o comando gh issue list","Visualizar uma issue com o comando gh issue view","Visualizar discussões de uma issue com o comando gh issue view --comments","Seguir o fluxo de trabalho de desenvolvimento de issues","Manter o trabalho alinhado com a política de branch e PR"],"ru":["Список открытых issues с помощью команды gh issue list","Просмотр одной issues с помощью команды gh issue view","Просмотр обсуждений одной issues с помощью команды gh issue view --comments","Следование workflow разработки issues с помощью ИИ Агентов","Сохранение работы в соответствии с политикой branch и PR"],"ar":["قائمة Issues المفتوحة باستخدام الأمر gh issue list","مشاهدة Issue واحدة باستخدام الأمر gh issue view","مشاهدة مناقشات Issue واحدة باستخدام الأمر gh issue view --comments","اتباع Fluxo de Trabalho من Issues مع أداة الذكاء الاصطناعي","الحفاظ على العمل متوافقًا مع سياسة الفرع والمراجعة"]},"keywords":{"en":["github-issue-workflow setup guide","how to use github-issue-workflow","github-issue-workflow vs github CLI","github-issue-workflow install","what is github-issue-workflow","github-issue-workflow alternative","github-issue-workflow tutorial","github issue management best practices","github-issue-workflow for AI agents"],"zh":["Github Issue Workflow","gh 命令行工具","Github 问题管理","issue 开发流程","CLI 命令","AIエージェント","Github 工作流程","问题跟踪","版本控制"],"ja":["Github Issue Workflow","gh コマンドラインツール","Github の問題管理","issue 開発フロー","CLI コマンド","AIエージェント","Github ワークフロー","問題追跡","バージョン管理"],"ko":["Github Issue Workflow","gh 명령줄 도구","Github 문제 관리","이슈 개발 흐름","CLI 명령","AI 도구","Github 워크플로","문제 추적","버전 관리"],"es":["github issue workflow","flujo de trabajo de issues de github","gestión de issues","desarrollo de issues","comandos deterministas","política de ramas y PR","herramientas de desarrollo de github","github cli","issues github"],"fr":["github issue workflow","workflow des issues github","gestion des issues","développement d''issues","commandes déterministes","politique de branches et PR","outils de développement github","github cli","issues github"],"de":["github issue workflow","issue-workflow von github","issues verwalten","issues entwickeln","deterministische befehle","verzweigungs- und pr-richtlinie","entwicklungstools von github","github cli","issues github"],"pt":["github issue workflow","comando gh","issues abertas","visualizar issue","fluxo de trabalho de desenvolvimento","política de branch e PR","ferramentas de desenvolvimento","produtividade da equipe"],"ru":["github issue workflow","команда gh","открытые issues","просмотр issues","workflow разработки issues","политика branch и PR","инструменты разработки","производительность команды","ИИ Агенты"],"ar":["github issue workflow","الأمر gh","قائمة Issues المفتوحة","مشاهدة Issue","Fluxo de Trabalho من Issues","سياسة الفرع والمراجعة","أدوات التطوير","إنتاجية الفريق","أداة الذكاء الاصطناعي"]}},"owner":"gordonwatts","repo":"exam-helper","repoPath":"gordonwatts/exam-helper","stars":0,"forks":0,"updatedAt":"2026-03-05T06:37:45Z","topics":[],"category":"community","skillMd":{"name":"github-issue-workflow","description":"Manage GitHub issue execution with `gh` in this repository, including scanning open issues, retrieving issue details, creating issue branches, opening draft PRs, and keeping test/push hygiene. Use when a user asks to work an issue, check issue/PR status, or start/continue issue-driven implementation.","bodyPreview":"# Github Issue Workflow\n\n## Overview\n\nUse `gh` to discover and inspect issues, then follow the repository''s required issue-development flow.\nPrefer deterministic commands and keep work aligned to branch and PR policy.\n\n## Scan And Inspect Issues\n\n- List open issues:\n  - `gh issue list --state open --limit 200`\n- View one issue:\n  - `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`\n- View one issue with discussion:\n  - `gh issue view <issue-number> --comments`\n\nIf","body":"# Github Issue Workflow\n\n## Overview\n\nUse `gh` to discover and inspect issues, then follow the repository''s required issue-development flow.\nPrefer deterministic commands and keep work aligned to branch and PR policy.\n\n## Scan And Inspect Issues\n\n- List open issues:\n  - `gh issue list --state open --limit 200`\n- View one issue:\n  - `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`\n- View one issue with discussion:\n  - `gh issue view <issue-number> --comments`\n\nIf `gh` is unavailable, ask the user to install/authenticate `gh`, then retry the same command.\n\n## Command Playbook\n\nRun these in order for a new issue implementation.\n\n1. Sync `main` first:\n   - `git checkout main`\n   - `git pull --ff-only origin main`\n2. Inspect and confirm target issue:\n   - `gh issue view <issue-number> --json number,title,body,state,labels,assignees,url`\n   - `gh issue view <issue-number> --comments`\n3. Create issue branch before edits:\n   - `git checkout -b issue-<issue-number>-<short-slug>`\n4. Implement changes and run tests:\n   - `uv run --extra dev pytest -q`\n5. Commit and push branch:\n   - `git add -A`\n   - `git commit -m \"<focused-change-message>\"`\n   - `git push -u origin issue-<issue-number>-<short-slug>`\n6. Open draft PR to `main` with auto-close reference:\n   - `gh pr create --base main --head issue-<issue-number>-<short-slug> --draft --title \"<pr-title>\" --body \"fix #<issue-number>\"`\n\n## Start New Issue Checklist\n\n1. Confirm clean context:\n   - Check current branch and status with `git status -sb`.\n2. Scan open issues:\n   - Run `gh issue list --state open --limit 200`.\n3. Load issue details:\n   - Run both `gh issue view <n> --json ...` and `gh issue view <n> --comments`.\n4. Update `main` before branch work:\n   - Run `git checkout main` and `git pull --ff-only origin main`.\n5. Create issue branch before any edits:\n   - Use `git checkout -b issue-<n>-<slug>`.\n6. Start implementation and open draft PR early:\n   - Push and create draft PR as soon as meaningful implementation starts.\n\n## Resume Existing Issue Checklist\n\n1. Verify issue branch exists and switch to it:\n   - `git checkout issue-<issue-number>-<short-slug>`\n2. Refresh issue/PR context:\n   - `gh issue view <issue-number> --comments`\n   - `gh pr status`\n3. Sync from `main` if needed (merge/rebase per repo preference).\n4. Continue implementation on issue branch only.\n5. Run tests before push:\n   - `uv run --extra dev pytest -q`\n6. Push updates and keep PR draft until ready:\n   - `git push`\n   - Mark PR ready only after tests/review items are complete.\n\n## Policy Guardrails\n\n- Do not implement issue work directly on `main`.\n- Do not switch tools if a workflow command fails due to sandbox restrictions; rerun with proper escalation.\n- Keep commits focused and descriptive.\n- Avoid destructive git commands unless explicitly requested.\n- Include issue-closing reference in PR description (for example `fix #123`).\n- If sandbox/network blocks required update commands, request elevated execution and retry.\n\n## Reference\n\nSee `references/agents-github-issue-workflow.md` for the extracted source policy text from this repository''s `AGENTS.md`.\n"},"lastSynced":"2026-03-07T13:11:09.191Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient GitHub issue management using the gh command.","zh":"适用于需要使用 gh 命令高效管理 GitHub 问题的开发代理。","ja":"GitHub の問題を gh コマンドで効率的に管理する必要がある開発エージェントに適しています。","ko":"gh 명령을 사용하여 GitHub 문제를 효율적으로 관리해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión eficiente de problemas de GitHub utilizando el comando gh.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion efficace des problèmes GitHub à l''aide de la commande gh.","de":"Perfekt für Entwicklungsmittel, die eine effiziente GitHub-Problemmgmt mit dem Befehl gh benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento eficiente de problemas do GitHub usando o comando gh.","ru":"Идеально подходит для агентов разработки, которым необходим эффективный менеджмент проблем GitHub с помощью команды gh.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إدارة فعالة لقضايا GitHub باستخدام أمر gh."},"recommendation":{"en":"Empowers agents to streamline issue development flows using deterministic commands like gh issue list and gh issue view, ensuring alignment with repository policies and branch/PR protocols.","zh":"赋予代理人使用确定性命令（如 gh issue list 和 gh issue view）来简化问题开发流程的能力，确保与存储库策略和分支/PR 协议保持一致。","ja":"エージェントが、gh issue list や gh issue view などの決定性コマンドを使用して問題開発フローを合理化し、リポジトリのポリシーやブランチ/PR プロトコルに準拠することを可能にします。","ko":"에이전트가 결정적 명령어(예: gh issue list 및 gh issue view)를 사용하여 문제 개발 흐름을 간소화하고 저장소 정책 및 분기/PR 프로토콜과 일치하도록 하는 기능을 제공합니다.","es":"Permite a los agentes optimizar los flujos de desarrollo de problemas utilizando comandos deterministas como gh issue list y gh issue view, garantizando la alineación con las políticas del repositorio y los protocolos de rama/PR.","fr":"Permet aux agents de rationaliser les flux de développement de problèmes en utilisant des commandes déterministes comme gh issue list et gh issue view, garantissant ainsi l''alignement sur les politiques de référentiel et les protocoles de branche/PR.","de":"Ermöglicht es den Agenten, die Problem-Entwicklungsflüsse mit deterministischen Befehlen wie gh issue list und gh issue view zu optimieren, um die Ausrichtung mit den Repository-Richtlinien und Branch/PR-Protokollen sicherzustellen.","pt":"Habilita os agentes a otimizar os fluxos de desenvolvimento de problemas usando comandos determinísticos, como gh issue list e gh issue view, garantindo alinhamento com as políticas do repositório e os protocolos de branch/PR.","ru":"Наделяет агентов возможностью оптимизировать потоки разработки проблем с помощью детерминированных команд, таких как gh issue list и gh issue view, обеспечивая соответствие политикам репозитория и протоколам branch/PR.","ar":"يمنح الوكيل القدرة على تبسيط تدفقات تطوير المشكلات باستخدام أوامر محددة، مثل gh issue list و gh issue view، مما يضمن الاتساق مع سياسات المستودع وبروتوكولات الفرع / PR."},"useCases":{"en":["Automating issue discovery with gh issue list --state open --limit 200","Inspecting issues with gh issue view <issue-number> --json number,title,body,state,labels,assignees,url","Debugging issue discussions with gh issue view <issue-number> --comments"],"zh":["使用 gh issue list --state open --limit 200 自动发现问题","使用 gh issue view <issue-number> --json number,title,body,state,labels,assignees,url 检查问题","使用 gh issue view <issue-number> --comments 调试问题讨论"],"ja":["gh issue list --state open --limit 200 を使用して問題を自動的に検出する","gh issue view <issue-number> --json number,title,body,state,labels,assignees,url を使用して問題を調査する","gh issue view <issue-number> --comments を使用して問題のディスカッションをデバッグする"],"ko":["gh issue list --state open --limit 200를 사용하여 문제 자동 발견","gh issue view <issue-number> --json number,title,body,state,labels,assignees,url을 사용하여 문제 검토","gh issue view <issue-number> --comments를 사용하여 문제 토론 디버깅"],"es":["Automatizar el descubrimiento de problemas con gh issue list --state open --limit 200","Inspeccionar problemas con gh issue view <issue-number> --json number,título,cuerpo,estado,etiquetas,asignados,url","Depurar discusiones de problemas con gh issue view <issue-number> --comments"],"fr":["Automatiser la découverte de problèmes avec gh issue list --state open --limit 200","Inspecter les problèmes avec gh issue view <issue-number> --json number,titre,corps,état,libellés,affectés,url","Déboguer les discussions de problèmes avec gh issue view <issue-number> --comments"],"de":["Automatisieren der Problemerkennung mit gh issue list --state open --limit 200","Überprüfen von Problemen mit gh issue view <issue-number> --json number,titel,text,zustand,labels,zugewiesen,url","Fehlerbehebung von Problemdiskussionen mit gh issue view <issue-number> --comments"],"pt":["Automatizar a descoberta de problemas com gh issue list --state open --limit 200","Inspecionar problemas com gh issue view <número-do-problema> --json number,title,body,state,labels,assignees,url","Depurar discussões de problemas com gh issue view <número-do-problema> --comments"],"ru":["Автоматизировать обнаружение проблем с помощью gh issue list --state open --limit 200","Осматривать проблемы с помощью gh issue view <номер-проблемы> --json number,title,body,state,labels,assignees,url","Отладить обсуждения проблем с помощью gh issue view <номер-проблемы> --comments"],"ar":["توتير اكتشاف المشكلات مع gh issue list --state open --limit 200","فحص المشكلات مع gh issue view <رقم-المشكلة> --json number,title,body,state,labels,assignees,url","تصحيح أخطاء مناقشات المشكلا